package main

import (
	"fmt"
	"regexp"
	"strings"
)

// =====================================================================
// W9 d1：SQL 基础与 Postgres DDL。
// 今天徒手写 CREATE TABLE，逐个理解每个约束防什么。
//
// 本机没有 Postgres，所以用 Go 把 DDL 逐条「拆开讲」：
// 每个约束用一段代码模拟它会拦住什么数据。
// =====================================================================

// ---- 工具：把 DDL 按语句拆开（模拟 psql 的行为）----

type Column struct {
	Name       string
	Type       string
	Nullable   bool
	Default    string
	PrimaryKey bool
	Unique     bool
	References string
	Check      string
}

type Table struct {
	Name        string
	Schema      string
	Columns     []Column
	Constraints []string
}

func (t Table) DDL() string {
	var b strings.Builder
	b.WriteString(fmt.Sprintf("CREATE TABLE %s.%s (\n", t.Schema, t.Name))
	parts := []string{}
	for _, c := range t.Columns {
		s := "  " + c.Name + " " + c.Type
		if c.PrimaryKey {
			s += " PRIMARY KEY"
		}
		if !c.Nullable {
			s += " NOT NULL"
		}
		if c.Default != "" {
			s += " DEFAULT " + c.Default
		}
		if c.Unique {
			s += " UNIQUE"
		}
		if c.References != "" {
			s += " REFERENCES " + c.References
		}
		if c.Check != "" {
			s += " CHECK (" + c.Check + ")"
		}
		parts = append(parts, s)
	}
	for _, k := range t.Constraints {
		parts = append(parts, "  "+k)
	}
	b.WriteString(strings.Join(parts, ",\n"))
	b.WriteString("\n);")
	return b.String()
}

// ---- 本项目第一张表：finance_category（S3 d21 会建全部 11 张）----

func FinanceCategory() Table {
	return Table{
		Name:   "finance_category",
		Schema: "finance",
		Columns: []Column{
			{Name: "id", Type: "UUID", PrimaryKey: true, Nullable: false},
			{Name: "family_id", Type: "UUID", Nullable: false},
			{Name: "parent_id", Type: "UUID", Nullable: true, References: "finance.finance_category(id)"},
			{Name: "name", Type: "VARCHAR(32)", Nullable: false},
			{Name: "type", Type: "VARCHAR(16)", Nullable: false, Check: "type IN ('expense','income')"},
			{Name: "icon", Type: "VARCHAR(32)", Nullable: false, Default: "'wallet'"},
			{Name: "color", Type: "VARCHAR(9)", Nullable: true},
			{Name: "sort_order", Type: "INTEGER", Nullable: false, Default: "0"},
			{Name: "is_active", Type: "BOOLEAN", Nullable: false, Default: "true"},
			{Name: "version", Type: "INTEGER", Nullable: false, Default: "1"},
			{Name: "deleted_at", Type: "TIMESTAMPTZ", Nullable: true},
			{Name: "deleted_by", Type: "UUID", Nullable: true},
			{Name: "created_at", Type: "TIMESTAMPTZ", Nullable: false, Default: "now()"},
			{Name: "updated_at", Type: "TIMESTAMPTZ", Nullable: false, Default: "now()"},
		},
		Constraints: []string{
			// 同级同名唯一。注意 parent_id 可空时 NULL 不参与唯一性判定 ——
			// 这是 W12 d12 会详细讲的「软删与唯一约束冲突」的第一个伏笔。
			"UNIQUE (family_id, parent_id, name) WHERE deleted_at IS NULL",
			"CHECK (color IS NULL OR color ~ '^#[0-9A-Fa-f]{6}$')",
		},
	}
}

// ---- 一个「行」用来演示约束 ----

type Row map[string]any

func (t Table) Insert(row Row) (bool, string) {
	// 1) NOT NULL
	for _, c := range t.Columns {
		if !c.Nullable {
			v, ok := row[c.Name]
			if !ok || v == nil {
				return false, fmt.Sprintf("null value in column \"%s\" violates not-null constraint", c.Name)
			}
		}
	}
	// 2) PRIMARY KEY
	for _, c := range t.Columns {
		if c.PrimaryKey {
			if row[c.Name] == nil {
				return false, fmt.Sprintf("null value in column \"%s\" violates primary key constraint", c.Name)
			}
		}
	}
	// 3) CHECK（这里只演示 type 和 color 两个）
	for _, c := range t.Columns {
		v, ok := row[c.Name]
		if !ok || v == nil {
			continue
		}
		switch {
		case c.Check == "type IN ('expense','income')":
			s := fmt.Sprintf("%v", v)
			if s != "expense" && s != "income" {
				return false, fmt.Sprintf("new row for relation \"%s\" violates check constraint \"type_check\": %s", t.Name, s)
			}
		case strings.Contains(c.Check, "color"):
			// 正则 CHECK：必须是 #RRGGBB 形式
			s := fmt.Sprintf("%v", v)
			if !regexp.MustCompile(`^#[0-9A-Fa-f]{6}$`).MatchString(s) {
				return false, fmt.Sprintf("new row for relation \"%s\" violates check constraint \"color_check\": %s", t.Name, s)
			}
		}
	}
	// 4) REFERENCES（外键）：这里用「是否存在」模拟
	for _, c := range t.Columns {
		if c.References != "" && row[c.Name] != nil {
			if !existsInRegistry(row) {
				return false, fmt.Sprintf("insert or update on table \"%s\" violates foreign key constraint \"fk_parent\"", t.Name)
			}
		}
	}
	return true, ""
}

// registry 模拟「finance_category 里已存在的行」
var registry = map[string]bool{
	"9f1c0000-0000-4000-8000-000000000001": true,
}

// existsInRegistry 判断 parent_id 是否指向已存在的行

func existsInRegistry(row Row) bool {
	pid, ok := row["parent_id"]
	if !ok || pid == nil {
		return true // 允许为空
	}
	return registry[fmt.Sprintf("%v", pid)]
}

fmt.Println("\n=== 3. 逐条测试约束到底拦什么 ===")
cases := []struct {
	desc string
	row  Row
}{
	{"合法的一级分类", Row{
		"id": "a1", "family_id": "f1", "name": "餐饮", "type": "expense",
		"icon": "wallet", "sort_order": 10, "is_active": true, "version": 1,
		"created_at": "2026-10-15", "updated_at": "2026-10-15",
	}},
	{"漏掉 name（NOT NULL 拦住）", Row{
		"id": "a2", "family_id": "f1", "type": "expense",
		"icon": "wallet", "sort_order": 10, "is_active": true, "version": 1,
		"created_at": "2026-10-15", "updated_at": "2026-10-15",
	}},
	{"type 写成 transfer（CHECK 拦住）", Row{
		"id": "a3", "family_id": "f1", "name": "转账", "type": "transfer",
		"icon": "wallet", "sort_order": 10, "is_active": true, "version": 1,
		"created_at": "2026-10-15", "updated_at": "2026-10-15",
	}},
	{"color 写成红色（CHECK 拦住）", Row{
		"id": "a4", "family_id": "f1", "name": "购物", "type": "expense",
		"icon": "wallet", "color": "红色", "sort_order": 10,
		"is_active": true, "version": 1,
		"created_at": "2026-10-15", "updated_at": "2026-10-15",
	}},
	{"parent_id 指向不存在的分类（外键拦住）", Row{
		"id": "a5", "family_id": "f1", "name": "午餐", "type": "expense",
		"icon": "wallet", "parent_id": "99999999-0000-4000-8000-000000000099",
		"sort_order": 10, "is_active": true, "version": 1,
		"created_at": "2026-10-15", "updated_at": "2026-10-15",
	}},
	{"parent_id 指向存在的分类（合法子分类）", Row{
		"id": "a6", "family_id": "f1", "name": "午餐", "type": "expense",
		"icon": "wallet", "parent_id": "9f1c0000-0000-4000-8000-000000000001",
		"sort_order": 10, "is_active": true, "version": 1,
		"created_at": "2026-10-15", "updated_at": "2026-10-15",
	}},
	{"漏掉 version（NOT NULL 拦住，说明它必须有默认值）", Row{
		"id": "a7", "family_id": "f1", "name": "交通", "type": "expense",
		"icon": "wallet", "sort_order": 10, "is_active": true,
		"created_at": "2026-10-15", "updated_at": "2026-10-15",
	}},
}
for _, c := range cases {
	ok, msg := t.Insert(c.row)
	if ok {
		fmt.Printf("  ✅ %s\n", c.desc)
	} else {
		fmt.Printf("  ❌ %s\n       → %s\n", c.desc, msg)
	}
}

fmt.Println("\n=== 4. 为什么每个约束都要写（不是「能省就省」）===")
rows := []struct{ what, why string }{
	{"NOT NULL", "「这一列必须填」是业务事实。写成可空，然后靠 Go 的 if 判空，判漏一次就写入垃圾数据——而数据库的空值判不出来（NULL 和空字符串在某些比较里相等）"},
	{"DEFAULT", "让老代码不用改就能工作。给 sort_order 一个 0，之前 INSERT 不带这个字段的代码照样跑——这是迁移友好性的关键"},
	{"PRIMARY KEY", "行的身份。S3 d23 乐观锁靠它定位，W11 游标分页靠它做第二排序键，没有它这两件事都做不了"},
	{"UNIQUE", "把「同级不能重名」从应用层搬到数据库层。应用层判重在并发下会失效（两个请求同时查到不存在），唯一索引不会"},
	{"CHECK", "格式类校验放这里最省：color 的正则、type 的枚举。放 Go 里要写一遍、放 SQL 里还要写一遍，迟早不一致"},
	{"REFERENCES", "保证不出现「父分类不存在」的孤儿行。应用层要先查后插，两步之间有竞态；外键是数据库层的原子保证"},
}
for _, r := range rows {
	fmt.Printf("  %-14s %s\n", r.what, r.why)
}

