package main

import (
	"fmt"
	"strings"
)

// =====================================================================
// W9 d2：主键、外键、唯一约束、CHECK 的实际语义。
//
// 今天不讲「是什么」，讲「在什么情况下会给出你意想不到的结果」。
// 四个反直觉点：
//   ① NULL 参与唯一约束时的行为（多行 NULL 互不冲突）
//   ② 外键的默认行为：先删父还是先删子
//   ③ CHECK 里 NULL 的三值逻辑（结果不是 false 就是「未知」）
//   ④ 自引用外键与「只支持两级」的冲突
// =====================================================================

func header(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// ① NULL 与 UNIQUE 的反直觉行为
// =====================================================================

type uniqueCase struct {
	row    [2]any // {family_id, name}
	unique bool
	note   string
}

func testUniqueWithNull() {
	header("① UNIQUE (family_id, parent_id, name) 时 NULL 的行为")

	cases := []uniqueCase{
		{[2]any{"f1", "餐饮"}, true, "第一行"},
		{[2]any{"f1", "餐饮"}, false, "第二行同名 → 冲突"},
		{[2]any{"f2", "餐饮"}, true, "B 家也叫餐饮 → 不冲突（family_id 不同）"},
	}
	for i, c := range cases {
		fmt.Printf("  第%d次插入 %v\n", i+1, c.row)
	}

	fmt.Println("\n  关键结论：Postgres 里 NULL 参与 UNIQUE 时，")
	fmt.Println("  「NULL 等于 NULL」的结果是「未知」而不是「相等」，")
	fmt.Println("  而 UNIQUE 约束只在「相等」时拒绝。所以：")
	fmt.Println()
	fmt.Println("    INSERT 一级分类 '餐饮'      (parent_id = NULL)  → OK")
	fmt.Println("    再插入一级分类 '餐饮'        (parent_id = NULL)  → OK！不冲突")
	fmt.Println("    因为两行的 parent_id 都是 NULL，UNIQUE 判定为「未知」，不拒绝")

	fmt.Println("\n  这意味着：一级分类可以无限重复 —— 「同级同名唯一」这个业务规则")
	fmt.Println("  在一级分类上完全失效！Postgres 默认的多列 UNIQUE 无法区分「都为空」和「都相等」。")

	fmt.Println("\n  三种解法（本项目选第二种）：")
	fmt.Println("  ① COALESCE 把它变成哨兵值：")
	fmt.Println("       ALTER TABLE finance_category")
	fmt.Println("         ADD CONSTRAINT uq_sibling_name")
	fmt.Println("         UNIQUE (family_id, COALESCE(parent_id, '00000000-0000-0000-0000-000000000000'::uuid), name);")
	fmt.Println("     代价：表达式唯一索引不能被 ON CONFLICT(family_id, parent_id, name) 直接命中")
	fmt.Println("  ② 用 Postgres 15+ 的 NULLS NOT DISTINCT：")
	fmt.Println("       UNIQUE NULLS NOT DISTINCT (family_id, parent_id, name)")
	fmt.Println("     这是 15 版新增的，最干净，但要求数据库版本 ≥ 15（本项目就用 15+）")
	fmt.Println("  ③ 拆两张表：一级分类一张、子分类一张，各自在表内唯一（结构改动大，不推荐）")
	fmt.Println()
	fmt.Println("  ★ 本项目选择 ②：tech-plan §2.1 定的是 Postgres 15+，直接用 NULLS NOT DISTINCT")
	fmt.Println("    它保留了三列的形状，所以 ON CONFLICT 依然能精确命中，")
	fmt.Println("    这对 d12 的「软删与唯一约束冲突」和 d23 的 upsert 都很重要")
}

// =====================================================================
// ② 外键的三种删除行为
// =====================================================================

type FKAction struct {
	Name         string
	SQL          string
	DeleteParent string
	Result       string
	ForHomeCube  string
}

func testForeignKey() {
	header("② 外键的三种删除行为")

	actions := []FKAction{
		{
			Name:         "NO ACTION（默认）",
			SQL:          "REFERENCES parent(id)",
			DeleteParent: "DELETE FROM parent WHERE id = 1",
			Result:       "❌ 报错：violates foreign key constraint（父表还有子行）",
			ForHomeCube:  "这是最安全的默认，也是不写 ON DELETE 时的行为",
		},
		{
			Name:         "CASCADE",
			SQL:          "REFERENCES parent(id) ON DELETE CASCADE",
			DeleteParent: "DELETE FROM parent WHERE id = 1",
			Result:       "⚠️  连带删掉所有子行（静默数据丢失）",
			ForHomeCube:  "本项目几乎不用。分类删了，挂在它下面的几千条流水会一起消失",
		},
		{
			Name:         "RESTRICT",
			SQL:          "REFERENCES parent(id) ON DELETE RESTRICT",
			DeleteParent: "DELETE FROM parent WHERE id = 1",
			Result:       "❌ 报错（与 NO ACTION 几乎一样，区别在检查时机）",
			ForHomeCube:  "RESTRICT 立即检查，NO ACTION 延迟到事务末尾检查",
		},
		{
			Name:         "SET NULL",
			SQL:          "REFERENCES parent(id) ON DELETE SET NULL",
			DeleteParent: "DELETE FROM parent WHERE id = 1",
			Result:       "子行的 parent_id 被置为 NULL",
			ForHomeCube:  "要求 parent_id 可空。用于「附件被删但流水还在」这类场景",
		},
	}

	for _, a := range actions {
		fmt.Printf("  %s\n", a.Name)
		fmt.Printf("    定义: %s\n", a.SQL)
		fmt.Printf("    %s\n", a.DeleteParent)
		fmt.Printf("    结果: %s\n", a.Result)
		fmt.Printf("    用法: %s\n\n", a.ForHomeCube)
	}

	fmt.Println("  ★ 本项目的铁律：分类和账户只停用不删除（tech-plan §5.1），")
	fmt.Println("    所以 finance_category.parent_id 用 ON DELETE RESTRICT，")
	fmt.Println("    而 finance_transaction.category_id 用逻辑引用（无物理外键）——")
	fmt.Println("    理由是 tech-plan §7.1 第 ③ 条：跨系统只存对方 id，无物理外键")
}

// =====================================================================
// ③ CHECK 与 NULL 的三值逻辑
// =====================================================================

func testCheckWithNull() {
	header("③ CHECK 里的 NULL：不是 false 就不是「通过」")

	fmt.Println("  CHECK 约束只在表达式结果为 FALSE 时拒绝，为 NULL 时放行。")
	fmt.Println("  （这叫 SQL 的三值逻辑：TRUE / FALSE / UNKNOWN）")
	fmt.Println()

	cases := []struct {
		col     string
		value   string
		expr    string
		eval    string
		verdict string
	}{
		{"amount_cents", "100", "amount_cents > 0", "TRUE", "✅ 通过"},
		{"amount_cents", "-5", "amount_cents > 0", "FALSE", "❌ 被 CHECK 拒绝"},
		{"amount_cents", "NULL", "amount_cents > 0", "NULL（未知）", "✅ 通过（！）"},
		{"name", "NULL", "length(name) <= 32", "NULL（未知）", "✅ 通过（！）"},
		{"name", "工具", "length(name) <= 32", "TRUE", "✅ 通过"},
		{"name", "一二三四五六七八九十十一二", "length(name) <= 32", "FALSE", "❌ 被 CHECK 拒绝"},
	}

	for _, c := range cases {
		fmt.Printf("  %-14s = %-8s  表达式 %-22s → %-12s %s\n", c.col, c.value, c.expr, c.eval, c.verdict)
	}

	fmt.Println("\n  结论：CHECK 不是「校验器」，它是「非空数据的校验器」。")
	fmt.Println("  想让 NULL 也被检查，必须显式写：")
	fmt.Println("    CHECK (amount_cents IS NOT NULL AND amount_cents > 0)")
	fmt.Println("  而更根本的解法是：这个列本来就不该可空 → NOT NULL + CHECK")
	fmt.Println("  （这正是 finance_category.type 和 amount_cents 的写法）")
	fmt.Println()
	fmt.Println("  ★ 真实事故形态：金额列写成可空 + CHECK (amount_cents > 0)，")
	fmt.Println("    某次重构漏了这个字段，INSERT 时它变成 NULL，CHECK 放行，")
	fmt.Println("    于是数据库里出现了一条「金额未知」的流水，报表求和时被当 0 处理")
}

// =====================================================================
// ④ 自引用外键 vs「只支持两级」
// =====================================================================

func testSelfReference() {
	header("④ 自引用外键：它管不了「只支持两级」")

	fmt.Println("  CREATE TABLE 加了 FOREIGN KEY (parent_id) REFERENCES finance_category(id)")
	fmt.Println("  这只保证「父分类存在」，完全不管层级深度。所以：")
	fmt.Println()

	// 构造一棵树
	rows := []struct {
		id       int
		name     string
		parentID int // 0 表示无父
		level    int
	}{
		{1, "餐饮", 0, 1},
		{2, "午餐", 1, 2},
		{3, "工作日午餐", 2, 3}, // 三级！外键不会拦
	}

	for _, r := range rows {
		parent := "-"
		if r.parentID != 0 {
			parent = fmt.Sprintf("id=%d", r.parentID)
		}
		fmt.Printf("  id=%d  %-14s parent=%-8s 层级=%d\n", r.id, r.name, parent, r.level)
	}

	fmt.Println("\n  外键检查：id=3 的 parent_id=2 存在 ✅（但它其实是第三层）")
	fmt.Println()
	fmt.Println("  所以「只支持两级分类」这条规则**必须**在 service 层判：")
	fmt.Println("    ① 查 parent_id 指向的分类存在")
	fmt.Println("    ② 查那个分类的 parent_id 是不是 NULL —— 是的话我是一级，合法；")
	fmt.Println("       不是的话我想建第三级，拒绝（4005）")
	fmt.Println()
	fmt.Println("  ★ 这正是 S2 d6 里 CategoryService.Create 那段代码的逻辑。")
	fmt.Println("    规则属于业务语义（长度会变），就不能靠数据库约束（写死在 schema 里）——")
	fmt.Println("    这是「什么该放数据库、什么该放应用层」的第一个判据。")
}

// =====================================================================
// ⑤ 四种约束的职责划分
// =====================================================================

func testResponsibilitySplit() {
	header("⑤ 判据：什么放数据库约束，什么放应用层")

	rules := []struct{ rule, db, app, judge string }{
		{
			"行不能重复（同一家庭同一父级下分类名唯一）",
			"✅ UNIQUE NULLS NOT DISTINCT",
			"⚠️ 可以提前查给友好提示",
			"唯一性必须数据库兜底：应用层「先查后插」在并发下会失效",
		},
		{
			"父分类必须存在",
			"✅ FOREIGN KEY",
			"⚠️ 需要知道 parent_id 属于哪个家庭（外键不管跨租户）",
			"引用完整性是数据库的事；跨租户一致性是应用的事",
		},
		{
			"金额必须为正",
			"✅ NOT NULL + CHECK (> 0)",
			"✅ 也可以判，但数据库必须有一道",
			"数据不变量就该在数据库；应用层判是为了给友好错误",
		},
		{
			"只支持两级分类",
			"❌ 不能用约束表达",
			"✅ service 层判",
			"层级是可变的业务规则，写进 schema 就等于说「永远两级」",
		},
		{
			"不能删除有流水的账户",
			"❌ 不能用约束表达（跨表计数）",
			"✅ service 层判",
			"约束只能看单行的列，不能「查一下子表有没有行」",
		},
		{
			"分类不能有子分类才能停用",
			"❌ 不能用约束表达",
			"✅ service 层判（d6 的 4004）",
			"同上，跨行判断只能靠触发器或应用层",
		},
	}

	for _, r := range rules {
		fmt.Printf("  规则: %s\n", r.rule)
		fmt.Printf("    数据库: %s\n", r.db)
		fmt.Printf("    应用层: %s\n", r.app)
		fmt.Printf("    判据  : %s\n\n", r.judge)
	}

	fmt.Println("  ★ 一句话判据：约束能表达的是「这一行的这些列之间的关系」，")
	fmt.Println("    表达不了「这一行和其他行的关系」。")
	fmt.Println("    单行 → 数据库；多行 → 应用层（或者触发器，但触发器难调试，本项目不用）。")
}

func main() {
	testUniqueWithNull()
	testForeignKey()
	testCheckWithNull()
	testSelfReference()
	testResponsibilitySplit()

	fmt.Println("\n=== S3 d2 到此结束 ===")
	fmt.Println("今天四个反直觉点里，① UNIQUE 与 NULL 的冲突最贵 ——")
	fmt.Println("它会在 d12（软删与唯一约束）再次出现，而且那里的形态更复杂：")
	fmt.Println("软删的行还占着唯一键，第二次插入会直接失败。")
	fmt.Println("明天讲索引：什么时候需要、复合索引的顺序、EXPLAIN 看执行计划。")
}

