	fmt.Println("  CREATE TABLE 加了 FOREIGN KEY (parent_id) REFERENCES finance_category(id)")
	fmt.Println("  这只保证「父分类存在」，完全不管层级深度。所以：")
	fmt.Println()

	// 构造一棵树
	rows := []struct {
		id       int
		name     string
		parentID int // 0 表示无父
		level    int
	}{
		{1, "餐饮", 0, 1},
		{2, "午餐", 1, 2},
		{3, "工作日午餐", 2, 3}, // 三级！外键不会拦
	}

	for _, r := range rows {
		parent := "-"
		if r.parentID != 0 {
			parent = fmt.Sprintf("id=%d", r.parentID)
		}
		fmt.Printf("  id=%d  %-14s parent=%-8s 层级=%d\n", r.id, r.name, parent, r.level)
	}

	fmt.Println("\n  外键检查：id=3 的 parent_id=2 存在 ✅（但它其实是第三层）")
	fmt.Println()
	fmt.Println("  所以「只支持两级分类」这条规则**必须**在 service 层判：")
	fmt.Println("    ① 查 parent_id 指向的分类存在")
	fmt.Println("    ② 查那个分类的 parent_id 是不是 NULL —— 是的话我是一级，合法；")
	fmt.Println("       不是的话我想建第三级，拒绝（4005）")
	fmt.Println()
	fmt.Println("  ★ 这正是 S2 d6 里 CategoryService.Create 那段代码的逻辑。")
	fmt.Println("    规则属于业务语义（长度会变），就不能靠数据库约束（写死在 schema 里）——")
	fmt.Println("    这是「什么该放数据库、什么该放应用层」的第一个判据。")
}

// =====================================================================
// ⑤ 四种约束的职责划分

// =====================================================================

func testResponsibilitySplit() {
	header("⑤ 判据：什么放数据库约束，什么放应用层")

	rules := []struct{ rule, db, app, judge string }{
		{
			"行不能重复（同一家庭同一父级下分类名唯一）",
			"✅ UNIQUE NULLS NOT DISTINCT",
			"⚠️ 可以提前查给友好提示",
			"唯一性必须数据库兜底：应用层「先查后插」在并发下会失效",
		},
		{
			"父分类必须存在",
			"✅ FOREIGN KEY",
			"⚠️ 需要知道 parent_id 属于哪个家庭（外键不管跨租户）",
			"引用完整性是数据库的事；跨租户一致性是应用的事",
		},
		{
			"金额必须为正",
			"✅ NOT NULL + CHECK (> 0)",
			"✅ 也可以判，但数据库必须有一道",
			"数据不变量就该在数据库；应用层判是为了给友好错误",
		},
		{
			"只支持两级分类",
			"❌ 不能用约束表达",
			"✅ service 层判",
			"层级是可变的业务规则，写进 schema 就等于说「永远两级」",
		},
		{
			"不能删除有流水的账户",
			"❌ 不能用约束表达（跨表计数）",
			"✅ service 层判",
			"约束只能看单行的列，不能「查一下子表有没有行」",
		},
		{
			"分类不能有子分类才能停用",
			"❌ 不能用约束表达",
			"✅ service 层判（d6 的 4004）",
			"同上，跨行判断只能靠触发器或应用层",
		},
	}

	for _, r := range rules {
		fmt.Printf("  规则: %s\n", r.rule)
		fmt.Printf("    数据库: %s\n", r.db)
		fmt.Printf("    应用层: %s\n", r.app)
		fmt.Printf("    判据  : %s\n\n", r.judge)
	}

	fmt.Println("  ★ 一句话判据：约束能表达的是「这一行的这些列之间的关系」，")
	fmt.Println("    表达不了「这一行和其他行的关系」。")
	fmt.Println("    单行 → 数据库；多行 → 应用层（或者触发器，但触发器难调试，本项目不用）。")
}

