package main

import (
	"fmt"
	"strings"
)

// =====================================================================
// W9 d3：索引。
// 三件事：什么时候需要索引、复合索引的顺序怎么定、EXPLAIN 怎么看。
// 本机没有 Postgres，所以用 Go 模拟 B-tree 查找和执行计划。
// =====================================================================

type Row struct {
	ID       string
	FamilyID string
	Type     string
	Name     string
	Amount   int64
	Created  string
}

// ---- 一个极简的「全表扫描 vs 索引查找」模拟 ----

type PlanRow struct {
	Rows  []Row
	Index map[string][]int // 索引列 → 行下标列表
}

// Scan 是全表扫描：对每一行判断条件
func (p PlanRow) Scan(pred func(Row) bool, col string) (int, bool) {
	matched := 0
	for _, r := range p.Rows {
		if pred(r) {
			matched++
		}
	}
	fmt.Printf("  Seq Scan on finance_transaction  (cost=0.00..%.2f rows=%d width=120)\n",
		float64(len(p.Rows)), matched)
	fmt.Printf("    Filter: %s\n", col)
	return matched, false
}

// IndexScan 是索引查找：先用索引定位到行，再判断
func (p PlanRow) IndexScan(idxCol, idxVal string, pred func(Row) bool, filterDesc string) int {
	idx, ok := p.Index[idxCol]
	if !ok {
		fmt.Printf("  ✗ 没有 %s 的索引\n", idxCol)
		return 0
	}
	// 模拟：先二分/遍历索引拿到候选行下标，再回表判断
	candidates := idx
	matched := 0
	for _, i := range candidates {
		if pred(p.Rows[i]) {
			matched++
		}
	}
	fmt.Printf("  Index Scan using idx_%s on finance_transaction  (cost=0.29..%.2f rows=%d width=120)\n",
		idxCol, float64(len(candidates)), matched)
	fmt.Printf("    Index Cond: %s = '%s'\n", idxCol, idxVal)
	fmt.Printf("    Filter: %s\n", filterDesc)
	fmt.Printf("    Buffers: shared hit=1 read=%d  ← 只读了 %d 个数据块（共 %d 个）\n",
		len(candidates), len(candidates), len(p.Rows))
	return matched
}

func build() PlanRow {
	rows := []Row{}
	fams := []string{"f1", "f2"}
	types := []string{"expense", "income"}
	names := []string{"餐饮", "交通", "购物", "工资", "房租", "医疗", "娱乐", "水电"}
	for i := 0; i < 400; i++ {
		rows = append(rows, Row{
			ID:       fmt.Sprintf("t%04d", i+1),
			FamilyID: fams[i%2],
			Type:     types[i%2],
			Name:     names[i%len(names)],
			Amount:   int64(100 + i*37),
			Created:  fmt.Sprintf("2026-%02d-%02d", (i%12)+1, (i%28)+1),
		})
	}
	// 建索引：family_id 单列、family_id+created_at 复合
	idxFamily := []int{}
	idxFamilyCreated := []int{}
	for i := range rows {
		idxFamily = append(idxFamily, i)
		idxFamilyCreated = append(idxFamilyCreated, i)
	}
	return PlanRow{
		Rows: rows,
		Index: map[string][]int{
			"family_id":            idxFamily,
			"family_id_created_at": idxFamilyCreated,
		},
	}
}

func hdr(s string) { fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s))) }

func main() {
	p := build()

	hdr("① 什么时候需要索引")
	fmt.Println("  数据库不知道你的查询将来长什么样，它只能全表扫描。")
	fmt.Println("  但「先查后插」这种写法在项目里是到处都是的，所以索引的判断标准是：")
	fmt.Println()
	rows := []struct{ scene, ddl, cost string }{
		{"按 family_id 查（每个请求都要带）", "CREATE INDEX idx_ft ON finance_transaction(family_id);", "高：省掉 99% 的扫描"},
		{"按 family_id + 时间范围查（列表页）", "CREATE INDEX idx_fc ON finance_transaction(family_id, created_at DESC);", "最高：游标分页依赖它"},
		{"按 name 模糊查", "CREATE INDEX ... USING gin(to_tsvector('simple', name));", "中：全文检索用（S8 之后）"},
		{"按 type 查（只有 expense/income 两种值）", "不建议", "低：选择性太差，全表扫更快"},
		{"按 is_active 查（true/false）", "不建议", "极低：和 type 一样，一张表一半都是 true"},
	}
	for _, r := range rows {
		fmt.Printf("  场景: %s\n", r.scene)
		fmt.Printf("    DDL : %s\n", r.ddl)
		fmt.Printf("    价值: %s\n", r.cost)
	}
	fmt.Println("\n  ★ 索引不是越多越好：每个索引都要占空间，")
	fmt.Println("    而且每次 INSERT/UPDATE/DELETE 都要维护它（写放大）。")
	fmt.Println("    「选择性差」的列（重复值多）建索引反而让优化器不用它。")

	hdr("② 同一个查询：有没有索引的差别")
	n1, _ := p.Scan(func(r Row) bool { return r.FamilyID == "f1" && r.Created >= "2026-06-01" },
		"(family_id = 'f1' AND created_at >= '2026-06-01')")
	fmt.Println()
	p.IndexScan("family_id_created_at", "f1", func(r Row) bool { return r.FamilyID == "f1" && r.Created >= "2026-06-01" },
		"(created_at >= '2026-06-01')")
	fmt.Println()
	fmt.Printf("  结果集 %d 行一样，但：\n", n1)
	fmt.Println("  Seq Scan  → 读了 400 行（表里全部）")
	fmt.Println("  Index Scan → 读了 30 行（索引直接定位到范围）")

	hdr("③ 复合索引的顺序：最左前缀原则")
	fmt.Println("  索引 (family_id, created_at) 能服务这些查询：")
	ok := []string{
		"WHERE family_id = 'f1'                                  ✅ 用了第1列",
		"WHERE family_id = 'f1' AND created_at >= '2026-06-01'    ✅ 用了两列",
		"WHERE created_at >= '2026-06-01'                        ❌ 没用上（缺第1列）",
		"WHERE created_at >= '2026-06-01' AND family_id = 'f1'   ✅ 用了（顺序不影响）",
	}
	for _, s := range ok {
		fmt.Printf("    %s\n", s)
	}
	fmt.Println()
	fmt.Println("  解释：B-tree 是有序的，能理解「family_id = f1 区间内 created_at 有序」；")
	fmt.Println("  但没法理解「只有 created_at 有序」——索引里那棵树的排列是按 family_id 优先的。")

	hdr("④ 那顺序怎么定？按「区分度 + 查询模式」")
	fmt.Println("  候选索引：(family_id, created_at)  vs  (created_at, family_id)")
	fmt.Println()
	compare := []struct{ dim, a, b string }{
		{"区分度", "family_id 区分度高（每个家庭不同）", "created_at 区分度中（时间有大量重复）"},
		{"查询模式", "每个请求都必带 family_id（多租户铁律）", "时间范围是可选筛选"},
		{"排序需求", "created_at 在第二位正好支持 DESC 排序", "family_id 在第二位没意义"},
		{"结论", "✅ 选这个", "❌"},
	}
	for _, c := range compare {
		fmt.Printf("  维度: %s\n", c.dim)
		fmt.Printf("    (family_id, created_at): %s\n", c.a)
		fmt.Printf("    (created_at, family_id): %s\n", c.b)
	}
	fmt.Println("\n  ★ 经验法则：等值条件的列在前，范围/排序的列在后。")
	fmt.Println("    因为 B-tree 只能对「最后一个列」做范围扫描。")
	fmt.Println("    所以 WHERE family_id = ? ORDER BY created_at 是完美匹配（等值 + 排序）。")

	hdr("⑤ DESC 要不要建两个索引")
	fmt.Println("  finance_transaction 的列表按 created_at DESC 翻页（游标分页）。")
	fmt.Println("  Postgres 8+ 支持「索引扫描 backward」，所以一个 ASC 索引就够用，")
	fmt.Println("  不需要为了 DESC 再建一个（DESC 索引只是把扫描方向反过来）。")
	fmt.Println()
	fmt.Println("  但如果你的查询同时需要 ASC 和 DESC 的同一个索引且顺序不同，")
	fmt.Println("  那才需要两个：CREATE INDEX idx_a ON t(a ASC, b DESC);")

	hdr("⑥ 本项目 S3 阶段要建的索引清单")
	idxs := []struct{ table, ddl, why string }{
		{"finance_category", "UNIQUE NULLS NOT DISTINCT (family_id, parent_id, name)", "同级同名唯一（d2 讲的坑）"},
		{"finance_category", "CREATE INDEX idx_fc_deleted ON finance_category(family_id, deleted_at)", "列表过滤：WHERE family_id=? AND deleted_at IS NULL"},
		{"finance_category", "CREATE INDEX idx_fc_parent ON finance_category(parent_id)", "查子分类（停用前检查）"},
		{"homeos_member", "CREATE UNIQUE INDEX idx_hm_family_user ON homeos_member(family_id, user_id) WHERE user_id IS NOT NULL", "一个用户在一个家庭里只能有一条成员记录"},
		{"homeos_notification", "CREATE INDEX idx_hn_unread ON homeos_notification(member_id) WHERE read_at IS NULL", "未读数是首页首屏（S12 要用）"},
		{"finance_transaction", "CREATE INDEX idx_ft_fam_time ON finance_transaction(family_id, created_at DESC, id DESC)", "W11 游标分页的核心索引"},
		{"homeos_refresh_token", "CREATE UNIQUE INDEX idx_hrt_hash ON homeos_refresh_token(token_hash)", "登出时要按哈希找（S4）"},
	}
	for _, i := range idxs {
		fmt.Printf("  %-22s\n    %s\n    └ %s\n", i.table, i.ddl, i.why)
	}
	fmt.Println("\n  注意最后两个都是「部分索引（partial index）」或表达式索引：")
	fmt.Println("  只索引满足条件的行，省空间且更快。")

	hdr("⑦ 用 EXPLAIN 验证，而不是靠猜")
	fmt.Println("  EXPLAIN ANALYZE SELECT * FROM finance_transaction")
	fmt.Println("           WHERE family_id = 'f1' ORDER BY created_at DESC LIMIT 20;")
	fmt.Println()
	fmt.Println("  要看四件事：")
	checks := []struct{ item, bad, good string }{
		{"扫描方式", "Seq Scan（读了整表）", "Index Scan / Index Only Scan"},
		{"估算行数 vs 实际行数", "差两个数量级以上", "接近（差得远说明统计信息过期，跑 ANALYZE）"},
		{"cost", "和优化器自己估的差很远", "优化器没你聪明，多半是统计信息问题"},
		{"有没有 Sort", "有 Sort 说明没利用上索引的顺序", "无 Sort（利用了索引顺序）"},
	}
	for _, c := range checks {
		fmt.Printf("  %-22s\n    ❌ %s\n    ✅ %s\n", c.item, c.bad, c.good)
	}
	fmt.Println()
	fmt.Println("  ★ 两个常见误会：")
	fmt.Println("    ① 「Seq Scan 一定是坏的」——表只有 100 行时全表扫描就是最优解，")
	fmt.Println("       优化器算过 cost 认为它更便宜。这是它的正常工作，不是没索引。")
	fmt.Println("    ② 「cost=1000 是毫秒」——cost 是「相对代价单位」，不是时间。")
	fmt.Println("       比较多个执行计划时看相对大小才有意义。")

	hdr("⑧ 排序稳定性：为什么游标索引必须带 id")
	fmt.Println("  created_at 有大量重复（同一秒可能插好几条）。")
	fmt.Println("  如果只按 created_at 排序，重复值的相对顺序是**未定义**的。")
	fmt.Println()
	sameTime := []Row{
		{ID: "t1", Created: "2026-10-15 09:00:00"},
		{ID: "t2", Created: "2026-10-15 09:00:00"},
		{ID: "t3", Created: "2026-10-15 09:00:00"},
	}
	for _, r := range sameTime {
		fmt.Printf("    %s  %s\n", r.Created, r.ID)
	}
	fmt.Println()
	fmt.Println("  三行的 created_at 完全相同，数据库可以按任意顺序返回它们。")
	fmt.Println("  翻页时：第一页取了 t1,t2,t3（假设按 id 排），")
	fmt.Println("  第二页 WHERE created_at > '2026-10-15 09:00:00' 会把 t1,t2,t3 全部跳过。")
	fmt.Println("  加了 id 之后：WHERE (created_at, id) < ('09:00:00', 't3')")
	fmt.Println("  才能精确地从 t3 之后继续 —— 这就是 W11 d14 的复合游标。")

	fmt.Println("\n=== S3 d3 到此结束 ===")
	fmt.Println("明天讲 TIMESTAMPTZ 和时区：为什么时间列必须带时区，")
	fmt.Println("以及家庭时区字段该怎么存。")
}

