package main

import (
	"fmt"
	"strings"
	"time"
)

// =====================================================================
// W9 d4：时间类型 TIMESTAMPTZ、时区、家庭时区字段。
//
// 三个核心问题：
//   ① TIMESTAMP 和 TIMESTAMPTZ 差一个字母，行为天差地别
//   ② 存「几点几分」还是「2026-10-15」？两者的处理方式完全不同
//   ③ 家庭时区字段存在的意义（跨时区家庭的月末统计）
// =====================================================================

func hdr(s string) { fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s))) }

func main() {
	hdr("① TIMESTAMP vs TIMESTAMPTZ：差一个字母，差 8 小时")

	fmt.Println("  同样存 '2026-10-15 09:00:00+08'，在 TIMESTAMP 列里发生了什么：")
	fmt.Println()
	rows := []struct {
		colType string
		value   string
		stored  string
		note    string
	}{
		{"TIMESTAMP", "2026-10-15 09:00:00+08", "2026-10-15 09:00:00", "+08 被直接丢弃！"},
		{"TIMESTAMP WITH TIME ZONE", "2026-10-15 09:00:00+08", "2026-10-15 01:00:00+00", "转成 UTC 存，读出时按会话时区显示"},
	}
	for _, r := range rows {
		fmt.Printf("  列类型: %s\n", r.colType)
		fmt.Printf("    插入: %s\n", r.value)
		fmt.Printf("    库里存: %s\n", r.stored)
		fmt.Printf("    说明 : %s\n\n", r.note)
	}

	fmt.Println("  ★ 关键差异：TIMESTAMP 不存时区，TIMESTAMPTZ 存「绝对时刻」。")
	fmt.Println("    TIMESTAMPTZ 内部其实也是存 UTC 的 8 字节整数，")
	fmt.Println("    显示时才转成会话时区 —— 所以「它带时区」这个说法是关于行为的，不是关于存储。")
	fmt.Println()
	fmt.Println("  真实事故形态：")
	fmt.Println("    1. 应用服务器在 Asia/Shanghai，写入 '2026-10-15 09:00'")
	fmt.Println("    2. 列类型是 TIMESTAMP（无时区），存下的是 09:00（没转成 UTC）")
	fmt.Println("    3. 应用服务器迁到 UTC，同样的逻辑写入 '2026-10-15 09:00'")
	fmt.Println("    4. 于是库里出现了两个含义不同但值相同的「09:00」")
	fmt.Println("    5. 凌晨对账时，昨天的数据看起来比实际早了 8 小时")

	hdr("② 本项目的口径（tech-plan §5.5）：时间一律 TIMESTAMPTZ")
	fmt.Println("  ✅ 所有时间列用 TIMESTAMPTZ")
	fmt.Println("     created_at / updated_at / deleted_at / occurred_at / due_at / next_at")
	fmt.Println()
	fmt.Println("  ❌ 不用的类型：")
	fmt.Println("     TIMESTAMP（无时区）—— 会丢时区，是本项目明令禁止的")
	fmt.Println("     DATE —— 语义完全不同（见 ③），只在「按天统计」且不需要时区时才用")
	fmt.Println("     TIME —— 家庭记账场景基本不需要「一天内的时刻」")

	hdr("③ 三种时间语义，存法完全不同")
	cases := []struct {
		what    string
		example string
		column  string
		why     string
	}{
		{
			"时刻（这件事什么时候发生的）",
			"2026-10-15 21:30:00+08",
			"TIMESTAMPTZ",
			"带时区，跨时区访问自动正确；moment.js 的那种",
		},
		{
			"日期（哪一天，不关心几点）",
			"2026-10-15",
			"DATE",
			"生日、账期、报表的分桶维度；用 DATE 不要用 TIMESTAMPTZ 截断",
		},
		{
			"时间窗编码（tech-plan §5.5 的五档）",
			"2026-10 / 2026-W42 / 2026-Q4 / 2026",
			"VARCHAR(7) 或按档分开",
			"period 参数的编码；不要试图用时间戳表达「10 月」这个概念",
		},
	}
	for _, c := range cases {
		fmt.Printf("  %s\n", c.what)
		fmt.Printf("    例子  : %s\n", c.example)
		fmt.Printf("    列类型: %s\n", c.column)
		fmt.Printf("    原因  : %s\n\n", c.why)
	}
	fmt.Println("  ★ 关键区分：「这笔账发生在 21:30」是时刻，用 TIMESTAMPTZ；")
	fmt.Println("    「这笔账算在 10 月」是账期，用 VARCHAR 或 DATE。")
	fmt.Println("    混在一起就会出现「21:30 到底属于哪个账期」的问题 ——")
	fmt.Println("    上海晚上 10 点的花费，和伦敦下午 2 点的花费，可能属于不同的月份。")

	hdr("④ 五档时间窗编码（tech-plan §5.5 原文口径）")
	windows := []struct {
		code string
		from string
		to   string
	}{
		{"day", "2026-10-15", "2026-10-15 23:59:59"},
		{"week", "2026-10-12（周一）", "2026-10-18（周日）"},
		{"month", "2026-10-01", "2026-10-31 23:59:59"},
		{"quarter", "2026-10-01", "2026-12-31 23:59:59"},
		{"year", "2026-01-01", "2026-12-31 23:59:59"},
	}
	for _, w := range windows {
		fmt.Printf("  %-8s  %s → %s\n", w.code, w.from, w.to)
	}
	fmt.Println()
	fmt.Println("  ★ 红线：非法编码返回 400，不回落默认档。")
	fmt.Println("    「静默回落」是本项目 tech-plan §5.5 明确禁止的 —— ")
	fmt.Println("    前端传了 period=week 但拼错了，后端默默按 month 算，")
	fmt.Println("    用户看到「这个月的数据」但其实是上周的，还完全不知道。")

	hdr("⑤ 家庭时区字段：为什么 homeos_family 要有 timezone")
	fmt.Println("  场景：一对夫妻，一个在东京一个在伦敦。12 月 31 日 23:30 东京时间，")
	fmt.Println("  伦敦那边已经是 12 月 31 日 15:30 了 —— 这个时间点下，")
	fmt.Println("  「这笔钱算 2026 年还是 2027 年的？」")
	fmt.Println()
	comparison := []struct {
		approach string
		sql      string
		problem  string
	}{
		{
			"❌ 用服务器时区（最常见的错）",
			"SELECT ... WHERE occurred_at >= '2026-01-01' AND occurred_at < '2027-01-01'",
			"取决于服务器部署在哪个时区。迁移机房后历史统计全变",
		},
		{
			"❌ 用客户端时区",
			"前端传 ?tz=Asia/Tokyo 然后拼时间戳",
			"客户端时钟可被篡改；且前端传的时间范围会被信任，存在越权风险",
		},
		{
			"✅ 用家庭时区（HOME 的口径）",
			"WHERE (occurred_at AT TIME ZONE f.timezone) >= '2026-01-01'::date",
			"家庭是记账的单位，用家庭所在地的时区决定账期",
		},
	}
	for _, c := range comparison {
		fmt.Printf("  %s\n", c.approach)
		fmt.Printf("    SQL   : %s\n", c.sql)
		fmt.Printf("    问题  : %s\n\n", c.problem)
	}

	fmt.Println("  ★ homeos_family.timezone 的定义：")
	fmt.Println("    timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Shanghai'")
	fmt.Println("    存 IANA 时区名（如 Asia/Shanghai），不存偏移量（+08:00）")
	fmt.Println()
	fmt.Println("  为什么不存偏移量：")
	offs := []struct {
		zone   string
		offset string
		winter string
		summer string
	}{
		{"Asia/Shanghai", "+08:00", "+08:00", "+08:00"},
		{"Europe/London", "+00:00", "+00:00", "+01:00"},
		{"America/New_York", "-05:00", "-05:00", "-04:00"},
		{"Australia/Sydney", "+10:00", "+11:00", "+10:00"},
	}
	fmt.Printf("  %-20s %-9s %-9s %s\n", "时区名", "冬季偏移", "夏季偏移", "是否需要夏令时")
	for _, o := range offs {
		same := "是"
		if o.winter != o.summer {
			same = "否（会变！）"
		}
		fmt.Printf("  %-20s %-9s %-9s %s\n", o.zone, o.winter, o.summer, same)
	}
	fmt.Println()
	fmt.Println("  存偏移量的话：伦敦的家庭，冬天记 -05:00（纽约的），明年 3 月就错了。")
	fmt.Println("  存 IANA 名字，Postgres 能自己处理夏令时切换。")
	fmt.Println("  对应 Go 侧：time.LoadLocation(\"Europe/London\")，不是 time.FixedZone。")

	hdr("⑥ Go 侧对应写法（这是你每天要写的）")
	snippets := []struct{ what, code string }{
		{
			"从 DB 读（TIMESTAMPTZ → time.Time）",
			"var occurred time.Time\n" +
				"// pq/pgx 自动把 timestamptz 扫成 time.Time（带时区）\n" +
				"err := row.Scan(&occurred)",
		},
		{
			"写入（time.Time → TIMESTAMPTZ）",
			"_, err := db.Exec(\n" +
				"  `INSERT INTO finance_transaction (occurred_at, ...) VALUES ($1, ...)`,\n" +
				"  time.Now(),  // Go 的 time.Now() 自带本地时区信息\n" +
				")\n" +
				"// 不需要手动 Format 成字符串——那会丢时区",
		},
		{
			"按家庭时区算账期",
			"loc, err := time.LoadLocation(family.Timezone)  // 查不到要报错，不能默认 UTC\n" +
				"local := occurred.In(loc)\n" +
				"period := local.Format(\"2006-01\")  // 2026-10",
		},
		{
			"构造「本月」的边界",
			"now := time.Now().In(loc)\n" +
				"y, m, _ := now.Date()\n" +
				"from := time.Date(y, m, 1, 0, 0, 0, 0, loc)\n" +
				"to   := from.AddDate(0, 1, 0)  // 用 AddDate 不要手动加天数",
		},
		{
			"★ 千万别这么写",
			"from := time.Date(y, m, 1, 0, 0, 0, 0, time.UTC)\n" +
				"// ↑ 把家庭时区的时间当成 UTC 比较 → 边界错了最多 1 天",
		},
	}
	for _, s := range snippets {
		fmt.Printf("  %s\n", s.what)
		for _, line := range strings.Split(s.code, "\n") {
			fmt.Printf("    %s\n", line)
		}
		fmt.Println()
	}

	hdr("⑦ 今天容易踩的四个坑")
	pits := []struct{ pit, fix string }{
		{
			"用 TIMESTAMP 而不是 TIMESTAMPTZ",
			"tech-plan §5.5 明确规定一律 TIMESTAMPTZ。DDL review 时专门查一遍",
		},
		{
			"time.Now().Format(\"2006-01-02 15:04:05\") 然后塞进 TIMESTAMPTZ",
			"格式化成字符串就丢了时区信息。直接传 time.Time，让驱动处理",
		},
		{
			"存 \"+08:00\" 这样的固定偏移量",
			"存 IANA 时区名 \"Asia/Shanghai\"，否则夏令时切换后全错",
		},
		{
			"账期边界用 time.UTC 构造",
			"必须用 time.LoadLocation(family.Timezone) 构造，两端用同一个时区",
		},
	}
	for i, p := range pits {
		fmt.Printf("  坑 %d: %s\n", i+1, p.pit)
		fmt.Printf("    改法: %s\n\n", p.fix)
	}

	hdr("⑧ 验证时区行为的一个小实验")
	shanghai, _ := time.LoadLocation("Asia/Shanghai")
	utc := time.UTC
	t1 := time.Date(2026, 10, 15, 9, 0, 0, 0, shanghai)
	t2 := time.Date(2026, 10, 15, 1, 0, 0, 0, utc)
	fmt.Printf("  东京时间 %s\n", t1.Format("2006-01-02 15:04:05 MST"))
	fmt.Printf("  UTC 时间 %s\n", t2.Format("2006-01-02 15:04:05 MST"))
	fmt.Printf("  两者是同一时刻吗: %v\n", t1.Equal(t2))
	fmt.Println()
	fmt.Printf("  在上海时区看 t2: %s\n", t2.In(shanghai).Format("2006-01-02 15:04:05 MST"))
	fmt.Printf("  在 UTC 看 t1   : %s\n", t1.In(utc).Format("2006-01-02 15:04:05 MST"))
	fmt.Println()
	fmt.Println("  同一个 TIMESTAMPTZ 值，读出来时按不同时区显示成不同的墙上时间，")
	fmt.Println("  但它代表的时刻是唯一的 —— 这就是 TIMESTAMPTZ 的正确行为。")

	fmt.Println("\n=== S3 d4 到此结束 ===")
	fmt.Println("明天讲金额列设计：为什么是 *_cents BIGINT 而不是 numeric 或 float，")
	fmt.Println("以及「用整数分」这个决定在 Go/JS 两侧分别要怎么配合。")
}

