// =====================================================================
// W10 d9：GORM 基础 —— 模型定义、自动迁移的隐患、手写 SQL 的边界。
//
// 本机没有 Postgres，所以这里用 GORM 的 DryRun 模式：
// 它会真的跑一遍 GORM 的 SQL 构建流程（方言、标签解析、语句组装），
// 只是不把 SQL 发给数据库。因此下面打印出来的每一句 SQL
// 都是 GORM + postgres 驱动真实生成的结果，不是手写的。
//
// 两个 DryRun 的坑（今天必须知道，否则明天会误解）：
//  ① DryRun 只拦「执行语句」，不拦 gorm.Open 时的连通性探测，
//     所以必须同时设 DisableAutomaticPing: true，否则直接 connection refused。
//  ② DryRun 不能读任何行。所以本文件不演示任何查询结果，
//     只展示「发出去的 SQL 长什么样」——那才是这天的重点。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

// ---- 模型定义：GORM 靠 struct tag 反推列名、类型、约束 ----

type Category struct {
	// gorm:"primaryKey" → 主键。GORM 默认会把字段名 ID 当主键，
	// 但显式写出来更清楚，也让「主键是 UUID 而不是自增整数」这件事在代码里可见。
	ID string `gorm:"primaryKey;type:uuid"`

	// column:family_id —— GORM 会把 FamilyID 单数化成 family_id，
	// 但一旦字段名本身以 s 结尾就会出错（如 Address → addresses）。
	// 显式写 column tag 的真正理由：让 struct 与手写迁移的列名一一对应，
	// 避免「结构 diff 门禁」在 CI 上报出一堆你解释不了的差异。
	FamilyID string `gorm:"column:family_id;type:uuid;not null;index"`

	// VARCHAR 而不是 TEXT：数据库层面挡住超长输入（S3 d1 讲过）。
	Name      string `gorm:"column:name;type:varchar(32);not null"`
	Type      string `gorm:"column:type;type:varchar(16);not null"`
	SortOrder int    `gorm:"column:sort_order;not null;default:0"`

	// 乐观锁。第一行代码就要有（S3 d23 专门讲为什么）。
	// 注意 Go 的 int → GORM 推成 bigint，而你手写的 DDL 写的是 INTEGER。
	// 这是「模型与迁移漂移」的最小例子：两边都能建表，但类型不同。
	Version int `gorm:"column:version;not null;default:1"`

	// 自动软删：只要这个字段在，GORM 的 Delete 就变成 UPDATE deleted_at=now()。
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

// TableName 必须手写。GORM 默认把 Category 变成 categories（复数），
// 但你的表叫 finance_category（单数 + 域前缀）。
// 不写的话 AutoMigrate 会建出一张 categories 表，你的迁移又建一张 —— 两张表。
func (Category) TableName() string { return "finance_category" }

// ---- 只用于 DryRun 的连接 ----

// 固定时间戳。DryRun 模式下 GORM 的软删会把 NowFunc() 的结果写进 SQL，
// 用真实 time.Now() 的话两次运行输出就不同 —— 这正是「输出确定」会踩到的坑。
var fixedNow = time.Date(2026, 10, 15, 9, 30, 0, 0, time.UTC)

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun:               true, // 只构建 SQL，不发送
		DisableAutomaticPing: true,
		NowFunc:              func() time.Time { return fixedNow },
		Logger:               logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		// DryRun + DisableAutomaticPing 下 Open 不会失败。
		// 留着它是因为真库环境下这是第一个要处理的错误。
		panic(err)
	}
	return db
}

// 把 SQL 里的连续空白压成一行，方便对照
func flat(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

func showSQL(title, sql string, vars []any) {
	fmt.Printf("  %s\n", title)
	fmt.Printf("    SQL : %s\n", flat(sql))
	if len(vars) > 0 {
		parts := make([]string, len(vars))
		for i, v := range vars {
			parts[i] = fmt.Sprintf("$%d=%v", i+1, v)
		}
		fmt.Printf("    VAR : %s\n", strings.Join(parts, ", "))
	}
}

func main() {
	db := dryDB()
	d := db.Session(&gorm.Session{DryRun: true})

	fmt.Println("=== 1. 模型 → 表：AutoMigrate 真实生成的 DDL ===")
	// DryRun 下 AutoMigrate 以为表不存在，于是把 CREATE TABLE / CREATE INDEX
	// 直接 fmt.Println 出来（GORM 源码 migrator.go 里的 printSQLLogger 就是干这个的）。
	// 所以下面这几行是 GORM 亲手打印的 DDL，不是我们写的字符串。
	fmt.Println("  （下面三行由 GORM 的 printSQLLogger 直接输出）")
	_ = db.Session(&gorm.Session{DryRun: true}).AutoMigrate(&Category{})
	fmt.Println()
	fmt.Println("  对照 d1 手写的 DDL，三处不一致：")
	fmt.Println("    ① 缺少 schema 前缀 —— GORM 生成 finance_category，")
	fmt.Println("       你的迁移写 finance.finance_category（schema 归属是本项目硬约定）")
	fmt.Println("    ② sort_order / version 变成 bigint —— Go 的 int 默认映射成 bigint，")
	fmt.Println("       而你手写的是 INTEGER。类型不同 = 结构 diff 报差异。")
	fmt.Println("    ③ 唯一索引、CHECK、外键一个都没有 —— AutoMigrate 只认 tag，")
	fmt.Println("       它不知道 finance_category 需要 UNIQUE (family_id, name) WHERE deleted_at IS NULL")

	fmt.Println()
	fmt.Println("=== 2. 五条最常写的语句，GORM 分别生成什么 SQL ===")

	fmt.Println("  ① Create")
	fmt.Printf("    %s\n", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Create(&Category{
			ID:        "11111111-0000-4000-8000-000000000001",
			FamilyID:  "aaaaaaaa-0000-4000-8000-000000000001",
			Name:      "餐饮",
			Type:      "expense",
			SortOrder: 10,
			Version:   1,
		})
	}))

	fmt.Println("  ② Find（列表查询）")
	st := d.Model(&Category{}).
		Where("family_id = ? AND deleted_at IS NULL", "aaaaaaaa-0000-4000-8000-000000000001").
		Order("sort_order ASC, id ASC").
		Limit(20).
		Find(&[]Category{})
	showSQL("", st.Statement.SQL.String(), st.Statement.Vars)
	fmt.Println("    ↑ WHERE 里有两个 deleted_at 条件：一个是我写的，")
	fmt.Println("      一个是 GORM 因为 DeletedAt 字段自动加的。不冲突，但要知道它在。")

	fmt.Println("  ③ First（取单条）")
	st = d.Where("id = ?", "11111111-0000-4000-8000-000000000001").First(&Category{})
	showSQL("", st.Statement.SQL.String(), st.Statement.Vars)
	fmt.Println("    ↑ GORM 自动加了 ORDER BY id LIMIT 1，")
	fmt.Println("      所以 First 的结果依赖主键有序；你传了别的 Order() 它就会用你的。")

	fmt.Println("  ④ Update（带乐观锁）")
	fmt.Printf("    %s\n", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Category{}).
			Where("id = ? AND family_id = ? AND version = ?",
				"11111111-0000-4000-8000-000000000001",
				"aaaaaaaa-0000-4000-8000-000000000001", 1).
			Updates(map[string]any{"name": "餐饮(改)", "version": 2})
	}))

	fmt.Println("  ⑤ Delete（因为有 DeletedAt，自动变软删）")
	fmt.Printf("    %s\n", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Delete(&Category{ID: "11111111-0000-4000-8000-000000000001"})
	}))
	fmt.Println("    Unscoped().Delete 才是真删：")
	fmt.Printf("    %s\n", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Unscoped().Delete(&Category{ID: "11111111-0000-4000-8000-000000000001"})
	}))
	fmt.Println("    ↑ 时间戳被 NowFunc 固定成 " + fixedNow.Format("2006-01-02 15:04:05") +
		"，两次跑完全一样 —— 这就是输出确定的来源。")

	fmt.Println()
	fmt.Println("=== 3. 三处「GORM 猜错了」的地方（模型与迁移对不上的根源）===")
	mismatch := []struct{ what, gormGuess, yourDDL, fix string }{
		{"表名", "categories（复数）", "finance.finance_category（单数+域前缀+schema）",
			"写 TableName() 方法。本项目所有模型的强制要求"},
		{"列类型", "bigint（Go int 的默认映射）", "integer",
			"tag 里写死 type:integer，或者把迁移也改成 bigint —— 两边必须一致"},
		{"索引名", "idx_finance_category_family_id（GORM 拼的）", "idx_fc_family（你自己起的）",
			"indexNames tag 指定名字，或者干脆不让 AutoMigrate 管索引"},
	}
	for _, x := range mismatch {
		fmt.Printf("  %s\n", x.what)
		fmt.Printf("    GORM 认为 : %s\n", x.gormGuess)
		fmt.Printf("    你的 DDL  : %s\n", x.yourDDL)
		fmt.Printf("    修法      : %s\n", x.fix)
	}

	fmt.Println()
	fmt.Println("=== 4. AutoMigrate 的四个隐患（为什么本项目禁用在生产）===")
	risks := []struct{ risk, detail string }{
		{"不会删列", "你从 struct 里删掉一个字段，AutoMigrate 什么也不做。数据库里那列还在，老代码还能写它。这不是 bug 是设计——删列有数据风险。但你必须知道：struct 和表会永久漂移。"},
		{"改类型会重建表", "VARCHAR(32) 想改成 TEXT，AutoMigrate 在 Postgres 上可能走 ALTER ... TYPE，也可能 drop+rename 重建。重建 = 丢索引、丢约束、锁表。生产上这是个事故。"},
		{"新增 NOT NULL 无默认值的列会失败", "struct 里加个 not null 字段，AutoMigrate 生成的 ALTER TABLE ADD COLUMN NOT NULL 在表已有数据时报 column contains null values。它不会帮你填值。"},
		{"不建 CHECK、外键和部分唯一索引", "你 struct 里的 CHECK 约束、外键、partial unique index（WHERE deleted_at IS NULL），AutoMigrate 一个都不建。它只认 tag 里明确写的东西。"},
	}
	for i, x := range risks {
		fmt.Printf("  %d. %s\n", i+1, x.risk)
		fmt.Printf("     %s\n", x.detail)
	}
	fmt.Println()
	fmt.Println("  结论（tech-plan §10.1 第 2 条）：")
	fmt.Println("    开发期可以用 AutoMigrate 快速起步；")
	fmt.Println("    但 schema 的真相只在 server/migrations/ 里；")
	fmt.Println("    结构 diff 门禁会在 CI 上把 AutoMigrate 偷偷改的东西全部暴露出来。")

	fmt.Println()
	fmt.Println("=== 5. 手写 SQL 的边界：什么时候该离开 GORM ===")
	bounds := []struct{ scene, verdict, reason string }{
		{"简单 CRUD", "用 GORM", "样板代码省掉几百行，而且 SQL 形态可预测（上面已经验证过）"},
		{"复杂聚合 / 报表", "用 Raw", "链式 API 表达多表 JOIN + GROUP BY 会很难读，Raw 反而清楚"},
		{"游标分页的元组比较", "Where 字符串 + ? 占位符", "(created_at, id) < (?, ?) 能用 Where 写，但参数必须用 ?，绝不能拼字符串"},
		{"批量 INSERT", "CreateInBatches", "一次 1000 条用 Create 会发 1000 条 INSERT；CreateInBatches(200) 发 5 条"},
		{"行锁 / FOR UPDATE", "clause.Locking", "手写容易忘加表别名，或者忘了它不能和分页一起用"},
	}
	for _, b := range bounds {
		fmt.Printf("  %-26s → %s\n", b.scene, b.verdict)
		fmt.Printf("     %s\n", b.reason)
	}
	fmt.Println()
	fmt.Println("  一条纪律：任何 Raw() 里都不许出现 fmt.Sprintf 拼出来的用户输入。")
	fmt.Println("  GORM 的 ? 占位符会被驱动变成 $1/$2 交给 Postgres 参数化 ——")
	fmt.Println("  这条链路是防 SQL 注入的唯一依靠，绕开它等于开门。")

	fmt.Println()
	fmt.Println("=== 6. 与 Node/JS 生态的对比：为什么 JS 里没有这一环 ===")
	fmt.Println("  ① Node 没有 ORM 的默认选择。前端根本不碰数据库，")
	fmt.Println("     所以 JS 工程师对「schema 是代码之外的契约」这件事没有直觉。")
	fmt.Println("     Go/Java 有静态类型 + 迁移工具传统，schema 从第一天就是显式产物。")
	fmt.Println("  ② Prisma/Knex 大致相当于 GORM + 迁移文件二合一，")
	fmt.Println("     DDL 由 schema.prisma 生成。本项目不同：我们手写 DDL，")
	fmt.Println("     因为 tech-plan 要求 DDL 可读、可审计（门禁要 grep 表名前缀）。")
	fmt.Println("  ③ JS 里 null/undefined 混用，映射到 SQL 的 NULL 时处处是坑；")
	fmt.Println("     Go 里指针字段为 nil ⇔ NULL，非指针零值 ⇔ 0/''，")
	fmt.Println("     所以「这列能不能是 NULL」在 Go 里是类型层面的决定，不是运行时的意外。")
	fmt.Println("     代价：可空列必须用指针（比如 *string），读的时候要判 nil —— 显式的代价。")

	fmt.Println()
	fmt.Println("=== S3 d9 到此结束 ===")
	fmt.Println("明天讲 N+1：为什么「先查列表，再逐条查详情」在 20 条数据时会发 21 条 SQL，")
	fmt.Println("以及 Preload / JOIN / 批量 IN 三种解法各自的真实查询次数（会真跑出数字）。")
}

