	// 乐观锁。第一行代码就要有（S3 d23 专门讲为什么）。
	// 注意 Go 的 int → GORM 推成 bigint，而你手写的 DDL 写的是 INTEGER。
	// 这是「模型与迁移漂移」的最小例子：两边都能建表，但类型不同。
	Version int `gorm:"column:version;not null;default:1"`

	// 自动软删：只要这个字段在，GORM 的 Delete 就变成 UPDATE deleted_at=now()。
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

// TableName 必须手写。GORM 默认把 Category 变成 categories（复数），
// 但你的表叫 finance_category（单数 + 域前缀）。
// 不写的话 AutoMigrate 会建出一张 categories 表，你的迁移又建一张 —— 两张表。
func (Category) TableName() string { return "finance_category" }

// ---- 只用于 DryRun 的连接 ----

// 固定时间戳。DryRun 模式下 GORM 的软删会把 NowFunc() 的结果写进 SQL，
// 用真实 time.Now() 的话两次运行输出就不同 —— 这正是「输出确定」会踩到的坑。
var fixedNow = time.Date(2026, 10, 15, 9, 30, 0, 0, time.UTC)

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun:               true, // 只构建 SQL，不发送
		DisableAutomaticPing: true,
		NowFunc:              func() time.Time { return fixedNow },
		Logger:               logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		// DryRun + DisableAutomaticPing 下 Open 不会失败。
		// 留着它是因为真库环境下这是第一个要处理的错误。
		panic(err)
	}
	return db
}

// 把 SQL 里的连续空白压成一行，方便对照
func flat(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

func showSQL(title, sql string, vars []any) {
	fmt.Printf("  %s\n", title)
	fmt.Printf("    SQL : %s\n", flat(sql))
	if len(vars) > 0 {
		parts := make([]string, len(vars))
		for i, v := range vars {
			parts[i] = fmt.Sprintf("$%d=%v", i+1, v)
		}
		fmt.Printf("    VAR : %s\n", strings.Join(parts, ", "))
	}
}

