// =====================================================================
// W10 d10：GORM 查询与预加载 —— N+1 问题的真实数字。
//
// 本机没有 Postgres，所以分两层演示：
//  A. 查询次数（真跑）：用 GORM 的 callback 数「真的构建/发出了多少条语句」。
//     这些数字是 GORM 自己走完流程后给的，不是估算。
//  B. 代价模型（确定性）：N+1 的伤害不在「单条慢」，而在「往返次数」。
//     内存 map 查找几乎免费，所以拿 slice 计时会得出「预加载反而更慢」
//     这种误导结论 —— 真实世界里每条 SQL 都要付网络往返 + parse/plan 的
//     固定成本。本节用一个**固定的**往返成本把这件事算清楚。
//
// 重要声明：B 节是代价模型，不是实测。S3 第 6 天（D22）你起真库之后，
// 要把同样的 N+1 写法跑在真 SQL 上，用 EXPLAIN (ANALYZE) 数真实的
// 往返与扫描行数。方法完全一样，只是数据来自数据库而不是 slice。
// =====================================================================

package main

import (
	"context"
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

// ---- 模型：一张流水表 + 一张分类表 ----

type Transaction struct {
	ID         string `gorm:"primaryKey;type:uuid"`
	FamilyID   string `gorm:"column:family_id;type:uuid;not null"`
	CategoryID string `gorm:"column:category_id;type:uuid;not null"`
	Amount     int64  `gorm:"column:amount;not null"`
	Note       string `gorm:"column:note;type:varchar(200)"`
	// 关联字段：Preload 就靠它。GORM 通过字段类型推出 Category 表。
	Category *Category `gorm:"foreignKey:CategoryID;references:ID"`
}

func (Transaction) TableName() string { return "finance_transaction" }

type Category struct {
	ID       string `gorm:"primaryKey;type:uuid"`
	FamilyID string `gorm:"column:family_id;type:uuid;not null"`
	Name     string `gorm:"column:name;type:varchar(32);not null"`
	Type     string `gorm:"column:type;type:varchar(16);not null"`
}

func (Category) TableName() string { return "finance_category" }

// ---- 查询计数器：钩在 GORM 的 callback 上，数它真的发了多少条 ----

type queryCounter struct {
	log []string
}

func (c *queryCounter) LogMode(logger.LogLevel) logger.Interface { return c }
func (c *queryCounter) Info(context.Context, string, ...any)     {}
func (c *queryCounter) Warn(context.Context, string, ...any)     {}
func (c *queryCounter) Error(context.Context, string, ...any)    {}
func (c *queryCounter) Trace(_ context.Context, _ time.Time, fc func() (string, int64), _ error) {
	sql, _ := fc()
	c.log = append(c.log, sql)
}

func (c *queryCounter) reset() { c.log = nil }

// ---- DryRun 连接 ----

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun:               true,
		DisableAutomaticPing: true,
		Logger:               logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

// =====================================================================
// B 节：代价模型
//
// 一条 SQL 的固定成本拆成三块（本地 Postgres，同机 unix socket）：
//   网络往返   0.05 ms —— 应用和数据库之间的来回
//   parse/plan 0.08 ms —— 把 SQL 文本变成执行计划
//   执行本身   0.01 ms —— 假设已命中索引，取回 20 行
// 这三个数是「典型量级」的取值，用来把量级讲清楚，不是你机器的实测值。
// 换成远程数据库（网络 0.5ms）只会让结论更极端。
// =====================================================================

const (
	costRoundTrip = 0.05 * float64(time.Millisecond) // 每条 SQL 的往返
	costParsePlan = 0.08 * float64(time.Millisecond) // 每条 SQL 的解析+规划
	costExecute   = 0.01 * float64(time.Millisecond) // 取回 20 行

	// 关联对象的查找在 N+1 里是「另一次完整往返」，
	// 不是本地 map 查找 —— 这是关键差别。
	costPerQuery = costRoundTrip + costParsePlan + costExecute
)

// costOf 返回 n 条 SQL 的总代价（毫秒），保留两位小数
func costOf(n int) float64 {
	ms := float64(n) * costPerQuery / float64(time.Millisecond)
	return float64(int64(ms*100+0.5)) / 100
}

func main() {
	db := dryDB()

	fmt.Println("=== 1. N+1 的定义：查询次数随行数线性增长 ===")
	fmt.Println("  N+1 = 「查一次列表」+ 「每行再查一次关联」")
	fmt.Println("  20 行 → 21 条 SQL，100 行 → 101 条，1000 行 → 1001 条。")
	fmt.Println("  每条 SQL 单独看都很快（走索引，O(log n)），")
	fmt.Println("  致命的不是单条慢，是**往返次数**：1000 次往返光固定成本就")
	fmt.Printf("  就是 %.0f ms，还没算任何实际的数据传输。\n", costOf(1000))

	fmt.Println()
	fmt.Println("=== 2. 三种写法，GORM 分别生成什么 SQL（真实 SQL，来自 DryRun）===")

	fmt.Println("  ① N+1 写法：查列表")
	st := db.Session(&gorm.Session{DryRun: true}).Model(&Transaction{}).
		Where("family_id = ?", famA).
		Order("created_at DESC, id DESC").
		Limit(20).
		Find(&[]Transaction{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))

	fmt.Println("  ② N+1 写法：循环里逐条查分类（第 2..21 条一模一样，只有 $1 不同）")
	st = db.Session(&gorm.Session{DryRun: true}).Where("id = ?", "c01").First(&Category{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))
	fmt.Println("     ↑ 注意它有 ORDER BY id LIMIT 1 —— GORM 的 First 总会加这两个，")
	fmt.Println("       所以 N+1 里的每条关联查询都多了一次排序。这部分开销也是白付的。")

	fmt.Println("  ③ Preload 写法：外层查询不变")
	st = db.Session(&gorm.Session{DryRun: true}).Model(&Transaction{}).
		Where("family_id = ?", famA).
		Order("created_at DESC, id DESC").
		Limit(20).
		Find(&[]Transaction{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))
	fmt.Println("     紧接着 GORM 自动发第二条（Preload 的 IN 查询）：")
	st = db.Session(&gorm.Session{DryRun: true}).Model(&Category{}).
		Where("id IN ?", []string{"c01", "c02", "c03"}).
		Find(&[]Category{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))

	fmt.Println("  ④ JOIN 写法：一条 SQL 出全部字段")
	fmt.Println("     SELECT t.*, c.name AS category_name FROM finance.finance_transaction t")
	fmt.Println("     JOIN finance.finance_category c ON c.id = t.category_id")
	fmt.Println("     WHERE t.family_id = $1 ORDER BY t.created_at DESC, t.id DESC LIMIT $2")

	fmt.Println()
	fmt.Println("  三种写法的查询次数：")
	fmt.Println("    N+1     : 1 + N   条（20 行 = 21 条）")
	fmt.Println("    Preload : 2       条（列表 + IN，与 N 无关）")
	fmt.Println("    JOIN    : 1       条")

	fmt.Println()
	fmt.Println("=== 3. 代价模型：把 N+1 的伤害算成具体毫秒 ===")
	fmt.Println("  每条 SQL 的固定成本（本地 Postgres 的典型量级）：")
	fmt.Printf("    网络往返 %6.0f µs\n", costRoundTrip/float64(time.Microsecond))
	fmt.Printf("    解析规划 %6.0f µs\n", costParsePlan/float64(time.Microsecond))
	fmt.Printf("    执行取回 %6.0f µs\n", costExecute/float64(time.Microsecond))
	fmt.Println("  合计     ", fmt.Sprintf("%6.0f µs", costPerQuery/float64(time.Microsecond)))
	fmt.Println()
	fmt.Println("  关键：这三个成本**和数据量无关**，只和往返次数有关。")
	fmt.Println("  所以「每条都快」并不能救 N+1 —— 次数才是成本的主体。")
	fmt.Println()
	fmt.Printf("  %-8s %-14s %-14s %-16s\n", "行数", "N+1 条数", "预加载条数", "N+1 代价")
	for _, n := range []int{20, 100, 1000} {
		fmt.Printf("  %-8d %-14d %-14d %-16s\n", n, 1+n, 2, fmt.Sprintf("%.1f ms", costOf(1+n)))
	}
	fmt.Println()
	fmt.Println("  同样算一次 JOIN 与 Preload（固定 2 条）：")
	fmt.Printf("    JOIN     %.2f ms\n", costOf(1))
	fmt.Printf("    Preload  %.2f ms\n", costOf(2))
	fmt.Println()
	fmt.Println("  1000 行时，N+1 比 JOIN 慢 " +
		fmt.Sprintf("%.0f 倍", costOf(1001)/costOf(1)) + "。")
	fmt.Println()
	fmt.Println("  如果数据库不在本机（容器网络 / 远程实例），往返从 50µs 涨到 500µs，")
	fmt.Printf("  1000 行的 N+1 就是 %.0f ms —— 而用户点一下「加载更多」只愿意等 100ms。\n",
		costOf(1001)*10)

	fmt.Println()
	fmt.Println("  为什么不用 slice 计时来演示？因为那样测出来的结论是错的：")
	fmt.Println("  Go 的 map 查找是纳秒级，循环里查内存 map 几乎不花时间，")
	fmt.Println("  于是「预加载」反而显得更慢（它多了一次建 map 的开销）。")
	fmt.Println("  这恰恰说明：**内存里的 N+1 不是问题，跨网络的 N+1 才是问题**。")
	fmt.Println("  把「每行查一次」从内存 map 换成网络请求，性质就完全变了。")

	fmt.Println()
	fmt.Println("=== 4. 用 GORM callback 数一遍：Preload 真的构建了几条语句 ===")
	fmt.Println("  上面是模型推算。下面让 GORM 自己走一遍流程，用 Trace callback 数。")
	counter := &queryCounter{}
	db2, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true, Logger: counter,
	})
	if err != nil {
		panic(err)
	}
	dd := db2.Session(&gorm.Session{DryRun: true})

	counter.reset()
	var list []Transaction
	dd.Model(&Transaction{}).Where("family_id = ?", famA).Limit(20).Find(&list)
	fmt.Printf("  不带 Preload：构建 %d 条语句\n", len(counter.log))
	for i, s := range counter.log {
		fmt.Printf("    [%d] %s\n", i+1, flat(s))
	}

	counter.reset()
	var list2 []Transaction
	dd.Model(&Transaction{}).Where("family_id = ?", famA).Limit(20).
		Preload("Category").Find(&list2)
	fmt.Printf("  带 Preload：构建 %d 条语句\n", len(counter.log))
	for i, s := range counter.log {
		fmt.Printf("    [%d] %s\n", i+1, flat(s))
	}
	fmt.Println()
	fmt.Println("  ↑ DryRun 下 Preload 的第二条不会被发出去 —— 因为没有真实行，")
	fmt.Println("    GORM 不知道要预加载哪些 id，也就构造不出 IN 列表。")
	fmt.Println("    真库上它一定发，内容就是上面 ③ 里那条 IN 查询。")
	fmt.Println("    这正是 D22 要在真库上验证的地方。")

	fmt.Println()
	fmt.Println("=== 5. 三种解法的取舍（不是「Preload 永远最好」）===")
	tradeoffs := []struct{ method, queries, good, bad string }{
		{"N+1 逐条查", "1 + N", "代码最直观；只在 N<3 时可接受", "数据量一涨就雪崩；永远不要在循环里查库"},
		{"Preload", "2", "GORM 一行代码搞定；自动把对象图拼好", "关联表很大时会把不需要的列也拉出来；多层嵌套要多次 Preload"},
		{"JOIN", "1", "一次往返，最省；可以只 SELECT 需要的列", "一对多 JOIN 会让行数膨胀（一笔流水 JOIN 20 张发票 = 20 行）；语义比 Preload 复杂"},
		{"批量 IN 手动", "2", "完全可控，可以配合缓存做「查一次用多次」", "要自己收集 id、自己拼装，手写量最大，容易漏掉 family_id"},
	}
	for _, t := range tradeoffs {
		fmt.Printf("  %s（%s 条）\n", t.method, t.queries)
		fmt.Printf("    好 : %s\n", t.good)
		fmt.Printf("    坏 : %s\n", t.bad)
	}
	fmt.Println()
	fmt.Println("  本项目的选择（tech-plan §7）：")
	fmt.Println("    列表页用 JOIN（一次往返 + 只取需要的列）；")
	fmt.Println("    详情页的关联对象用 Preload（对象图完整，代码好读）；")
	fmt.Println("    任何情况下都不允许在 for 循环里发查询 —— 这条要写成 lint 规则。")
	fmt.Println("    特别注意 JOIN 的膨胀：一对多关联要用子查询聚合，")
	fmt.Println("    或者退回 Preload，不要直接 JOIN 完在 Go 里 dedup。")

	fmt.Println()
	fmt.Println("=== 6. 与 JS/前端对比：为什么这个问题在 Node 里更隐蔽 ===")
	fmt.Println("  ① Node 里习惯 Promise.all + map，看起来像「并发所以没问题」，")
	fmt.Println("     其实并发 100 个查询和串行 100 个查询对数据库的压力完全一样，")
	fmt.Println("     而且更容易打爆连接池（pg 默认 max=100，100 个并发正好占满，")
	fmt.Println("     主连接都拿不到）。所以「并发化」不是 N+1 的解法，只是把排队换了个形式。")
	fmt.Println("  ② JS 没有编译期检查，写错字段名（t.categoryId）不会报错，")
	fmt.Println("     运行时是 undefined，map 查不到就跳过 —— 结果是「静默少数据」，")
	fmt.Println("     比 Go 里空指针 panic 更难查。Go 的强类型在这里是优势。")
	fmt.Println("  ③ 前端拿数据常常一次性全取回再在浏览器里 join，")
	fmt.Println("     小数据下没问题；但 S5/S6 接后端后必须改成服务端 join，")
	fmt.Println("     否则流量会被响应体大小拖垮。")
	fmt.Println("     这正是本项目 D22「把内存 store 换成 Postgres」时最容易漏的一步：")
	fmt.Println("     内存 store 里循环查 map 毫无成本，搬进 DB 之后同样的代码就是 N+1。")

	fmt.Println()
	fmt.Println("=== S3 d10 到此结束 ===")
	fmt.Println("明天讲事务：转账为什么必须是一个事务单元，隔离级别怎么选，")
	fmt.Println("以及 rollback 到底回滚了什么（用 Go 模拟账本真跑一遍给你看）。")
}

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

func flat(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

