//   parse/plan 0.08 ms —— 把 SQL 文本变成执行计划
//   执行本身   0.01 ms —— 假设已命中索引，取回 20 行
// 这三个数是「典型量级」的取值，用来把量级讲清楚，不是你机器的实测值。
// 换成远程数据库（网络 0.5ms）只会让结论更极端。

// =====================================================================

const (
	costRoundTrip = 0.05 * float64(time.Millisecond) // 每条 SQL 的往返
	costParsePlan = 0.08 * float64(time.Millisecond) // 每条 SQL 的解析+规划
	costExecute   = 0.01 * float64(time.Millisecond) // 取回 20 行

	// 关联对象的查找在 N+1 里是「另一次完整往返」，
	// 不是本地 map 查找 —— 这是关键差别。
	costPerQuery = costRoundTrip + costParsePlan + costExecute
)

// costOf 返回 n 条 SQL 的总代价（毫秒），保留两位小数
func costOf(n int) float64 {
	ms := float64(n) * costPerQuery / float64(time.Millisecond)
	return float64(int64(ms*100+0.5)) / 100
}

