// =====================================================================
// W11 d11：事务 —— 转账为什么必须是一个事务单元。
//
// 本机没有 Postgres，但事务的本质是**状态的可回滚性**，
// 这件事用纯 Go 的结构体切片就能完整模拟：
//   - 我们自己维护 undo log（Go 里就是记下「改之前长什么样」）
//   - commit = 丢弃 undo log；rollback = 逆序重放
// 这正是数据库事务的实现原理（Postgres 用的是 WAL + MVCC，
// 原理同源，只是 undo 信息存在磁盘上而不是内存里）。
//
// 所以本文件的所有「回滚了什么」都是真跑出来的：账本余额真的变了又变回来。
//
// S3 第 6 天（D22）起真库后，要把同样的转账逻辑跑在真事务上，
// 验证 SERIALIZABLE 下并发转账会不会丢更新（方法见文末）。
// =====================================================================

package main

import (
	"errors"
	"fmt"
	"strings"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

// ---- 模型 ----

type Account struct {
	ID       string `gorm:"primaryKey;type:uuid"`
	FamilyID string `gorm:"column:family_id;type:uuid;not null"`
	Name     string `gorm:"column:name;type:varchar(32);not null"`
	// 金额用整数「分」存储，绝不用浮点 —— 这是 S3 d5 讲过的 money 规则。
	BalanceCents int64 `gorm:"column:balance_cents;not null"`
	Version      int   `gorm:"column:version;not null;default:1"`
}

func (Account) TableName() string { return "finance_account" }

// =====================================================================
// 一个最小的内存事务管理器
// =====================================================================

// undoEntry 记录「这一行改之前是什么样」，回滚时照着恢复
type undoEntry struct {
	accountID string
	before    Account
}

type DB struct {
	accounts map[string]*Account // 主键索引，等价于 Postgres 的 heap + index
	log      []undoEntry         // 未提交事务的 undo log
	inTx     bool
}

func NewDB() *DB {
	return &DB{accounts: map[string]*Account{}}
}

func (db *DB) Insert(a Account) {
	cp := a
	db.accounts[a.ID] = &cp
}

// ---- 事务边界 ----

func (db *DB) Begin() {
	if db.inTx {
		panic("嵌套事务：Go 里没有嵌套事务，需要 SAVEPOINT（GORM 的 SavePoint）")
	}
	db.log = nil
	db.inTx = true
}

func (db *DB) Commit() {
	if !db.inTx {
		panic("没有进行中的事务")
	}
	// 真 Postgres 里 COMMIT 之后数据落 WAL。
	// 内存版没有「落盘」，丢弃 undo log 就等价于提交。
	db.log = nil
	db.inTx = false
}

// Rollback 返回被撤销的修改条数，方便调用方打日志/测试断言
func (db *DB) Rollback() (int, error) {
	if !db.inTx {
		return 0, errors.New("没有进行中的事务")
	}
	// 逆序重放 undo log —— 这是回滚的全部秘密
	for i := len(db.log) - 1; i >= 0; i-- {
		e := db.log[i]
		cp := e.before
		db.accounts[e.accountID] = &cp
	}
	n := len(db.log)
	db.log = nil
	db.inTx = false
	return n, nil
}

// 写操作：先记 undo，再改数据。
// 注意：真实数据库里这条 undo 信息在 WAL 中由数据库自己维护；
// 我们手写它，是为了让你**看见**数据库在替你做的事。
//
// autocommit 语义要模拟对：Postgres 默认 autocommit=on，
// 不显式 BEGIN 时每条语句**自己就是一个事务**，立即生效、无法回滚。
// 所以这里 db.inTx == false 时照样改数据，只是不记 undo log ——
// 因为 autocommit 提交之后就没有「回滚到上一条」的概念了。
func (db *DB) UpdateBalance(id string, delta int64) error {
	a, ok := db.accounts[id]
	if !ok {
		return fmt.Errorf("account %s not found", id)
	}
	// 在事务里 → 记 undo，可回滚；不在事务里 → autocommit，直接生效
	if db.inTx {
		// 深拷贝：否则 undo 记的是同一个指针，改了就失效
		before := *a
		db.log = append(db.log, undoEntry{accountID: id, before: before})
	}

	a.BalanceCents += delta
	a.Version++
	return nil
}

// ---- 余额不变式：任何时候所有账户余额之和必须守恒 ----

func (db *DB) Total() int64 {
	var t int64
	for _, a := range db.accounts {
		t += a.BalanceCents
	}
	return t
}

func (db *DB) Dump(title string) {
	fmt.Printf("  %s\n", title)
	ids := []string{"acc-alice", "acc-bob", "acc-carol"}
	fmt.Printf("    %-12s %-8s %14s %8s\n", "账户", "名字", "余额(元)", "version")
	var sum int64
	for _, id := range ids {
		a := db.accounts[id]
		if a == nil {
			continue
		}
		sum += a.BalanceCents
		fmt.Printf("    %-12s %-8s %14.2f %8d\n", a.ID, a.Name, float64(a.BalanceCents)/100, a.Version)
	}
	fmt.Printf("    %-21s %14.2f\n", "合计", float64(sum)/100)
}

var totalMustStay int64 = 100000 // 1000.00 元 = 100000 分

// checkInvariance 检查**每个账户**的余额，而不只是总额。
//
// 为什么必须逐个账户查：总额守恒是弱不变式 —— 场景一里 Alice 少了 50 元、
// Bob 一分没多，总额恰好还是 1000.00（因为钱确实从系统里消失了，
// 只是「凭空消失」而不是「转移」）。只查总额会漏掉这种错误。
// 强不变式是：Alice 600→550，Bob 300→350，Carol 保持 100。
func checkInvariance(db *DB, when string, want map[string]int64) bool {
	allOK := true
	for _, id := range []string{"acc-alice", "acc-bob", "acc-carol"} {
		got := db.accounts[id].BalanceCents
		exp := want[id]
		if got == exp {
			fmt.Printf("    ✅ %-11s = %8.2f\n", id, float64(got)/100)
		} else {
			fmt.Printf("    ❌ %-11s = %8.2f，应为 %8.2f\n", id, float64(got)/100, float64(exp)/100)
			allOK = false
		}
	}
	fmt.Printf("    总额 = %.2f（%s）\n", float64(db.Total())/100, when)
	if allOK {
		fmt.Printf("    ✅ 状态一致：%s\n", when)
	} else {
		fmt.Printf("    ❌ 状态不一致：%s\n", when)
	}
	return allOK
}

// 期望值表
var (
	wantInitial = map[string]int64{"acc-alice": 60000, "acc-bob": 30000, "acc-carol": 10000}
	// 场景三（事务提交成功）
	wantTransferred = map[string]int64{"acc-alice": 55000, "acc-bob": 35000, "acc-carol": 10000}
)

// =====================================================================
// 业务：转账
// =====================================================================

// transferNoTx 没有事务：先扣 A，再加 B。中间任何一步失败，钱就没了。
func transferNoTx(db *DB, from, to string, cents int64, failAt string) {
	fmt.Println("  写法一：没有事务（危险）")
	db.UpdateBalance(from, -cents) // 先扣
	fmt.Printf("    已扣 %s %.2f\n", db.accounts[from].Name, float64(cents)/100)
	if failAt == "after-debit" {
		fmt.Println("    ✗ 扣款成功后进程崩溃/加款失败 —— 钱凭空消失")
		fmt.Println("      （注意：真实 Postgres 默认 autocommit，这行 UPDATE 已经落库了）")
		// 直接返回，不回滚。这就是线上事故的样子。
		return
	}
	db.UpdateBalance(to, cents)
	fmt.Println("    已加款，转账完成")
}

// transferTx 有事务：任何一步失败都整体回滚
func transferTx(db *DB, from, to string, cents int64, failAt string) error {
	fmt.Println("  写法二：包在事务里（正确）")
	db.Begin()
	if err := db.UpdateBalance(from, -cents); err != nil {
		_, _ = db.Rollback()
		return err
	}
	fmt.Printf("    已扣 %s %.2f\n", db.accounts[from].Name, float64(cents)/100)
	if failAt == "after-debit" {
		fmt.Println("    ✗ 加款前失败 → Rollback")
		reverted, err := db.Rollback()
		if err != nil {
			return err
		}
		fmt.Printf("    回滚了 %d 处修改（undo log 逐条逆放）\n", reverted)
		return errors.New("业务失败：收款账户校验没过")
	}
	if err := db.UpdateBalance(to, cents); err != nil {
		_, _ = db.Rollback()
		return err
	}
	db.Commit()
	fmt.Println("    已加款并 Commit，转账完成")
	return nil
}

// =====================================================================

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		Logger: logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

func seed() *DB {
	db := NewDB()
	db.Insert(Account{ID: "acc-alice", FamilyID: "f1", Name: "Alice", BalanceCents: 60000, Version: 1})
	db.Insert(Account{ID: "acc-bob", FamilyID: "f1", Name: "Bob", BalanceCents: 30000, Version: 1})
	db.Insert(Account{ID: "acc-carol", FamilyID: "f1", Name: "Carol", BalanceCents: 10000, Version: 1})
	return db
}

func main() {
	fmt.Println("=== 1. 转账要满足的两条不变式 ===")
	fmt.Println("  ① 不变式：所有账户余额之和必须守恒（转账是「搬运」不是「创造」）")
	fmt.Println("  ② 原子性：要么全成功，要么全失败，不能停在中间状态")
	fmt.Println("  没有事务时这两条都可能被破坏 —— 下面真跑给你看。")

	fmt.Println()
	fmt.Println("=== 2. 场景一：没有事务，扣款后失败 ===")
	db := seed()
	db.Dump("初始状态：")
	checkInvariance(db, "初始状态", wantInitial)
	fmt.Println()
	transferNoTx(db, "acc-alice", "acc-bob", 5000, "after-debit")
	fmt.Println()
	db.Dump("失败之后：")
	fmt.Println("  对照「正常转账后应该长什么样」：")
	fmt.Println()
	fmt.Printf("    %-12s %14s %14s\n", "账户", "实际", "应该")
	for _, id := range []string{"acc-alice", "acc-bob", "acc-carol"} {
		got := db.accounts[id].BalanceCents
		exp := wantTransferred[id]
		flag := "✅"
		if got != exp {
			flag = "❌"
		}
		fmt.Printf("    %s %-10s %14.2f %14.2f\n", flag, id, float64(got)/100, float64(exp)/100)
	}
	checkInvariance(db, "失败后（应回到初始值）", wantInitial)
	fmt.Println()
	fmt.Println("  ❌ 5000 分（50 元）凭空消失了：Alice 少了，Bob 没多。")
	fmt.Println("     注意总额从 1000.00 变成了 950.00 —— 弱不变式（总额守恒）")
	fmt.Println("     在这里居然也被破坏了，因为它根本不是「转移」，是「销毁」。")
	fmt.Println()
	fmt.Println("     这就是「转账必须是一个事务单元」的真正原因：")
	fmt.Println("     任何两个写操作之间都可能失败，而失败时必须有办法恢复到一致状态。")

	fmt.Println()
	fmt.Println("=== 3. 场景二：包进事务，同样的失败点 ===")
	db2 := seed()
	db2.Dump("初始状态：")
	checkInvariance(db2, "初始状态", wantInitial)
	fmt.Println()
	err := transferTx(db2, "acc-alice", "acc-bob", 5000, "after-debit")
	fmt.Printf("    业务返回错误：%v\n", err)
	fmt.Println()
	db2.Dump("回滚之后：")
	checkInvariance(db2, "回滚后（应回到初始值）", wantInitial)
	fmt.Println()
	fmt.Println("  ✅ 余额完全回到初始值。undo log 里有 1 条记录，被逆序重放了 1 次。")

	fmt.Println()
	fmt.Println("  顺带看一下 version 列发生了什么：")
	fmt.Println("    Rollback 之后 Alice 的 version 仍然是 1 ——")
	fmt.Println("    因为 version 也在 undo log 里，一起被恢复了。")
	fmt.Println("    这点很重要：乐观锁的计数器必须和业务字段在同一个事务里改，")
	fmt.Println("    否则回滚之后 version 前进了一格，数据却没变 —— 下次更新会莫名冲突。")

	fmt.Println()
	fmt.Println("=== 4. 场景三：事务正常提交 ===")
	db3 := seed()
	fmt.Println()
	_ = transferTx(db3, "acc-alice", "acc-bob", 5000, "")
	fmt.Println()
	db3.Dump("提交之后：")
	checkInvariance(db3, "提交后（应完成转移）", wantTransferred)
	fmt.Printf("    Alice version 1 → %d，Bob version 1 → %d\n",
		db3.accounts["acc-alice"].Version, db3.accounts["acc-bob"].Version)

	fmt.Println()
	fmt.Println("=== 5. 回滚到底回滚了什么：看 undo log 的内容 ===")
	db4 := seed()
	db4.Begin()
	_ = db4.UpdateBalance("acc-alice", -20000)
	_ = db4.UpdateBalance("acc-bob", +12000)
	_ = db4.UpdateBalance("acc-carol", +8000)
	fmt.Printf("  事务内改了 3 行，undo log 里有 %d 条：\n", len(db4.log))
	for i, e := range db4.log {
		fmt.Printf("    [%d] %-11s 余额 %7d → %7d（记的是改之前的值）\n",
			i+1, e.accountID, e.before.BalanceCents, db4.accounts[e.accountID].BalanceCents)
	}
	fmt.Println()
	fmt.Printf("  事务内的中间状态总额 = %.2f（守恒，因为三笔一起改）\n", float64(db4.Total())/100)
	if n, err := db4.Rollback(); err == nil {
		fmt.Printf("  Rollback() 报告撤销了 %d 处修改\n", n)
	}
	fmt.Println()
	fmt.Printf("  回滚后 undo log 清空（len=%d），总额 = %.2f\n", len(db4.log), float64(db4.Total())/100)
	fmt.Println()
	fmt.Println("  注意「记的是改之前的值」这一点：如果 undo log 记的是「改成什么」，")
	fmt.Println("  回滚就会把状态改成目标值 —— 恰好相反。所以 undo log 必须是 before 快照。")
	fmt.Println("  Postgres 用的是同样的思路，只是把 before 存在 WAL 里，")
	fmt.Println("  而且用 MVCC 让读者看到的是旧版本，不阻塞写入。")

	fmt.Println()
	fmt.Println("=== 6. GORM 里怎么写事务（真实 SQL）===")
	dbg := dryDB()
	fmt.Println("  ① Begin")
	fmt.Printf("     %s\n", dbg.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Exec("BEGIN")
	}))
	fmt.Println("  ② 转账的两条 UPDATE（第二条带乐观锁）")
	fmt.Printf("     %s\n", dbg.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Account{}).
			Where("id = ? AND family_id = ? AND version = ?", "acc-alice", "f1", 1).
			Update("balance_cents", gorm.Expr("balance_cents - ?", 5000))
	}))
	fmt.Printf("     %s\n", dbg.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Account{}).
			Where("id = ? AND family_id = ? AND version = ?", "acc-bob", "f1", 1).
			Update("balance_cents", gorm.Expr("balance_cents + ?", 5000))
	}))
	fmt.Println("  ③ Commit / Rollback")
	fmt.Printf("     %s\n", dbg.ToSQL(func(tx *gorm.DB) *gorm.DB { return tx.Exec("COMMIT") }))
	fmt.Printf("     %s\n", dbg.ToSQL(func(tx *gorm.DB) *gorm.DB { return tx.Exec("ROLLBACK") }))

	fmt.Println()
	fmt.Println("  GORM 的事务写法：")
	fmt.Println("    err := db.Transaction(func(tx *gorm.DB) error {")
	fmt.Println("        // 这里面用 tx，不要用外层的 db —— 用错了就不在同一个事务里")
	fmt.Println("        if err := tx.Where(...).Update(...).Error; err != nil {")
	fmt.Println("            return err   // 返回 error → GORM 自动 Rollback")
	fmt.Println("        }")
	fmt.Println("        return nil      // 返回 nil → GORM 自动 Commit")
	fmt.Println("    })")
	fmt.Println()
	fmt.Println("  ⚠️ 最常见的两个错：")
	fmt.Println("     ① 事务闭包里用了外层 db（不是 tx）—— 那条语句在事务外跑，")
	fmt.Println("        Commit 了但它不在事务里，于是「以为是一个事务」实际不是。")
	fmt.Println("     ② 事务里做了网络调用（发通知、调第三方 API）—— 网络超时会让事务")
	fmt.Println("        长时间挂住，锁住行。正确做法是：事务内只碰数据库，")
	fmt.Println("        提交成功之后再发通知。")

	fmt.Println()
	fmt.Println("=== 7. 隔离级别：并发转账会不会丢更新 ===")
	fmt.Println("  两个事务同时给 Alice 扣钱，各扣 100 元。")
	fmt.Println()
	fmt.Println("  Read Committed（Postgres 默认）：")
	fmt.Println("    T1: SELECT balance → 600.00")
	fmt.Println("    T2: SELECT balance → 600.00   ← T1 还没提交，T2 读到旧值")
	fmt.Println("    T1: UPDATE balance = 600-100 = 500  （提交）")
	fmt.Println("    T2: UPDATE balance = 600-100 = 500  ← 用的是它读到的旧值！")
	fmt.Println("    结果 = 500.00，只扣了一次 100 元 —— **丢更新**")
	fmt.Println()
	fmt.Println("  Repeatable Read：")
	fmt.Println("    T2 的 UPDATE 会等待 T1 提交，然后基于**最新版本**重新计算，")
	fmt.Println("    结果 = 400.00，两次都生效。Postgres 的 RR 是靠「读到的行加锁」实现的。")
	fmt.Println()
	fmt.Println("  Serializable：")
	fmt.Println("    最严格，任何执行顺序都不能产生异常，代价是冲突时直接报错。")
	fmt.Println("    Postgres 的实现方式是 SSI（可串行化快照隔离），")
	fmt.Println("    表现为提交时抛 SQLSTATE 40001 serialization_failure，应用需要重试。")
	fmt.Println()
	fmt.Println("  本项目的选择（tech-plan §10.1）：")
	fmt.Println("    读多写少（记账列表、统计）→ Read Committed 默认级别，够用且最快")
	fmt.Println("    涉及余额扣减的写路径（转账、周期记账扣预算）→ SERIALIZABLE")
	fmt.Println("    更简单也更常见的做法：给 UPDATE 加上 version 条件（乐观锁），")
	fmt.Println("    靠 RowsAffected == 0 判断冲突并返回 409。这样就不依赖隔离级别，")
	fmt.Println("    在任何级别下都正确 —— D23 会完整演示。")

	fmt.Println()
	fmt.Println("=== 8. 死锁：两个事务以相反顺序加锁 ===")
	fmt.Println("  T1: BEGIN; UPDATE alice; UPDATE bob;  COMMIT")
	fmt.Println("  T2: BEGIN; UPDATE bob;   UPDATE alice; COMMIT")
	fmt.Println("  → T1 持有 alice 锁等 bob，T2 持有 bob 锁等 alice → 死锁")
	fmt.Println()
	fmt.Println("  Postgres 检测到死锁后，会**主动回滚其中一个事务**并报：")
	fmt.Println("    ERROR: deadlock detected")
	fmt.Println("    DETAIL: Process 1234 waits for ShareLock on transaction 5678;")
	fmt.Println("            Process 5678 waits for ShareLock on transaction 1234.")
	fmt.Println()
	fmt.Println("  预防办法（本项目采用第 1 条）：")
	fmt.Println("    ① 全局统一加锁顺序：所有转账都按 account_id 从小到大加锁。")
	fmt.Println("       这需要业务上先把两个 id 排序 —— 代码里 sort.Strings([from, to])。")
	fmt.Println("    ② 缩短事务：事务里不做网络调用，不做大计算。")
	fmt.Println("    ③ 应用层加重试：捕获 40001 和 40P01（死锁）后重试 2-3 次。")
	fmt.Println("       重试必须有上限，否则在持续冲突时会把数据库压垮。")

	fmt.Println()
	fmt.Println("=== 9. 与 Node/JS 对比 ===")
	fmt.Println("  ① node-postgres（pg）的 client.query() 不自动开事务，")
	fmt.Println("     显式写 BEGIN/COMMIT。如果你在中间漏写 ROLLBACK，")
	fmt.Println("     连接归还池池时 pg 会自动 rollback —— 这算是个保护。")
	fmt.Println("     但更常见的问题是「忘了 BEGIN」，于是两条 UPDATE 各自自动提交，")
	fmt.Println("     和上面的场景一完全一样。Knex/Prisma 的 transaction() 帮你处理了这个。")
	fmt.Println("  ② JS 没有编译期检查，事务闭包里不小心用了另一个 client，")
	fmt.Println("     不会有任何警告。GORM 用 tx 参数传递，编译器能帮你抓一部分 ——")
	fmt.Println("     比如把 tx 定义成参数，闭包里用错变量更容易被看出来。")
	fmt.Println("  ③ JS 的 async/await 让人容易忘记「Promise.all 里的多个查询")
	fmt.Println("     可能不在同一事务里」—— 除非你显式传同一个 client。")
	fmt.Println("     Go 的 tx 是一个普通的值，你不传它就没法用，这反而是好事。")

	fmt.Println()
	fmt.Println("=== S3 d11 到此结束 ===")
	fmt.Println("明天讲软删与唯一约束的冲突：删掉的行还占着唯一键，")
	fmt.Println("第二次插入同名分类会失败 —— 本项目最真实的一个事故点，会真跑出失败。")
}

func flat(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

