// =====================================================================
// W11 d11：事务 —— 转账为什么必须是一个事务单元。
//
// 本机没有 Postgres，但事务的本质是**状态的可回滚性**，
// 这件事用纯 Go 的结构体切片就能完整模拟：
//   - 我们自己维护 undo log（Go 里就是记下「改之前长什么样」）
//   - commit = 丢弃 undo log；rollback = 逆序重放
// 这正是数据库事务的实现原理（Postgres 用的是 WAL + MVCC，
// 原理同源，只是 undo 信息存在磁盘上而不是内存里）。
//
// 所以本文件的所有「回滚了什么」都是真跑出来的：账本余额真的变了又变回来。
//
// S3 第 6 天（D22）起真库后，要把同样的转账逻辑跑在真事务上，
// 验证 SERIALIZABLE 下并发转账会不会丢更新（方法见文末）。
// =====================================================================

package main

import (
	"errors"
	"fmt"
	"strings"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

// ---- 模型 ----

type Account struct {
	ID       string `gorm:"primaryKey;type:uuid"`
	FamilyID string `gorm:"column:family_id;type:uuid;not null"`
	Name     string `gorm:"column:name;type:varchar(32);not null"`
	// 金额用整数「分」存储，绝不用浮点 —— 这是 S3 d5 讲过的 money 规则。
	BalanceCents int64 `gorm:"column:balance_cents;not null"`
	Version      int   `gorm:"column:version;not null;default:1"`
}

func (Account) TableName() string { return "finance_account" }

// =====================================================================
// 一个最小的内存事务管理器
// =====================================================================

// undoEntry 记录「这一行改之前是什么样」，回滚时照着恢复
type undoEntry struct {
	accountID string
	before    Account
}

type DB struct {
	accounts map[string]*Account // 主键索引，等价于 Postgres 的 heap + index
	log      []undoEntry         // 未提交事务的 undo log
	inTx     bool
}

func NewDB() *DB {
	return &DB{accounts: map[string]*Account{}}
}

func (db *DB) Insert(a Account) {
	cp := a
	db.accounts[a.ID] = &cp
}

// ---- 事务边界 ----

func (db *DB) Begin() {
	if db.inTx {
		panic("嵌套事务：Go 里没有嵌套事务，需要 SAVEPOINT（GORM 的 SavePoint）")
	}
	db.log = nil
	db.inTx = true
}

func (db *DB) Commit() {
	if !db.inTx {
		panic("没有进行中的事务")
	}
	// 真 Postgres 里 COMMIT 之后数据落 WAL。
	// 内存版没有「落盘」，丢弃 undo log 就等价于提交。
	db.log = nil
	db.inTx = false
}

// Rollback 返回被撤销的修改条数，方便调用方打日志/测试断言

func (db *DB) Rollback() (int, error) {
	if !db.inTx {
		return 0, errors.New("没有进行中的事务")
	}
	// 逆序重放 undo log —— 这是回滚的全部秘密
	for i := len(db.log) - 1; i >= 0; i-- {
		e := db.log[i]
		cp := e.before
		db.accounts[e.accountID] = &cp
	}
	n := len(db.log)
	db.log = nil
	db.inTx = false
	return n, nil
}

// 写操作：先记 undo，再改数据。
// 注意：真实数据库里这条 undo 信息在 WAL 中由数据库自己维护；
// 我们手写它，是为了让你**看见**数据库在替你做的事。
//
// autocommit 语义要模拟对：Postgres 默认 autocommit=on，
// 不显式 BEGIN 时每条语句**自己就是一个事务**，立即生效、无法回滚。
// 所以这里 db.inTx == false 时照样改数据，只是不记 undo log ——
// 因为 autocommit 提交之后就没有「回滚到上一条」的概念了。
func (db *DB) UpdateBalance(id string, delta int64) error {
	a, ok := db.accounts[id]
	if !ok {
		return fmt.Errorf("account %s not found", id)
	}
	// 在事务里 → 记 undo，可回滚；不在事务里 → autocommit，直接生效
	if db.inTx {
		// 深拷贝：否则 undo 记的是同一个指针，改了就失效
		before := *a
		db.log = append(db.log, undoEntry{accountID: id, before: before})
	}

	a.BalanceCents += delta
	a.Version++
	return nil
}

// ---- 余额不变式：任何时候所有账户余额之和必须守恒 ----

func (db *DB) Total() int64 {
	var t int64
	for _, a := range db.accounts {
		t += a.BalanceCents
	}
	return t
}

func (db *DB) Dump(title string) {
	fmt.Printf("  %s\n", title)
	ids := []string{"acc-alice", "acc-bob", "acc-carol"}
	fmt.Printf("    %-12s %-8s %14s %8s\n", "账户", "名字", "余额(元)", "version")
	var sum int64
	for _, id := range ids {
		a := db.accounts[id]
		if a == nil {
			continue
		}
		sum += a.BalanceCents
		fmt.Printf("    %-12s %-8s %14.2f %8d\n", a.ID, a.Name, float64(a.BalanceCents)/100, a.Version)
	}
	fmt.Printf("    %-21s %14.2f\n", "合计", float64(sum)/100)
}

var totalMustStay int64 = 100000 // 1000.00 元 = 100000 分

// checkInvariance 检查**每个账户**的余额，而不只是总额。
//
// 为什么必须逐个账户查：总额守恒是弱不变式 —— 场景一里 Alice 少了 50 元、
// Bob 一分没多，总额恰好还是 1000.00（因为钱确实从系统里消失了，
// 只是「凭空消失」而不是「转移」）。只查总额会漏掉这种错误。
// 强不变式是：Alice 600→550，Bob 300→350，Carol 保持 100。
func checkInvariance(db *DB, when string, want map[string]int64) bool {
	allOK := true
	for _, id := range []string{"acc-alice", "acc-bob", "acc-carol"} {
		got := db.accounts[id].BalanceCents
		exp := want[id]
		if got == exp {
			fmt.Printf("    ✅ %-11s = %8.2f\n", id, float64(got)/100)
		} else {
			fmt.Printf("    ❌ %-11s = %8.2f，应为 %8.2f\n", id, float64(got)/100, float64(exp)/100)
			allOK = false
		}
	}
	fmt.Printf("    总额 = %.2f（%s）\n", float64(db.Total())/100, when)
	if allOK {
		fmt.Printf("    ✅ 状态一致：%s\n", when)
	} else {
		fmt.Printf("    ❌ 状态不一致：%s\n", when)
	}
	return allOK
}

// 期望值表
var (
	wantInitial = map[string]int64{"acc-alice": 60000, "acc-bob": 30000, "acc-carol": 10000}
	// 场景三（事务提交成功）
	wantTransferred = map[string]int64{"acc-alice": 55000, "acc-bob": 35000, "acc-carol": 10000}
)

// =====================================================================
// 业务：转账

// =====================================================================

// transferNoTx 没有事务：先扣 A，再加 B。中间任何一步失败，钱就没了。
func transferNoTx(db *DB, from, to string, cents int64, failAt string) {
	fmt.Println("  写法一：没有事务（危险）")
	db.UpdateBalance(from, -cents) // 先扣
	fmt.Printf("    已扣 %s %.2f\n", db.accounts[from].Name, float64(cents)/100)
	if failAt == "after-debit" {
		fmt.Println("    ✗ 扣款成功后进程崩溃/加款失败 —— 钱凭空消失")
		fmt.Println("      （注意：真实 Postgres 默认 autocommit，这行 UPDATE 已经落库了）")
		// 直接返回，不回滚。这就是线上事故的样子。
		return
	}
	db.UpdateBalance(to, cents)
	fmt.Println("    已加款，转账完成")
}

// transferTx 有事务：任何一步失败都整体回滚
func transferTx(db *DB, from, to string, cents int64, failAt string) error {
	fmt.Println("  写法二：包在事务里（正确）")
	db.Begin()
	if err := db.UpdateBalance(from, -cents); err != nil {
		_, _ = db.Rollback()
		return err
	}
	fmt.Printf("    已扣 %s %.2f\n", db.accounts[from].Name, float64(cents)/100)
	if failAt == "after-debit" {
		fmt.Println("    ✗ 加款前失败 → Rollback")
		reverted, err := db.Rollback()
		if err != nil {
			return err
		}
		fmt.Printf("    回滚了 %d 处修改（undo log 逐条逆放）\n", reverted)
		return errors.New("业务失败：收款账户校验没过")
	}
	if err := db.UpdateBalance(to, cents); err != nil {
		_, _ = db.Rollback()
		return err
	}
	db.Commit()
	fmt.Println("    已加款并 Commit，转账完成")
	return nil
}

