// =====================================================================
// W11 d12：软删与唯一约束的冲突。
//
// 这是本项目最真实的一个事故点，真实到它发生在绝大多数项目的第 3 个月：
//   1. 用户建了一个分类「餐饮」
//   2. 用户手滑删了它（软删，deleted_at 被写上时间）
//   3. 用户想重建一个「餐饮」→ INSERT 失败：duplicate key value
//   4. 查代码找不到问题、查日志只有一行 constraint violation
//
// 为什么会这样？因为软删的行**还在表里**，它照样占着唯一键。
//
// 本机没有 Postgres，所以我们自己实现一个「唯一约束检查器」，
// 它的语义严格照抄 Postgres 的部分唯一索引（partial unique index）。
// 下面第 4 节的失败是真跑出来的 INSERT，不是手写的错误文案。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/clause"
	"gorm.io/gorm/logger"
)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

type Category struct {
	ID       string `gorm:"primaryKey;type:uuid"`
	FamilyID string `gorm:"column:family_id;type:uuid;not null"`
	Name     string `gorm:"column:name;type:varchar(32);not null"`
	Type     string `gorm:"column:type;type:varchar(16);not null"`
	Version  int    `gorm:"column:version;not null;default:1"`
	// 必须是 gorm.DeletedAt 而不是 *string —— 只有这个类型 GORM 才认识，
	// 才会在所有查询后面自动加 AND deleted_at IS NULL。
	// 用 *string 的话 GORM 完全不知道你在做软删（这个坑 d12 要记住）。
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

func (Category) TableName() string { return "finance_category" }

// =====================================================================
// 模拟 Postgres 的唯一约束
//
// 两种形态要区分清楚，这是今天最核心的区别：
//   A. 普通唯一索引：CREATE UNIQUE INDEX ... ON t (family_id, name)
//      → 所有行都参与判定，**包括软删的行**
//   B. 部分唯一索引：CREATE UNIQUE INDEX ... ON t (family_id, name)
//      WHERE deleted_at IS NULL
//      → 只有未删除的行参与判定
// =====================================================================

type InsertError struct{ Msg string }

func (e *InsertError) Error() string { return e.Msg }

type Table struct {
	rows []Category
	// partial 为 true 时模拟部分唯一索引（WHERE deleted_at IS NULL）
	partial bool
	// seq 自增，用来生成错误信息里的 "Key (family_id, name)=(...) already exists"
	seq int
}

func NewTable(partial bool) *Table { return &Table{partial: partial} }

// Insert 模拟一次 INSERT，唯一约束检查是唯一的失败来源
func (t *Table) Insert(c Category) error {
	t.seq++
	id := c.ID
	if id == "" {
		id = fmt.Sprintf("auto-%03d", t.seq)
	}

	// ---- 唯一约束检查：只有参与判定的行才冲突 ----
	for _, r := range t.rows {
		// 关键一行：部分唯一索引下，软删的行不参与判定
		if t.partial && r.DeletedAt.Valid {
			continue
		}
		if r.FamilyID == c.FamilyID && r.Name == c.Name {
			return &InsertError{Msg: fmt.Sprintf(
				`ERROR: duplicate key value violates unique constraint "%s" `+
					`(SQLSTATE 23505)`+"\n"+
					`DETAIL:  Key (family_id, name)=(%s, %s) already exists.`,
				t.constraintName(), c.FamilyID, c.Name)}
		}
	}

	c.ID = id
	c.Version = 1
	t.rows = append(t.rows, c)
	return nil
}

func (t *Table) constraintName() string {
	if t.partial {
		return "uniq_finance_category_family_name_active"
	}
	return "uniq_finance_category_family_name"
}

func (t *Table) SoftDelete(id string) {
	for i := range t.rows {
		if t.rows[i].ID == id {
			t.rows[i].DeletedAt = gorm.DeletedAt{
				Time:  time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC),
				Valid: true,
			}
			t.rows[i].Version++
		}
	}
}

func (t *Table) Dump(title string) {
	fmt.Printf("  %s\n", title)
	fmt.Printf("    %-9s %-10s %-8s %-4s %-8s %-22s\n", "id", "family_id", "name", "ver", "deleted?", "参与唯一约束判定?")
	for _, r := range t.rows {
		del := "否"
		if r.DeletedAt.Valid {
			del = "是"
		}
		involved := "✅ 是"
		if t.partial && r.DeletedAt.Valid {
			involved = "❌ 否（被 WHERE 排除）"
		}
		fmt.Printf("    %-9s %-10s %-8s %-4d %-8s %-22s\n",
			r.ID, short(r.FamilyID), r.Name, r.Version, del, involved)
	}
}

func short(uid string) string {
	if len(uid) > 8 {
		return uid[:8]
	}
	return uid
}

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		Logger: logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

func main() {
	fmt.Println("=== 1. 事故复现：删掉「餐饮」，再建一个「餐饮」 ===")
	fmt.Println("  用户故事：手滑删了「餐饮」分类，想重新建一个，结果报错。")

	// 错误的 schema：普通唯一索引
	bad := NewTable(false)
	fmt.Println()
	fmt.Println("  schema 里写的是（最常见的写法，也是错的）：")
	fmt.Println("    CREATE UNIQUE INDEX uniq_finance_category_family_name")
	fmt.Println("      ON finance.finance_category (family_id, name);")
	fmt.Println("  注意：没有 WHERE deleted_at IS NULL")

	fmt.Println()
	if err := bad.Insert(Category{FamilyID: famA, Name: "餐饮", Type: "expense"}); err != nil {
		fmt.Println("  步骤1 建「餐饮」：❌", err)
	} else {
		fmt.Println("  步骤1 建「餐饮」：✅ 成功")
	}
	bad.SoftDelete("auto-001")
	if err := bad.Insert(Category{FamilyID: famA, Name: "交通", Type: "expense"}); err != nil {
		fmt.Println("  步骤2 建「交通」：❌", err)
	} else {
		fmt.Println("  步骤2 建「交通」：✅ 成功")
	}
	fmt.Println("  步骤3 删掉「餐饮」（软删，deleted_at 被写上时间）")
	bad.SoftDelete("auto-001")

	fmt.Println()
	err := bad.Insert(Category{FamilyID: famA, Name: "餐饮", Type: "expense"})
	if err == nil {
		fmt.Println("  步骤4 重建「餐饮」：✅ 成功")
		fmt.Println("  ❌ 不该成功！这说明你的 schema 是对的（但那就不叫事故了）")
	} else {
		fmt.Println("  步骤4 重建「餐饮」：❌ 失败")
		for i, line := range strings.Split(err.Error(), "\n") {
			prefix := "     "
			if i == 0 {
				prefix = "    → "
			}
			fmt.Printf("%s%s\n", prefix, line)
		}
	}
	fmt.Println()
	bad.Dump("表里的真实状态：")
	fmt.Println()
	fmt.Println("  👆 看清楚：表里**没有**第二行「餐饮」，但插入仍然被拒绝了。")
	fmt.Println("     因为第一行「餐饮」虽然被软删了，它还躺在表里，")
	fmt.Println("     而普通唯一索引不区分「已删除」和「未删除」。")
	fmt.Println()
	fmt.Println("  这就是「软删 × 唯一约束」冲突的全部真相：")
	fmt.Println("     软删让行「看不见」，但唯一约束让行「依然存在」。")
	fmt.Println("     两个设计各自合理，凑在一起就出事故。")

	fmt.Println()
	fmt.Println("=== 2. 为什么这事特别难查：三个让它「看起来没问题」的地方 ===")
	tricky := []struct{ why, detail string }{
		{"测试环境复现不了", "新库是空的，没有「已删除的行」占着键，所以功能测试 100% 通过。必须先建后删才能触发。"},
		{"只在同一个家庭里发生", "唯一键是 (family_id, name) 而不是单独的 name，所以 A 家删了「餐饮」不影响 B 家。测试时你在 A 家建 B 家建，永远碰不到。"},
		{"报错信息完全不提示软删", "Postgres 只说 duplicate key，不会说「哦是因为上一行被软删了」。你得自己去查 SELECT * FROM ... WHERE name = '餐饮'，而默认查询还会自动过滤掉软删行 —— 于是你看到的是空结果，更加困惑。"},
	}
	for i, x := range tricky {
		fmt.Printf("  %s %s\n", []string{"①", "②", "③"}[i], x.why)
		fmt.Printf("     %s\n", x.detail)
	}

	fmt.Println()
	fmt.Println("  还有一个更隐蔽的：GORM 的默认查询也带软删过滤")
	dbg := dryDB()
	fmt.Println("    同一个 Where，两种 scope 生成两条不同的 SQL：")
	fmt.Println()
	st := dbg.Session(&gorm.Session{DryRun: true}).
		Where("family_id = ? AND name = ?", famA, "餐饮").
		First(&Category{})
	fmt.Printf("        默认 : %s\n", flat(st.Statement.SQL.String()))
	st = dbg.Session(&gorm.Session{DryRun: true}).Unscoped().
		Where("family_id = ? AND name = ?", famA, "餐饮").
		First(&Category{})
	fmt.Printf("        Unscoped: %s\n", flat(st.Statement.SQL.String()))
	fmt.Println()
	fmt.Println("    区别就在最后那半句 —— 默认查询带着 deleted_at IS NULL，")
	fmt.Println("    所以那行软删数据查不出来，你会以为「没重复啊」。")
	fmt.Println("    Unscoped 去掉了这个条件，才能看到那一行。")

	fmt.Println()
	fmt.Println("=== 3. 修法一（推荐）：部分唯一索引 ===")
	fmt.Println("  DDL：")
	fmt.Println("    CREATE UNIQUE INDEX uniq_fc_family_name_active")
	fmt.Println("      ON finance.finance_category (family_id, name)")
	fmt.Println("      WHERE deleted_at IS NULL;")
	fmt.Println()
	fmt.Println("  语义：只有 deleted_at IS NULL 的行参与唯一性判定。")
	fmt.Println("  软删的行自动「退出」约束，等于自动释放了那个名字。")

	good := NewTable(true)
	fmt.Println()
	if err := good.Insert(Category{FamilyID: famA, Name: "餐饮", Type: "expense"}); err != nil {
		fmt.Println("  步骤1 建「餐饮」：❌", err)
	} else {
		fmt.Println("  步骤1 建「餐饮」：✅ 成功")
	}
	good.SoftDelete("auto-001")
	if err := good.Insert(Category{FamilyID: famA, Name: "餐饮", Type: "expense"}); err != nil {
		fmt.Println("  步骤2 重建「餐饮」：❌ 失败")
		for _, line := range strings.Split(err.Error(), "\n") {
			fmt.Printf("      %s\n", line)
		}
	} else {
		fmt.Println("  步骤2 重建「餐饮」：✅ 成功（软删的行不再占键）")
	}
	fmt.Println("  步骤3 再建一个「餐饮」（此时它是活跃的，必须失败）")
	if err := good.Insert(Category{FamilyID: famA, Name: "餐饮", Type: "expense"}); err != nil {
		fmt.Println("         ❌ 被正确拦截：")
		for _, line := range strings.Split(err.Error(), "\n") {
			fmt.Printf("      %s\n", line)
		}
	}
	fmt.Println()
	good.Dump("表里的真实状态：")
	fmt.Println()
	fmt.Println("  👆 两行「餐饮」并存：一行已软删（不参与判定），一行活跃。")
	fmt.Println("     这正是我们要的：删了能重建，同时活跃数据仍然唯一。")

	fmt.Println()
	fmt.Println("  注意这里有个业务决策要写进产品文档：")
	fmt.Println("    「删除一个已有流水的分类」有两种做法 ——")
	fmt.Println("      A. 允许重建同名分类（两份历史流水挂在不同 id 的同名分类上）")
	fmt.Println("      B. 不允许：只要有流水引用就拒绝删除，提示「先转移流水」")
	fmt.Println("    本项目选 A，但要求前端在列表里对已软删的分类显示「已删除」占位，")
	fmt.Println("    否则用户会看到历史流水的分类名消失。**这是产品决策，不是技术决策。**")

	fmt.Println()
	fmt.Println("=== 4. 修法二：把 deleted_at 放进唯一键（不推荐，但要知道）===")
	fmt.Println("  DDL：")
	fmt.Println("    ALTER TABLE finance.finance_category")
	fmt.Println("      DROP CONSTRAINT uniq_finance_category_family_name;")
	fmt.Println("    CREATE UNIQUE INDEX uniq_fc_family_name_deleted")
	fmt.Println("      ON finance.finance_category (family_id, name, deleted_at);")
	fmt.Println()
	fmt.Println("  这个写法有个致命缺陷：**Postgres 的 NULL 不参与唯一性判定**")
	fmt.Println("  （SQL 标准行为，D2 专门讲过）。而未删除的行 deleted_at 是 NULL，")
	fmt.Println("  于是两个「未删除的餐饮」之间**根本不会冲突** ——")
	fmt.Println("  唯一约束形同虚设。这是从 JS/内存 store 迁过来的人最容易犯的错。")
	fmt.Println()
	fmt.Println("  想让它工作必须用 COALESCE 之类的技巧：")
	fmt.Println("    CREATE UNIQUE INDEX ... ON finance.finance_category")
	fmt.Println("      (family_id, name, COALESCE(deleted_at, 'epoch'::timestamptz));")
	fmt.Println("  但这要求索引是表达式索引（不能用普通 UNIQUE 约束声明），")
	fmt.Println("  而且 GORM 完全不认它。相比之下部分唯一索引干净得多。")

	fmt.Println()
	fmt.Println("=== 5. 修法三：先查后插（错误示范）===")
	fmt.Println("  很多人在 Go 里这么写：")
	fmt.Println("    var exist Category")
	fmt.Println("    err := db.Where(\"family_id = ? AND name = ?\", fam, name).First(&exist).Error")
	fmt.Println("    if err == nil { return errors.New(\"分类已存在\") }")
	fmt.Println("    db.Create(&Category{...})")
	fmt.Println()
	fmt.Println("  这段代码有三个问题：")
	fmt.Println("    ① 「先查后插」在并发下必然失效：两个请求同时查到「不存在」，")
	fmt.Println("       然后同时插入。唯一约束是数据库层的**原子**保证，应用层不是。")
	fmt.Println("    ② 这里查出来的 exist 其实是软删的行（如果没加 deleted_at IS NULL），")
	fmt.Println("       于是逻辑上会拒绝一个本该允许的操作 —— 反而制造了 bug。")
	fmt.Println("    ③ 就算逻辑写对了，它也只是把数据库的错误换成了更模糊的提示。")
	fmt.Println()
	fmt.Println("  正确的做法：**让唯一约束当唯一裁判**，应用层只负责把错误翻译成 409。")
	fmt.Printf("    %s\n", flat(dbg.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Category{}).
			Where("family_id = ? AND name = ?", famA, "餐饮").
			First(&Category{})
	})))
	fmt.Println("  这条查不到不是「没重复」，而是「已软删的行挡住了你」——")
	fmt.Println("  所以应用层判断逻辑必须以「唯一约束报没报错」为准，而不是以查询结果为准。")

	fmt.Println()
	fmt.Println("=== 6. 落地的四条纪律 ===")
	rules := []struct{ rule, detail string }{
		{"所有带软删的表，唯一约束一律用部分索引", "CREATE UNIQUE INDEX ... WHERE deleted_at IS NULL。这条写进 code review checklist。"},
		{"不要用 (col, deleted_at) 唯一", "NULL 不参与判定，唯一约束会静默失效。用部分索引或 COALESCE 表达式索引。"},
		{"捕获 23505 并翻译成 409", "GORM 里用 errors.As(&pgErr) 判断 *pq.Error 或 pgconn.PgError 的 Code，映射成「资源已存在」。"},
		{"给软删数据的查询留一个 Unscoped 出口", "排查问题、导出数据、审计日志都要能看到软删行；但业务查询绝对不要 Unscoped。"},
	}
	for i, r := range rules {
		fmt.Printf("  %d. %s\n", i+1, r.rule)
		fmt.Printf("     %s\n", r.detail)
	}

	fmt.Println()
	fmt.Println("  顺便说 ON CONFLICT：它能在有唯一约束的前提下做 upsert，")
	fmt.Println("  是部分唯一索引的最佳搭档（冲突了就更新而不是报错）。")
	fmt.Printf("    %s\n", flat(dbg.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Clauses(clause.OnConflict{
			Columns: []clause.Column{{Name: "family_id"}, {Name: "name"}},
			DoUpdates: clause.Assignments(map[string]any{
				"icon": gorm.Expr("EXCLUDED.icon"),
			}),
		}).Create(&Category{FamilyID: famA, Name: "餐饮", Type: "expense"})
	})))
	fmt.Println("  ↑ 有了部分唯一索引，ON CONFLICT (family_id, name) 才不会")
	fmt.Println("    匹配到软删的行 —— 因为那行根本不参与这个索引的判定。")

	fmt.Println()
	fmt.Println("  ⚠️ 最后提醒：这条约束目前只存在于 DDL 里（tech-plan §10.1 门禁会查）。")
	fmt.Println("  你在 D21 建 11 张表时，要检查**每一张带 deleted_at 的表**是否都有")
	fmt.Println("  配套的部分唯一索引 —— 漏一张就是一次未来的事故。")

	fmt.Println()
	fmt.Println("=== 与 JS/前端对比 ===")
	fmt.Println("  ① 内存 store（Map/数组）里根本没有唯一约束这回事。")
	fmt.Println("     你写 store.insert() 之前不判重，就真的会有两条「餐饮」。")
	fmt.Println("     所以 S1/S2 用内存 store 开发时，这个 bug 完全不会暴露 ——")
	fmt.Println("     搬进数据库的那天才第一次出现。这就是「内存开发」的盲区。")
	fmt.Println("  ② JS 里软删通常用数组过滤：items.filter(x => x.id !== id)，")
	fmt.Println("     元素真的从数组里消失了；数组的 indexOf + push 天然不会冲突。")
	fmt.Println("     数据库的表不是这样 —— 行还在磁盘上，索引还在维护它。")
	fmt.Println("  ③ 前端 localStorage 存数据也没有唯一约束。")
	fmt.Println("     本地重复了顶多显示两条，切设备就没了；")
	fmt.Println("     服务端重复是全局的数据污染，且往往无法自动修复。")

	fmt.Println()
	fmt.Println("=== S3 d12 到此结束 ===")
	fmt.Println("W11 明天进入本项目最贵的知识：游标分页。")
	fmt.Println("为什么 offset 分页在数据量涨上去之后会「跳数据」，")
	fmt.Println("我们会拿 1000 条数据把这件事一步步算清楚。")
}

func flat(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

