// =====================================================================
// W11 d13：游标分页原理 —— 为什么 offset 在大数据量下会跳数据。
//
// 这是本项目最贵的一块知识。核心结论一句话：
//   offset 分页的「页码」是一个**会漂移的坐标**，不是一把稳定的钥匙。
//
// 本文件用 1000 条数据把这件事算清楚：
//   - 每条数据的 id 是递增的，created_at 故意让 5 条一组共享同一时间戳
//   - 先看 offset 分页在「无并发」时就已经会漏数据（因为时间戳重复导致排序不稳定）
//   - 再看「有并发插入」时怎么重复 + 漏
//   - 最后用同样 1000 条数据跑一遍游标分页，证明它两种情况都不出错
//
// 数据全部是本地构造的，排序/分页逻辑是真实执行的 ——
// S3 第 6 天（D22）起真库后，要把同样的查询跑在真 SQL 上，
// 用 EXPLAIN ANALYZE 对比 offset 深分页的「丢弃行数」。
// =====================================================================

package main

import (
	"fmt"
	"strings"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

// ---- 一条流水 ----

type Txn struct {
	ID        string
	CreatedAt string // 格式 "2026-10-15 09:00:00"，秒级精度
	Amount    int64
	Note      string
}

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

// makeTxns 造 n 条流水。
// 关键设计：每 5 条共享同一个 created_at（模拟真实系统里
// 「批量导入」或「定时任务落库」产生的同秒数据）。
// 这不是刁难 —— 时间戳重复是生产环境的常态，
// 而它正是 offset 分页翻车的主要原因之一。
func makeTxns(n int) []Txn {
	out := make([]Txn, 0, n)
	base := 0
	for i := 1; i <= n; i++ {
		// 每 5 条一个时间戳 → 同一秒内最多 5 条
		ts := base + (i-1)/5
		out = append(out, Txn{
			ID:        fmt.Sprintf("txn-%04d", i),
			CreatedAt: fmt.Sprintf("2026-10-15 %02d:%02d:%02d", 9+ts/3600, (ts/60)%60, ts%60),
			Amount:    int64(1000 + i*13),
			Note:      fmt.Sprintf("第%d笔", i),
		})
	}
	return out
}

// =====================================================================
// 排序：模拟 SQL 的 ORDER BY created_at DESC, id DESC
//
// 注意：即使 SQL 写了两个排序键，如果 created_at 相同，
// 单靠它排序仍然有歧义 —— 必须有 id 兜底才唯一确定顺序。
// 这里的 sortStable 就是干这个的：先按 created_at，再按 id。
// =====================================================================

func sortDesc(rows []Txn) []Txn {
	out := make([]Txn, len(rows))
	copy(out, rows)
	// 插入排序：数据量小，重点是可读。真实数据库用 quicksort。
	for i := 1; i < len(out); i++ {
		for j := i; j > 0; j-- {
			a, b := out[j-1], out[j]
			// DESC：created_at 大 → id 大
			if a.CreatedAt > b.CreatedAt || (a.CreatedAt == b.CreatedAt && a.ID > b.ID) {
				break
			}
			out[j-1], out[j] = b, a
		}
	}
	return out
}

// =====================================================================
// offset 分页：LIMIT n OFFSET m
// =====================================================================

func pageOffset(rows []Txn, page, size int) []Txn {
	start := (page - 1) * size
	if start >= len(rows) {
		return nil
	}
	end := start + size
	if end > len(rows) {
		end = len(rows)
	}
	return rows[start:end]
}

func idsOf(rows []Txn) []string {
	out := make([]string, len(rows))
	for i, r := range rows {
		out[i] = r.ID
	}
	return out
}

func fmtIDs(ids []string) string { return strings.Join(ids, ", ") }

// ---- 展示辅助 ----

func showPages(title string, pages [][]string) {
	fmt.Printf("  %s\n", title)
	for i, p := range pages {
		fmt.Printf("    第%d页: %s\n", i+1, fmtIDs(p))
	}
}

func findAll(pages [][]string) []string {
	var out []string
	for _, p := range pages {
		out = append(out, p...)
	}
	return out
}

// 找出重复和遗漏
func diff(want, got []string) (dups, missing []string) {
	seen := map[string]int{}
	for _, g := range got {
		seen[g]++
	}
	for g, n := range seen {
		if n > 1 {
			dups = append(dups, fmt.Sprintf("%s×%d", g, n))
		}
	}
	wantSet := map[string]bool{}
	for _, w := range want {
		wantSet[w] = true
	}
	gotSet := map[string]bool{}
	for _, g := range got {
		gotSet[g] = true
	}
	for w := range wantSet {
		if !gotSet[w] {
			missing = append(missing, w)
		}
	}
	sortStrings(dups)
	sortStrings(missing)
	return
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		Logger: logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

func main() {
	const N = 1000
	const SIZE = 10

	fmt.Println("=== 1. 造 1000 条数据，先看清楚排序后的样子 ===")
	txns := makeTxns(N)
	sorted := sortDesc(txns)

	fmt.Printf("  共 %d 条，按 (created_at DESC, id DESC) 排序后的第 1..%d 条：\n", N, SIZE*2)
