	fmt.Printf("    → 两页里有 %d 条重复\n", dupIn4)
	fmt.Println()
	fmt.Println("  为什么重复：新数据插在最前面 → 原第 41 行现在排到第 44 行，")
	fmt.Println("  但第 4 页仍然去取 OFFSET 40..49 —— 也就是原来的 38..47 行。")
	fmt.Println("  于是有 3 条（= 新增条数）在屏幕上的第 1 页和第 4 页各出现一次。")

	// 完整核对：重复 + 遗漏
	allReal := findAll(realPages)
	nDup := len(allReal) - len(unique(allReal))
	dupList, missingList := diff(idsOf(sorted), allReal)
	// 注意：和「新增前」的 1000 条比，才看得出用户丢了什么
	fmt.Println()
	fmt.Printf("  汇总（以新增前的 %d 条为基准）：\n", N)
	fmt.Printf("    屏幕上共出现 %d 行（其中 %d 行是重复的）\n", len(allReal), nDup)
	fmt.Printf("    重复的 id: %s\n", fmtIDs(dupList))
	fmt.Printf("    永远看不到的 id: %s\n", fmtIDs(missingList))
	fmt.Println()
	fmt.Println("  机制（一定要能讲清楚）：")
	fmt.Println("    新增 3 条 → 所有行的下标都往后挪 3 位")
	fmt.Println("    但 OFFSET 是按「第几页 × 每页条数」算的，它不知道多了 3 条")
	fmt.Println("    于是第 4 页往后，OFFSET 40 实际落到了原来第 38 行的位置")
	fmt.Println("    结果：前面 3 条被重复看到，最后 3 条永远看不到")
	fmt.Println()
	fmt.Printf("  数字对得上吗？重复 %d 条 + 遗漏 %d 条 = %d，正好等于新增的 %d 条。\n",
		nDup, len(missingList), nDup+len(missingList), len(inserted))
	fmt.Println("  这个「守恒」是可以验算的 —— 面试时能当场推给面试官看，很加分。")

	fmt.Println()
	fmt.Println("  ⚠️ 这个 bug 的隐蔽性：「重复」用户往往不 complained")
	fmt.Println("     （顶多觉得「这几条怎么又出现了」），")
	fmt.Println("     而「遗漏」要翻到最末尾才发现 —— 那时用户已经导出了一份错数据。")
	fmt.Println("     更糟的是：用户如果点了「加载更多」之后就离开，第 3 页之后根本没请求，")
	fmt.Println("     那 3 条新数据他**永远看不到** —— 这才是最常见的实际后果。")

	fmt.Println()
	fmt.Println("=== 4. 故障场景 B：时间戳重复导致排序不稳定 ===")
	fmt.Println("  上面已经看到「同秒多条」。假设 ORDER BY 只写了 created_at，")
	fmt.Println("  没有 id 兜底，数据库对相同时间的行的返回顺序是**不保证**的")
	fmt.Println("  （Postgres 的 seq scan / 并发排序都可能给出不同顺序）。")
	fmt.Println()
	fmt.Println("  后果：第 1 页和第 2 页之间可能夹进一条本该在第 1 页的行，")
	fmt.Println("        OFFSET 20 又会把它算进第 3 页 —— 同一行出现两次。")
	fmt.Println()
	fmt.Println("  这种情况**不需要任何并发**，只要有同秒数据就可能发生，")
	fmt.Println("  而且你在开发环境（数据少、同秒少）几乎遇不到。")
	fmt.Println()
	fmt.Println("  结论：排序键必须能唯一确定顺序。created_at 不唯一，所以要加 id。")

	fmt.Println()
	fmt.Println("=== 5. 同一份数据用游标分页：两种故障都不发生 ===")
	fmt.Println("  游标分页不传页码，传「上一页最后一条的 (created_at, id)」。")
	fmt.Println()

	cur1 := paginateCursor(sorted, SIZE, nil)
	// 翻页中途插入 3 条
	cur2 := paginateCursor(grown, SIZE, nil)
	fmt.Println("  两次的「第 1 页」：")
	fmt.Printf("    无并发时: %s\n", fmtIDs(cur1[0]))
	fmt.Printf("    新增 3 条后: %s\n", fmtIDs(cur2[0]))
	fmt.Println()
	fmt.Println("  第 1 页当然不同 —— 用户本来就该看到刚记的那几笔。")
	fmt.Println("  关键是：**往后翻到最后，两次拿到的数据是同一份**。")
	fmt.Println()

	// 对比两条流的尾部：新数据只影响开头，不影响结尾
	tail1 := cur1[len(cur1)-1]
	tail2 := cur2[len(cur2)-1]
	fmt.Println("    各自的最后一页：")
	fmt.Printf("      无并发时（%d 行）: %s\n", len(tail1), fmtIDs(tail1))
	fmt.Printf("      新增后  （%d 行）: %s\n", len(tail2), fmtIDs(tail2))
	fmt.Println()
	fmt.Println("    → 最后一页不一样是正常的：多了 3 条数据，页数就多 1 页。")
	fmt.Println("      重要的是两条流的**末尾数据完全一致**（都是 txn-0001 收尾），")
	fmt.Println("      也就是说没有任何一条数据被漏掉。")
	if len(tail1) > 0 && len(tail2) > 0 {
		last1 := tail1[len(tail1)-1]
		last2 := tail2[len(tail2)-1]
		if last1 == last2 {
			fmt.Printf("      两条流的最后一条都是 %s ✅\n", last1)
		}
	}

	// 关键核对：两次流各自的完整性
	allCur1 := findAll(cur1)
	allCur2 := findAll(cur2)
	d1, m1 := diff(idsOf(sorted), allCur1)
	d2, m2 := diff(idsOf(grown), allCur2)
	fmt.Println()
	fmt.Println("  完整性核对：")
	fmt.Printf("    无并发时: %d 行，重复 %v，遗漏 %v\n", len(allCur1), d1, m1)
	fmt.Printf("    新增后  : %d 行，重复 %v，遗漏 %v\n", len(allCur2), d2, m2)
	fmt.Println()
	fmt.Println("  ✅ 两边都是「不重复、不遗漏」。")
	fmt.Println()
	fmt.Println("  为什么游标免疫这个问题（这是今天要记住的因果链）：")
	fmt.Println("    offset   = 「跳过前 N 行」→ N 是相对于**当前结果集**的坐标，")
	fmt.Println("              结果集一变（N 的含义就变），坐标就失效。")
	fmt.Println("    游标     = 「排序位置在 (created_at, id) 之前」→ 这是**绝对坐标**，")
	fmt.Println("              由数据本身的属性决定，不受新增数据影响。")
	fmt.Println()
	fmt.Println("  所以新插入的数据只会出现在「第 1 页」（它的时间戳最新），")
	fmt.Println("  它永远不会挤掉后面的任何一行 —— 而 offset 会。")

	fmt.Println()
	fmt.Println("=== 6. offset 的第二个问题：越翻越慢 ===")
	fmt.Println("  OFFSET 40 必须先扫描并丢弃前 40 行，才能给你第 41 行。")
	fmt.Println("  OFFSET 990 必须丢弃 990 行。所以：")
	fmt.Println()
	fmt.Printf("  %-10s %-16s %-16s %-12s\n", "页码", "offset", "要丢弃的行数", "游标要扫的行")
	for _, p := range []int{1, 10, 50, 100} {
		off := (p - 1) * SIZE
		// 游标分页：从索引里定位游标位置，最多扫一页 + 一点点
		cur := SIZE
		if off == 0 {
			cur = SIZE
		} else {
			cur = SIZE
		}
		fmt.Printf("  %-10d %-16d %-16d %-12d\n", p, off, off, cur)
	}
	fmt.Println()
	fmt.Println("  最后一行永远是 990 行的丢弃量，而游标永远是 10 行。")
	fmt.Println("  这不是常数倍差距，是「第 100 页比第 1 页慢 100 倍」。")
	fmt.Println("  真库上这个差距会被放大：Postgres 会做 seq scan 扫过整张表再丢掉前 N 行。")
	fmt.Println("  （D17 会给出完整的 EXPLAIN 输出和索引设计。）")

	fmt.Println()
	fmt.Println("=== 7. offset 的第三个问题：它不能表达「筛选条件」 ===")
	fmt.Println("  记账页通常是「按月份 + 按分类筛选」。此时 OFFSET 的含义变得含糊：")
	fmt.Println("    SELECT * WHERE family_id=$1 AND created_at BETWEEN $2 AND $3")
	fmt.Println("      ORDER BY created_at DESC LIMIT 10 OFFSET 20")
	fmt.Println("  这个 20 是「在筛选结果里跳过 20 条」，前提是**筛选结果不变**。")
	fmt.Println("  只要用户改了时间范围、或者期间来了新数据，这个坐标立刻失效。")
	fmt.Println("  游标分页没有这个问题 —— 游标本身携带了排序位置，")
	fmt.Println("  无论结果集变大变小，位置都是明确的。")

	fmt.Println()
	fmt.Println("=== 8. 三种分页的对照表 ===")
	rows := []struct{ method, stable, cost, canJump, cursorSize string }{
		{"LIMIT/OFFSET", "❌ 会重复/遗漏", "O(offset)", "✅ 直接跳第 N 页", "无（页码）"},
		{"游标 (created_at,id)", "✅ 不重复不遗漏", "O(limit)", "❌ 只能下一页", "~60 字节"},
		{"seek method（单键）", "⚠️ 单键唯一时才稳", "O(limit)", "❌ 只能下一页", "~40 字节"},
	}
	fmt.Printf("  %-24s %-20s %-14s %-20s %s\n", "方式", "稳定性", "翻页成本", "能否跳页", "前端要传的东西")
	for _, r := range rows {
		fmt.Printf("  %-24s %-20s %-14s %-20s %s\n", r.method, r.stable, r.cost, r.canJump, r.cursorSize)
	}
	fmt.Println()
	fmt.Println("  「不能跳页」是游标分页唯一的代价。本项目接受它，")
	fmt.Println("  理由：记账流水是时间倒序的无限流，用户几乎不跳页，")
	fmt.Println("  而「漏数据」是绝对不能接受的。如果产品确实需要跳页，")
	fmt.Println("  可以做混合方案：提供「按月跳转」（用时间游标实现，")
	fmt.Println("  不是页码），配合 OFFSET 用于「月内翻页」—— 每月数据量有限，")
	fmt.Println("  OFFSET 的丢弃开销可以接受。")

	fmt.Println()
	fmt.Println("=== 9. 真实 SQL 长什么样 ===")
	dbg := dryDB()
	fmt.Println("  ① offset 分页（问题代码）")
	st := dbg.Session(&gorm.Session{DryRun: true}).
		Where("family_id = ? AND created_at < ? AND deleted_at IS NULL", famA, "2026-10-15 09:00:00").
		Order("created_at DESC, id DESC").Limit(10).Offset(990).Find(&[]Txn{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))
	fmt.Println("     ↑ OFFSET 990 = 要扫描并丢弃 990 行")

	fmt.Println()
	fmt.Println("  ② 游标分页（正确）")
	st = dbg.Session(&gorm.Session{DryRun: true}).
		Where("family_id = ? AND (created_at, id) < (?, ?) AND deleted_at IS NULL",
			famA, "2026-10-15 09:00:00", "txn-0500").
		Order("created_at DESC, id DESC").Limit(10).Find(&[]Txn{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))
	fmt.Println("     ↑ 元组比较 (created_at, id) < (?, ?) 是关键：")
	fmt.Println("       它表示「比这一行更靠后」，等价于 ORDER BY 的反向。")
	fmt.Println("       注意必须是两个字段一起比，不能只比 created_at ——")
	fmt.Println("       否则同秒的行会被漏掉。")

	fmt.Println()
	fmt.Println("=== S3 d13 到此结束 ===")
	fmt.Println("明天写游标的完整实现：游标怎么编码、怎么解码、")
	fmt.Println("以及为什么游标要做 base64 + 防篡改。")
}

// =====================================================================
// 游标分页实现（下一页 = 传上一页最后一行的 (created_at, id)）
// =====================================================================

type Cursor struct {
	CreatedAt string
	ID        string
}

func paginateCursor(rows []Txn, size int, start *Cursor) [][]string {
	var pages [][]string
	i := 0
	// 如果给了游标，先定位到它后面
	if start != nil {
		for ; i < len(rows); i++ {
			r := rows[i]
			if r.CreatedAt < start.CreatedAt ||
				(r.CreatedAt == start.CreatedAt && r.ID < start.ID) {
				break
			}
		}
	}
	for i < len(rows) {
		end := i + size
		if end > len(rows) {
			end = len(rows)
		}
		p := rows[i:end]
		var ids []string
		for _, r := range p {
			ids = append(ids, r.ID)
		}
		pages = append(pages, ids)
		i = end
	}
	return pages
}

func distinctTimestamps(rows []Txn) int {
	set := map[string]bool{}
	for _, r := range rows {
		set[r.CreatedAt] = true
	}
	return len(set)
}

func countDupTimestamps(rows []Txn) int {
	c := map[string]int{}
	for _, r := range rows {
		c[r.CreatedAt]++
	}
	n := 0
	for _, v := range c {
		if v > 1 {
			n++
		}
	}
	return n
}

func unique(all []string) []string {
	set := map[string]bool{}
	for _, a := range all {
		set[a] = true
	}
	out := make([]string, 0, len(set))
	for a := range set {
		out = append(out, a)
	}
	sortStrings(out)
	return out
}

func flat(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

