// =====================================================================
// W12 d14：游标分页的实现 —— 基于 (created_at, id) 复合游标。
//
// d13 讲了「为什么 offset 会跳数据」，今天写「游标到底怎么落地」。
// 要落地就必须解决三个问题：
//   ① 游标怎么在 HTTP 里传？→ 编码成一个不透明的字符串
//   ② 前端能不能伪造游标？→ 防篡改（签名）
//   ③ 后端怎么解？→ 校验 + 解析，解析失败要报错而不是静默当第一页
//
// SQL 部分用 GORM DryRun 真实生成；编码/解码/分页逻辑是真实执行的。
// 提醒：本机没有 Postgres，D22 起真库后要把同样的查询跑在真 SQL 上，
// 用 EXPLAIN ANALYZE 确认走的是 (created_at, id) 的索引。
// =====================================================================

package main

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

// 固定的签名密钥。真环境里这个密钥必须来自配置/环境变量，
// 绝不能硬编码进仓库。
var cursorSecret = "homecube-s3-dev-secret"

var fixedNow = time.Date(2026, 10, 15, 9, 30, 0, 0, time.UTC)

// ---- 模型 ----

type Transaction struct {
	ID        string         `gorm:"primaryKey;type:uuid"`
	FamilyID  string         `gorm:"column:family_id;type:uuid;not null"`
	Amount    int64          `gorm:"column:amount;not null"`
	Note      string         `gorm:"column:note;type:varchar(200)"`
	Version   int            `gorm:"column:version;not null;default:1"`
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

func (Transaction) TableName() string { return "finance_transaction" }

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		NowFunc: func() time.Time { return fixedNow },
		Logger:  logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

// =====================================================================
// 游标的结构与编解码
// =====================================================================

// Cursor 就是「上一页最后一条数据的位置」。
// 只有两个字段，但顺序很重要：必须和 ORDER BY 完全一致。
type Cursor struct {
	CreatedAt string `json:"t"` // 时间戳（RFC3339 或 "2006-01-02 15:04:05"）
	ID        string `json:"i"` // 主键，作为时间戳相同时的 tiebreaker
	FamilyID  string `json:"f"` // 归属的家庭，防跨租户复用游标
}

// Encode 把游标编码成给前端的不透明字符串。
//
// 为什么要 base64 而不是直接 JSON：
//
//	JSON 里含 { } " 逗号 这些字符，放进 URL query 需要百分号编码，
//	而且一眼就能看出内部结构 → 用户会试图改它。
//	base64 之后是一段看起来无意义的字符串，符合「不透明 token」的预期。
//
// 格式： base64(JSON) + "." + base64(HMAC-SHA256 前 8 字节)
func Encode(c Cursor) string {
	raw, _ := json.Marshal(c)
	body := base64.RawURLEncoding.EncodeToString(raw)
	sig := sign(body)
	return body + "." + sig
}

// Decode 是 Encode 的逆操作，失败时返回错误。
//
// ⚠️ 这里用 HMAC 代替真正的 crypto/hmac 是为了保持零依赖且确定性；
// 真代码请用 crypto/hmac + crypto/sha256（同样的思路）。
func Decode(token string) (Cursor, error) {
	parts := strings.Split(token, ".")
	if len(parts) != 2 {
		return Cursor{}, fmt.Errorf("游标格式错误：应为 base64.signature 两段，实际 %d 段", len(parts))
	}
	body, sig := parts[0], parts[1]
	if sign(body) != sig {
		return Cursor{}, fmt.Errorf("游标签名校验失败：可能被篡改")
	}
	raw, err := base64.RawURLEncoding.DecodeString(body)
	if err != nil {
		return Cursor{}, fmt.Errorf("游标 base64 解码失败：%v", err)
	}
	var c Cursor
	if err := json.Unmarshal(raw, &c); err != nil {
		return Cursor{}, fmt.Errorf("游标 JSON 解析失败：%v", err)
	}
	if c.ID == "" || c.CreatedAt == "" {
		return Cursor{}, fmt.Errorf("游标字段缺失：t 与 i 都必须有值")
	}
	return c, nil
}

// sign 是一个确定性的「签名」：FNV-1a 哈希 + base64。
// 它足以演示「篡改会被发现」，但强度远不如 HMAC ——
// 真代码必须用 crypto/hmac。
func sign(body string) string {
	var h uint64 = 1469598103934665603 // FNV offset basis
	for i := 0; i < len(body); i++ {
		h ^= uint64(body[i])
		h *= 1099511628211 // FNV prime
	}
	return base64.RawURLEncoding.EncodeToString([]byte(strconv.FormatUint(h, 16)))
}

// =====================================================================
// 数据：100 条流水，序号越大时间越新
// =====================================================================

func makeTxns(n int) []Transaction {
	out := make([]Transaction, 0, n)
	for i := 1; i <= n; i++ {
		sec := n - i // 第 1 条时间最新
		ts := fixedNow.Add(time.Duration(-sec) * time.Second)
		out = append(out, Transaction{
			ID:       fmt.Sprintf("txn-%04d", i),
			FamilyID: famA,
			Amount:   int64(1000 + i*13),
			Note:     fmt.Sprintf("第%d笔", i),
			Version:  1,
		})
		_ = ts
	}
	// 直接按 createdAt 递减排（数据本来就是这个顺序）
	return out
}

func sortDesc(rows []Transaction) []Transaction {
	out := make([]Transaction, len(rows))
	copy(out, rows)
	for i := 1; i < len(out); i++ {
		for j := i; j > 0; j-- {
			a, b := out[j-1], out[j]
			// DESC：时间大 → 在前；时间相同则 id 大在前
			ta := tsOf(a.ID)
			tb := tsOf(b.ID)
			if ta > tb || (ta == tb && a.ID > b.ID) {
				break
			}
			out[j-1], out[j] = b, a
		}
	}
	return out
}

// tsOf 从 id 推出时间戳（保持测试数据的构造简单且确定）
func tsOf(id string) string {
	var n int
	fmt.Sscanf(id, "txn-%d", &n)
	return fixedNow.Add(time.Duration(-(100 - n)) * time.Second).
		Format("2006-01-02 15:04:05")
}

// =====================================================================
// 分页查询：核心逻辑
// =====================================================================

type Page struct {
	Rows       []Transaction
	NextCursor string // 空字符串表示没有下一页
	HasMore    bool
}

// Paginate 是游标分页的实现。token 为空表示取第一页。
func Paginate(rows []Transaction, familyID, token string, size int) (Page, error) {
	var start *Cursor
	if token != "" {
		c, err := Decode(token)
		if err != nil {
			return Page{}, err
		}
		// 防跨租户：游标里带的 family_id 必须和当前请求的一致
		if c.FamilyID != familyID {
			return Page{}, fmt.Errorf("游标不属于当前家庭（游标 %s vs 请求 %s）", shortID(c.FamilyID), shortID(familyID))
		}
		start = &c
	}

	// 定位：跳过所有「不小于游标位置」的行。
	// 对应 SQL 里的 (created_at, id) < ($1, $2)。
	idx := 0
	if start != nil {
		for ; idx < len(rows); idx++ {
			r := rows[idx]
			rt := tsOf(r.ID)
			// DESC 顺序下，「更靠后」= 时间更小，或时间相同且 id 更小
			if rt < start.CreatedAt || (rt == start.CreatedAt && r.ID < start.ID) {
				break
			}
		}
	}

	end := idx + size
	hasMore := false
	if end < len(rows) {
		hasMore = true
	} else {
		end = len(rows)
	}
	page := rows[idx:end]

	out := Page{Rows: page, HasMore: hasMore}
	if hasMore && len(page) > 0 {
		last := page[len(page)-1]
		out.NextCursor = Encode(Cursor{
			CreatedAt: tsOf(last.ID),
			ID:        last.ID,
			FamilyID:  familyID,
		})
	}
	return out, nil
}

func shortID(s string) string {
	if len(s) > 8 {
		return s[:8]
	}
	return s
}

func ids(rows []Transaction) []string {
	out := make([]string, len(rows))
	for i, r := range rows {
		out[i] = r.ID
	}
	return out
}

func main() {
	fmt.Println("=== 1. 游标里放什么：只有排序键，不放页码 ===")
	fmt.Println("  游标 = 上一页最后一条数据的 (created_at, id)。")
	fmt.Println("  游标里只有排序键 (created_at, id) 加上 family_id，**没有任何业务字段** ——")
	fmt.Println("  因为游标的唯一职责是「定位排序位置」，塞别的东西会让它变脆。")
	fmt.Println("  family_id 是为了做跨租户校验（见第 3 节），不是用来筛选的。")
	fmt.Println()
	sample := Cursor{
		CreatedAt: "2026-10-15 09:29:30",
		ID:        "txn-0031",
		FamilyID:  famA,
	}
	tok := Encode(sample)
	fmt.Printf("  游标内容 : %+v\n", sample)
	fmt.Printf("  编码后   : %s\n", tok)
	fmt.Printf("  长度     : %d 字节\n", len(tok))
	fmt.Println()
	fmt.Println("  对比一下 offset 分页要传的东西：")
	fmt.Println("    offset: page=3&size=10        （8 字节，但含义会漂移）")
	fmt.Printf("    游标  : cursor=%s\n", tok)
	fmt.Println("            （更长的字符串，但含义永远不变）")
	fmt.Println()
	fmt.Println("  这就是权衡：游标牺牲了「可读性和可跳页」，换来了「确定性」。")
	fmt.Println("  游标还必须做 base64 —— 否则 JSON 里的引号和逗号")
	fmt.Println("  放进 URL 要百分号编码，而且用户一眼就能看出内部结构并试图改它。")

	fmt.Println()
	fmt.Println("=== 2. 防篡改：前端改了游标会怎样 ===")
	cases := []struct{ name, token string }{
		{"原样传回", tok},
		{"把 id 改成 txn-0001（试图看更早的数据）", encodeWithID(tok, "txn-0001")},
		{"把 id 改成 txn-0100（试图看更晚的数据）", encodeWithID(tok, "txn-0100")},
		{"签名部分删掉", strings.Split(tok, ".")[0]},
		{"签名部分乱填", strings.Split(tok, ".")[0] + ".aGVsbG8gd29ybGQ"},
		{"完全乱传", "not-a-cursor"},
		{"签名正确但 base64 段非法", "@@@@" + "." + sign("@@@@")},
		{"签名正确但内容不是 JSON", base64.RawURLEncoding.EncodeToString([]byte("hello")) + "." + sign(base64.RawURLEncoding.EncodeToString([]byte("hello")))},
	}
	for _, c := range cases {
		_, err := Decode(c.token)
		if err == nil {
			fmt.Printf("  %-46s → ✅ 通过\n", c.name)
		} else {
			fmt.Printf("  %-46s → ❌ %v\n", c.name, err)
		}
	}
	fmt.Println()
	fmt.Println("  为什么必须防篡改（这是个安全问题，不是洁癖）：")
	fmt.Println("    游标里的 CreatedAt/ID 会被直接拼进 WHERE 子句。")
	fmt.Println("    如果允许前端任意构造，它可以：")
	fmt.Println("      ① 构造极端的时间戳，让数据库做一次昂贵的范围扫描")
	fmt.Println("      ② 构造别的租户的游标，试探系统行为（虽然结果被 family_id 挡着）")
	fmt.Println("      ③ 传入超长字符串撑爆日志/内存")
	fmt.Println("  签名的作用是让游标成为「只有服务端能生成的 token」。")
	fmt.Println("  更严格的做法：把签名换成 HMAC-SHA256，并且给游标加一个过期时间。")

	fmt.Println()
	fmt.Println("=== 3. 跨租户复用游标：第三道防线 ===")
	fmt.Println("  即使签名合法（因为签名确实是我们自己签的），")
	fmt.Println("  也要检查游标里的 family_id 和当前请求是否一致。")
	fmt.Println()
	_, err := Paginate(makeTxns(100), "bbbbbbbb-0000-4000-8000-000000000002", tok, 10)
	if err != nil {
		fmt.Printf("  用家庭 B 的身份带家庭 A 的游标来查：❌ %v\n", err)
	} else {
		fmt.Println("  ❌ 应该被拒绝但通过了")
	}
	fmt.Println()
	fmt.Println("  场景说明：用户退出登录再换一个账号登录，浏览器地址栏里的 cursor 还在。")
	fmt.Println("  如果不校验 family_id，A 的游标会在 B 的数据上「定位」，")
	fmt.Println("  结果是 B 看到一页从中间开始的数据 —— 逻辑错误，甚至可能泄露排序规律。")

	fmt.Println()
	fmt.Println("=== 4. 完整翻页：走一遍 100 条数据 ===")
	rows := sortDesc(makeTxns(100))
	const size = 10

	token := ""
	pageNo := 0
	var collected []string
	for {
		page, err := Paginate(rows, famA, token, size)
		if err != nil {
			fmt.Printf("  第%d页出错：%v\n", pageNo+1, err)
			break
		}
		pageNo++
		if pageNo <= 3 || !page.HasMore {
			fmt.Printf("  第%2d页: %s\n", pageNo, strings.Join(shorten(ids(page.Rows)), ", "))
			if page.HasMore {
				fmt.Printf("          next_cursor = %s...\n", trunc(page.NextCursor, 56))
			} else {
				fmt.Printf("          没有下一页了\n")
			}
		} else if pageNo == 4 {
			fmt.Printf("  第%2d页: ...（中间省略）\n", pageNo)
		}
		collected = append(collected, ids(page.Rows)...)
		if !page.HasMore {
			break
		}
		token = page.NextCursor
	}
	fmt.Println()
	fmt.Printf("  共翻到 %d 页，拿到 %d 条数据\n", pageNo, len(collected))
	fmt.Printf("  有重复吗：%v\n", hasDuplicate(collected))
	fmt.Printf("  第1条=%s  第100条=%s\n", collected[0], collected[len(collected)-1])

	fmt.Println()
	fmt.Println("=== 5. 真实 SQL：GORM 生成的样子 ===")
	dbg := dryDB()
	fmt.Println("  ① 第一页（无游标）")
	st := dbg.Session(&gorm.Session{DryRun: true}).
		Where("family_id = ? AND deleted_at IS NULL", famA).
		Order("created_at DESC, id DESC").
		Limit(size).Find(&[]Transaction{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))
	fmt.Printf("     VAR : %v\n", st.Statement.Vars)

	fmt.Println()
	fmt.Println("  ② 下一页（带游标）—— 元组比较是核心")
	st = dbg.Session(&gorm.Session{DryRun: true}).
		Where("family_id = ? AND deleted_at IS NULL AND (created_at, id) < (?, ?)",
			famA, sample.CreatedAt, sample.ID).
		Order("created_at DESC, id DESC").
		Limit(size).Find(&[]Transaction{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))
	fmt.Printf("     VAR : %v\n", st.Statement.Vars)

	fmt.Println()
	fmt.Println("  ③ 为什么必须用元组比较 (created_at, id) < (?, ?)？")
	fmt.Println("     如果写成两个独立条件：")
	fmt.Println("       WHERE created_at < $2 AND id < $3")
	fmt.Println("     那么当某一行 created_at == $2 但 id < $3 时，它会被漏掉；")
	fmt.Println("     而 created_at < $2 且 id > $3 的行又会错误地保留在后面。")
	fmt.Println("     元组比较是「词典序比较」，语义正好等于 ORDER BY 的反向：")
	fmt.Println("       (a1,a2) < (b1,b2)  ⟺  a1 < b1  OR  (a1 = b1 AND a2 < b2)")
	fmt.Println("     这才是「严格排在游标之后」的正确表达。")

	fmt.Println()
	fmt.Println("  ④ 反过来，ASC 方向翻页用 >：")
	st = dbg.Session(&gorm.Session{DryRun: true}).
		Where("family_id = ? AND (created_at, id) > (?, ?)", famA, sample.CreatedAt, sample.ID).
		Order("created_at ASC, id ASC").
		Limit(size).Find(&[]Transaction{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))

	fmt.Println()
	fmt.Println("  ⚠️ ASC 分页有个已知的不稳定问题（keyset pagination 的老坑）：")
	fmt.Println("     如果在你翻页期间，有一行被**插入**到当前游标之前，")
	fmt.Println("     它不会出现在后续页里 —— 这是对的（它比游标新，你已经看过了）。")
	fmt.Println("     但如果有一行被**更新**导致 created_at 变了，")
	fmt.Println("     它可能从「已看过的范围」跳到「未看过的范围」，于是被重复显示。")
	fmt.Println("     对记账流水来说这不是问题（created_at 是不可变的创建时间），")
	fmt.Println("     但如果你的表有 updated_at 且拿它排序，就必须知道这个坑。")

	fmt.Println()
	fmt.Println("=== 6. 实现里容易写错的五个点 ===")
	pitfalls := []struct{ wrong, right, why string }{
		{"ORDER BY created_at DESC（没有 id）", "ORDER BY created_at DESC, id DESC",
			"同秒数据顺序不确定，会漏行。ORDER BY 必须和游标比较键完全一致。"},
		{"WHERE created_at < ? AND id < ?", "WHERE (created_at, id) < (?, ?)",
			"两个独立条件是「与」而不是词典序，会漏掉同秒的行。"},
		{"LIMIT size+1 然后看有没有多的", "LIMIT size，然后靠排序位置推 hasMore",
			"取 size+1 再截断在绝大多数情况下也对，但要多判断一次；而且 count 查询更贵。游标分页通常用「多取一条」判断，但注意别真的返回它。"},
		{"把游标里的值拼进 SQL 字符串", "用 ? 占位符或结构体字段",
			"拼接 = SQL 注入。游标是前端可控的输入，和其他用户输入没有区别。"},
		{"Decode 失败时静默返回第一页", "Decode 失败就返回 400",
			"静默降级会让用户莫名其妙看到第一页，还以为数据丢了。"},
	}
	for i, p := range pitfalls {
		fmt.Printf("  %d. ❌ %s\n", i+1, p.wrong)
		fmt.Printf("     ✅ %s\n", p.right)
		fmt.Printf("     为什么：%s\n", p.why)
	}

	fmt.Println()
	fmt.Println("=== 7. 响应体长什么样（和项目统一 Envelope 对齐）===")
	resp := map[string]any{
		"code":    0,
		"message": "ok",
		"data": map[string]any{
			"items": []map[string]any{
				{"id": "txn-0001", "amount": 1013, "note": "第1笔"},
				{"id": "txn-0002", "amount": 1026, "note": "第2笔"},
			},
			"next_cursor": tok,
			"has_more":    true,
		},
		"request_id": "req-20261015-000001",
	}
	b, _ := json.MarshalIndent(resp, "", "  ")
	fmt.Println(string(b))
	fmt.Println()
	fmt.Println("  三个设计点：")
	fmt.Println("    ① next_cursor 是**不透明字符串**，前端不许解析、不许构造。")
	fmt.Println("    ② has_more 单独给出，前端不用靠「items 是不是正好 size 条」来判断")
	fmt.Println("       （最后一页可能刚好满，用长度判断会多请求一次空页）。")
	fmt.Println("    ③ 请求时 cursor 为空表示第一页；不要用 cursor=\"\" 表示结束，")
	fmt.Println("       用 has_more=false。")

	fmt.Println()
	fmt.Println("=== 与 JS/前端对比 ===")
	fmt.Println("  ① 前端几乎所有人都写 LIMIT/OFFSET，因为简单：")
	fmt.Println("     res.skip((page-1)*10).limit(10) —— 一行搞定，还能做页码 UI。")
	fmt.Println("     游标分页做不了页码 UI，这是它在多数项目里被弃用的真实原因。")
	fmt.Println("     本项目接受这个代价，因为「漏数据」比「没有页码」严重得多。")
	fmt.Println("  ② JS 里 base64 到处都有（btoa/atob），但注意：")
	fmt.Println("     btoa() 不能直接处理非 Latin-1 字符，中文会抛异常。")
	fmt.Println("     Go 的 base64.RawURLEncoding.EncodeToString 没有这个问题，")
	fmt.Println("     这也是服务端做编码比前端可靠的一个小例子。")
	fmt.Println("  ③ 前端把 cursor 放 URL 还是 POST body？")
	fmt.Println("     放 URL 会有长度限制和日志泄露风险；放 body 更干净。")
	fmt.Println("     本项目用 GET + query 参数（便于调试和缓存），")
	fmt.Println("     但要注意别把 cursor 打进访问日志。")

	fmt.Println()
	fmt.Println("=== S3 d14 到此结束 ===")
	fmt.Println("明天把游标和筛选条件组合起来：时间窗口 + family_id + cursor 三者同时存在时，")
	fmt.Println("最容易出错的是「用户中途改了筛选条件，但 cursor 还是旧的」。")
}

func encodeWithID(tok, newID string) string {
	parts := strings.Split(tok, ".")
	if len(parts) != 2 {
		return tok
	}
	raw, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return tok
	}
	var c Cursor
	_ = json.Unmarshal(raw, &c)
	c.ID = newID
	nraw, _ := json.Marshal(c)
	nbody := base64.RawURLEncoding.EncodeToString(nraw)
	// 注意：这里**故意不重算签名**，模拟「攻击者改了内容但没改签名」
	return nbody + "." + parts[1]
}

func hasDuplicate(s []string) bool {
	seen := map[string]bool{}
	for _, x := range s {
		if seen[x] {
			return true
		}
		seen[x] = true
	}
	return false
}

func shorten(ids []string) []string {
	out := make([]string, len(ids))
	for i, s := range ids {
		out[i] = strings.Replace(s, "txn-", "", 1)
	}
	return out
}

func trunc(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n]
}

func flat(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

