// =====================================================================
// W12 d15：多条件筛选 —— 时间窗口 + family_id + cursor 的组合。
//
// 昨天游标只管排序。今天加两个维度：
//   family_id   → 多租户隔离（W12 的主题）
//   时间窗口     → 用户选「看 10 月」「看最近 7 天」
//
// 组合之后出现一个新问题：**游标和筛选条件必须绑定**。
// 用户在第 2 页把时间范围从「10 月」改成「9 月」，但 cursor 还是旧的
// —— 此时那个游标在新结果集里的含义完全不同，会漏数据或者重复。
//
// 本文件真跑出这个故障，并给出正确解法：游标里带上筛选条件的指纹。
//
// SQL 部分用 GORM DryRun 真实生成；筛选/分页逻辑是真实执行的。
// 提醒：本机没有 Postgres，D22 起真库后要把同样的查询跑在真 SQL 上，
// 用 EXPLAIN ANALYZE 确认 (family_id, created_at DESC, id DESC) 索引被用上。
// =====================================================================

package main

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"
const famB = "bbbbbbbb-0000-4000-8000-000000000002"

var fixedNow = time.Date(2026, 10, 15, 12, 0, 0, 0, time.UTC)

type Transaction struct {
	ID        string         `gorm:"primaryKey;type:uuid"`
	FamilyID  string         `gorm:"column:family_id;type:uuid;not null"`
	Amount    int64          `gorm:"column:amount;not null"`
	Note      string         `gorm:"column:note;type:varchar(200)"`
	CreatedAt time.Time      `gorm:"column:created_at;not null"`
	Version   int            `gorm:"column:version;not null;default:1"`
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

func (Transaction) TableName() string { return "finance_transaction" }

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		NowFunc: func() time.Time { return fixedNow },
		Logger:  logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

// =====================================================================
// 筛选条件
// =====================================================================

type Filter struct {
	FamilyID string // 来自 token/session，绝不接受前端传
	From     string // "2026-10-01 00:00:00"，空表示不限
	To       string // "2026-11-01 00:00:00"，空表示不限
	MinCents int64  // 金额下限，0 表示不限
	Keyword  string // 备注关键字，空表示不限
}

// Fingerprint 是筛选条件的指纹。
// 它的唯一用途：**证明「这个游标是在这一组筛选条件下产生的」**。
// 条件变了，指纹就变，旧游标立刻失效。
func (f Filter) Fingerprint() string {
	// 注意 min 用 %d 而不是 %f —— 金额是整数分，不能有浮点误差
	key := fmt.Sprintf("%s|%s|%s|%d|%s", f.FamilyID, f.From, f.To, f.MinCents, f.Keyword)
	return sign(key)
}

// Cursor 现在带上了指纹
type Cursor struct {
	T string `json:"t"` // created_at
	I string `json:"i"` // id
	F string `json:"f"` // 筛选条件指纹
}

func EncodeCursor(c Cursor) string {
	raw, _ := json.Marshal(c)
	return base64.RawURLEncoding.EncodeToString(raw)
}

func DecodeCursor(tok string) (Cursor, error) {
	raw, err := base64.RawURLEncoding.DecodeString(tok)
	if err != nil {
		return Cursor{}, fmt.Errorf("游标 base64 解码失败：%v", err)
	}
	var c Cursor
	if err := json.Unmarshal(raw, &c); err != nil {
		return Cursor{}, fmt.Errorf("游标 JSON 解析失败：%v", err)
	}
	if c.T == "" || c.I == "" {
		return Cursor{}, fmt.Errorf("游标字段缺失")
	}
	return c, nil
}

// sign 是确定性的 FNV-1a 哈希，仅用于演示指纹/签名。
// 真代码请用 crypto/hmac + crypto/sha256。
func sign(s string) string {
	var h uint64 = 1469598103934665603
	for i := 0; i < len(s); i++ {
		h ^= uint64(s[i])
		h *= 1099511628211
	}
	return base64.RawURLEncoding.EncodeToString(
		[]byte(fmt.Sprintf("%016x", h)))[:16]
}

// =====================================================================
// 内存数据：两个家庭，各 60 条，分布在 10 月和 9 月
// =====================================================================

func makeTxns() []Transaction {
	var out []Transaction
	// 家庭 A：9 月 30 条 + 10 月 30 条
	for i := 1; i <= 60; i++ {
		month := time.September
		day := i%30 + 1
		if i > 30 {
			month = time.October
			day = (i-30)%30 + 1
		}
		ts := time.Date(2026, month, day, 9, 0, 0, 0, time.UTC)
		out = append(out, Transaction{
			ID:        fmt.Sprintf("A-%03d", i),
			FamilyID:  famA,
			Amount:    int64(1000 + i*37),
			Note:      fmt.Sprintf("A家第%d笔", i),
			CreatedAt: ts,
			Version:   1,
		})
	}
	// 家庭 B：也是 60 条，故意和 A 的时间/金额分布相似
	for i := 1; i <= 60; i++ {
		month := time.September
		day := i%30 + 1
		if i > 30 {
			month = time.October
			day = (i-30)%30 + 1
		}
		ts := time.Date(2026, month, day, 9, 0, 0, 0, time.UTC)
		out = append(out, Transaction{
			ID:        fmt.Sprintf("B-%03d", i),
			FamilyID:  famB,
			Amount:    int64(1000 + i*37),
			Note:      fmt.Sprintf("B家第%d笔", i),
			CreatedAt: ts,
			Version:   1,
		})
	}
	return out
}

func tsStr(t time.Time) string { return t.Format("2006-01-02 15:04:05") }

// FilterRows 模拟 SQL 的 WHERE，返回「该筛选条件下」的完整结果集（已排序）
func FilterRows(all []Transaction, f Filter) []Transaction {
	var out []Transaction
	for _, r := range all {
		if r.FamilyID != f.FamilyID {
			continue // 租户隔离永远第一优先
		}
		if r.DeletedAt.Valid {
			continue
		}
		s := tsStr(r.CreatedAt)
		if f.From != "" && s < f.From {
			continue
		}
		// To 是「开区间上界」：created_at < To
		if f.To != "" && s >= f.To {
			continue
		}
		if r.Amount < f.MinCents {
			continue
		}
		if f.Keyword != "" && !strings.Contains(r.Note, f.Keyword) {
			continue
		}
		out = append(out, r)
	}
	// DESC: created_at desc, id desc
	for i := 1; i < len(out); i++ {
		for j := i; j > 0; j-- {
			a, b := out[j-1], out[j]
			if a.CreatedAt.After(b.CreatedAt) ||
				(a.CreatedAt.Equal(b.CreatedAt) && a.ID > b.ID) {
				break
			}
			out[j-1], out[j] = b, a
		}
	}
	return out
}

type Page struct {
	Rows       []Transaction
	NextCursor string
	HasMore    bool
}

// Paginate 应用筛选 + 游标
func Paginate(all []Transaction, f Filter, token string, size int) (Page, error) {
	rows := FilterRows(all, f)

	if token != "" {
		c, err := DecodeCursor(token)
		if err != nil {
			return Page{}, err
		}
		// ★ 关键校验：游标必须是在「当前这组筛选条件」下产生的
		if c.F != f.Fingerprint() {
			return Page{}, fmt.Errorf(
				"游标与当前筛选条件不匹配（指纹 %s vs %s）—— 请重新开始翻页", c.F, f.Fingerprint())
		}
		// 在结果集里定位到游标之后
		idx := len(rows)
		for i, r := range rows {
			rt := tsStr(r.CreatedAt)
			if rt < c.T || (rt == c.T && r.ID < c.I) {
				idx = i
				break
			}
		}
		rows = rows[idx:]
	}

	end := size
	hasMore := false
	if end < len(rows) {
		hasMore = true
	} else {
		end = len(rows)
	}
	page := rows[:end]

	out := Page{Rows: page, HasMore: hasMore}
	if hasMore && len(page) > 0 {
		last := page[len(page)-1]
		out.NextCursor = EncodeCursor(Cursor{
			T: tsStr(last.CreatedAt),
			I: last.ID,
			F: f.Fingerprint(),
		})
	}
	return out, nil
}

func brief(rows []Transaction) []string {
	out := make([]string, len(rows))
	for i, r := range rows {
		out[i] = strings.TrimPrefix(r.ID, "A-")
	}
	return out
}

func main() {
	fmt.Println("=== 1. 三个筛选维度一起用 ===")
	all := makeTxns()

	// 只按 family_id
	f1 := Filter{FamilyID: famA}
	// 加时间窗口
	f2 := Filter{FamilyID: famA, From: "2026-10-01 00:00:00", To: "2026-11-01 00:00:00"}
	// 再加金额下限
	f3 := Filter{FamilyID: famA, From: "2026-10-01 00:00:00", To: "2026-11-01 00:00:00", MinCents: 2800}

	fmt.Printf("  原始数据: %d 条（家庭 A 60 + 家庭 B 60）\n", len(all))
	fmt.Printf("  ① 只按 family_id          → %3d 条\n", len(FilterRows(all, f1)))
	fmt.Printf("  ② + 时间窗口（10 月）      → %3d 条\n", len(FilterRows(all, f2)))
	fmt.Printf("  ③ + 金额 ≥ 28 元          → %3d 条\n", len(FilterRows(all, f3)))
	fmt.Println()
	fmt.Println("  注意：family_id 这一条**永远在**，不管其他条件怎么变。")
	fmt.Println("  这是多租户系统的底线 —— 租户隔离不是「筛选条件之一」，")
	fmt.Println("  它是每一条查询的**前置约束**。W12 后面两天专门讲这个。")

	fmt.Println()
	fmt.Println("=== 2. 正常翻页：三条件组合下走一遍 ===")
	const size = 10
	token := ""
	var collected []Transaction
	pageNo := 0
	for {
		p, err := Paginate(all, f3, token, size)
		if err != nil {
			fmt.Printf("  第%d页出错：%v\n", pageNo+1, err)
			break
		}
		pageNo++
		if pageNo <= 3 {
			fmt.Printf("  第%d页 (%d 条): %s\n", pageNo, len(p.Rows),
				strings.Join(brief(p.Rows), ", "))
		} else if !p.HasMore {
			fmt.Printf("  第%d页 (%d 条): %s  ← 最后一页\n", pageNo, len(p.Rows),
				strings.Join(brief(p.Rows), ", "))
		}
		collected = append(collected, p.Rows...)
		if !p.HasMore {
			break
		}
		token = p.NextCursor
	}
	fmt.Println()
	want := FilterRows(all, f3)
	fmt.Printf("  筛选结果应有 %d 条，实际翻到 %d 条\n", len(want), len(collected))
	fmt.Printf("  完全一致？%v\n", idsEqual(want, collected))

	fmt.Println()
	fmt.Println("=== 3. 故障：翻页中途改了筛选条件 ===")
	fmt.Println("  用户在第 1 页之后，把时间范围从「10 月」改成了「9 月」，")
	fmt.Println("  但前端的 cursor 还是原来那个（前端不知道它失效了）。")
	fmt.Println()

	p1, _ := Paginate(all, f2, "", size) // 10 月
	fmt.Printf("  第1页（10月）: %s\n", strings.Join(brief(p1.Rows), ", "))
	fmt.Printf("  拿到游标     : %s...\n", trunc(p1.NextCursor, 48))
	fmt.Println()

	// 用户改条件：10 月 → 9 月
	f9 := Filter{FamilyID: famA, From: "2026-09-01 00:00:00", To: "2026-10-01 00:00:00"}
	fmt.Println("  现在把条件换成 9 月，用**同一个游标**请求第 2 页：")
	p2, err := Paginate(all, f9, p1.NextCursor, size)
	if err != nil {
		fmt.Printf("  ❌ %v\n", err)
	} else {
		fmt.Printf("  ⚠️ 请求成功了，返回 %d 条：%s\n", len(p2.Rows), strings.Join(brief(p2.Rows), ", "))
	}
	fmt.Println()
	fmt.Println("  如果没有指纹校验，这里会静默返回错误的数据。")
	fmt.Println("  为什么「静默」特别糟：前端不报错，用户看到的是")
	fmt.Println("  「10 月的第 1 页 + 9 月的中间某一页」拼在一起的一屏数据，")
	fmt.Println("  用户会以为这是正常的分页，直到对账时才发现对不上。")

	fmt.Println()
	fmt.Println("=== 4. 指纹是怎么起作用的 ===")
	fmt.Printf("  10 月条件的指纹: %s\n", f2.Fingerprint())
	fmt.Printf("  9  月条件的指纹: %s\n", f9.Fingerprint())
	fmt.Printf("  相同吗        : %v\n", f2.Fingerprint() == f9.Fingerprint())
	fmt.Println()
	fmt.Println("  游标里存的就是这个指纹：")
	c, _ := DecodeCursor(p1.NextCursor)
	fmt.Printf("    游标内容: T=%s I=%s F=%s\n", c.T, c.I, c.F)
	fmt.Println()
	fmt.Println("  服务端收到请求时重算一遍指纹，比对不一致就返回 400。")
	fmt.Println("  前端拿到 400 的正确反应是：**清空 cursor，重新从第 1 页开始**。")
	fmt.Println("  这比返回错误数据好得多 —— 至少用户知道要重新翻了。")

	fmt.Println()
	fmt.Println("  ⚠️ 一个容易忽略的点：指纹里**不能**包含 page/size。")
	fmt.Println("     用户把每页 10 条改成 20 条是合法的，")
	fmt.Println("     游标语义（排序位置）不受影响，不该导致失效。")
	fmt.Println("     指纹只该包含**改变结果集本身**的条件。")

	fmt.Println()
	fmt.Println("=== 5. 时间窗口用开区间还是闭区间 ===")
	fmt.Println("  代码里写的是：")
	fmt.Println("    WHERE created_at >= '2026-10-01 00:00:00'")
	fmt.Println("      AND created_at <  '2026-11-01 00:00:00'")
	fmt.Println()
	fmt.Println("  上界用 `<` 而不是 `<=`，原因是 `<= '2026-10-31 23:59:59'` 会漏掉")
	fmt.Println("  「2026-10-31 23:59:59.5」这种带毫秒/微秒的数据。")
	fmt.Println("  半开区间 [from, to) 是所有时间范围查询的标准做法。")
	fmt.Println()
	edge := []struct {
		desc string
		val  time.Time
	}{
		{"2026-09-30 23:59:59（9 月最后一秒）", time.Date(2026, 9, 30, 23, 59, 59, 0, time.UTC)},
		{"2026-10-01 00:00:00（10 月第一秒）", time.Date(2026, 10, 1, 0, 0, 0, 0, time.UTC)},
		{"2026-10-31 23:59:59", time.Date(2026, 10, 31, 23, 59, 59, 0, time.UTC)},
		{"2026-11-01 00:00:00（11 月第一秒）", time.Date(2026, 11, 1, 0, 0, 0, 0, time.UTC)},
	}
	for _, e := range edge {
		in := FilterRows(all, f2)
		found := false
		for _, r := range in {
			if r.CreatedAt.Equal(e.val) {
				found = true
			}
		}
		mark := "❌ 不在结果里"
		if found {
			mark = "✅ 在结果里"
		}
		fmt.Printf("    %-34s %s\n", e.desc, mark)
	}
	fmt.Println()
	fmt.Println("  这就是半开区间的作用：边界判断清晰，相邻两个月不会重叠或漏。")

	fmt.Println()
	fmt.Println("=== 6. 真实 SQL：三条件 + 游标长什么样 ===")
	dbg := dryDB()
	fmt.Println("  ① 只有 family_id（第一页）")
	st := dbg.Session(&gorm.Session{DryRun: true}).
		Where("family_id = ? AND created_at >= ? AND created_at < ? AND amount >= ? AND deleted_at IS NULL",
			famA, "2026-10-01 00:00:00", "2026-11-01 00:00:00", 2800).
		Order("created_at DESC, id DESC").
		Limit(size).Find(&[]Transaction{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))

	fmt.Println()
	fmt.Println("  ② 加游标（注意括号的位置）")
	st = dbg.Session(&gorm.Session{DryRun: true}).
		Where("family_id = ? AND created_at >= ? AND created_at < ? AND amount >= ? AND deleted_at IS NULL",
			famA, "2026-10-01 00:00:00", "2026-11-01 00:00:00", 2800).
		Where("(created_at, id) < (?, ?)", "2026-10-28 09:00:00", "A-042").
		Order("created_at DESC, id DESC").
		Limit(size).Find(&[]Transaction{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))
	fmt.Printf("     VAR : %v\n", st.Statement.Vars)

	fmt.Println()
	fmt.Println("  ⚠️ 最容易写错的地方：游标条件的括号。")
	fmt.Println("     ❌ WHERE created_at < ? OR created_at >= ? AND (created_at,id) < (?,?)")
	fmt.Println("        → OR 的优先级会让整个筛选条件失效")
	fmt.Println("     ✅ 把游标条件整体加括号，或者用 gorm 的 Where 连写（它自动 AND）")

	fmt.Println()
	fmt.Println("=== 7. 关键字搜索：为什么它最难和游标配合 ===")
	fmt.Println("  LIKE '%关键字%' 无法用索引，会全表扫描。")
	fmt.Println("  叠加游标分页后问题更严重：")
	fmt.Println()
	fmt.Printf("  %-28s %-14s %s\n", "筛选条件", "命中行数", "能否走 (family_id, created_at, id) 索引")
	rows := []struct {
		desc string
		f    Filter
	}{
		{"只有 family_id", f1},
		{"family_id + 时间窗口", f2},
		{"family_id + 时间 + 金额下限", f3},
		{"family_id + 关键字 LIKE", Filter{FamilyID: famA, Keyword: "A家第1"}},
	}
	for _, r := range rows {
		n := len(FilterRows(all, r.f))
		can := "✅ 能，索引前缀匹配"
		if r.f.Keyword != "" {
			can = "❌ 不能，LIKE 前置通配符"
		}
		fmt.Printf("  %-28s %-14d %s\n", r.desc, n, can)
	}
	fmt.Println()
	fmt.Println("  原因：索引是 B-tree，靠**前缀**定位。")
	fmt.Println("  `created_at >= X` 是范围前缀 → 能用；")
	fmt.Println("  `note LIKE '%关键字%'` 前面是 % → 不知道从哪开始，只能全扫。")
	fmt.Println()
	fmt.Println("  实践上的三个选择：")
	fmt.Println("    ① 关键字搜索**单独做一个接口**，不与游标分页混用")
	fmt.Println("       （一次返回全部结果，前端自己做筛选，或者限制 100 条）")
	fmt.Println("    ② 改用全文检索（Postgres tsvector + GIN 索引，d17 会提）")
	fmt.Println("    ③ 改成前缀匹配（note LIKE '关键%'），能走 trigram 索引")

	fmt.Println()
	fmt.Println("=== 8. 参数校验：这些条件一个都不能信 ===")
	checks := []struct {
		field, bad, why string
	}{
		{"family_id", "来自前端 query", "可被篡改成别人的 family → 越权。必须从 token/session 取"},
		{"From/To", "'2026-13-45'", "非法日期。Postgres 会报错，但要转成 400 而不是 500"},
		{"From > To", "from=11月&to=10月", "空区间。应该明确报 400 或返回空 + 提示"},
		{"MinCents", "-1", "负数金额。money 字段的 CHECK 约束会挡，但要给友好提示"},
		{"Keyword", "'; DROP TABLE--", "SQL 注入。必须用 ? 占位符，绝不拼字符串"},
		{"size", "1000000", "一次拉百万行把数据库拖垮。要设上限（本项目 100）"},
	}
	fmt.Printf("  %-12s %-22s %s\n", "字段", "危险输入", "怎么防")
	for _, c := range checks {
		fmt.Printf("  %-12s %-22s %s\n", c.field, c.bad, c.why)
	}
	fmt.Println()
	fmt.Println("  特别强调 family_id 那一行：它是**唯一不能从请求参数取**的筛选条件。")
	fmt.Println("  其他条件都是「用户想看什么」，只有它是「用户是谁」。")

	fmt.Println()
	fmt.Println("=== 与 JS/前端对比 ===")
	fmt.Println("  ① 前端做筛选是「拿到全量再 filter」，服务端做筛选是「数据库只返回要的行」。")
	fmt.Println("     前者在数据量小时简单好用，S1/S2 的内存 store 就是这么做的；")
	fmt.Println("     但一旦接了后端，筛选必须下推到 SQL，否则响应体会爆炸。")
	fmt.Println("  ② JS 里改筛选条件很容易触发一串连锁更新（useEffect 依赖变化 → 重新请求），")
	fmt.Println("     而游标的分页状态可能被连带清空。本项目的约定是：")
	fmt.Println("     任何筛选条件变化 → 清空 cursor，从第 1 页重新开始。")
	fmt.Println("  ③ 时间处理：JS 的 new Date('2026-10-01') 会按**浏览器本地时区**解析，")
	fmt.Println("     用户在纽约看到的「10 月 1 日」和服务端算的可能差一天。")
	fmt.Println("     这就是 d4 讲的 TIMESTAMP vs TIMESTAMPTZ ——")
	fmt.Println("     本项目所有时间在传输层都用带时区的 ISO 8601 字符串。")

	fmt.Println()
	fmt.Println("=== S3 d15 到此结束 ===")
	fmt.Println("明天讲稳定性：翻页过程中数据被**修改**或**软删**会怎样，")
	fmt.Println("以及为什么「不重复不遗漏」这个承诺需要一个明确的前提条件。")
}

func idsEqual(a, b []Transaction) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].ID != b[i].ID {
			return false
		}
	}
	return true
}

func trunc(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n]
}

func flat(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

