// =====================================================================
// W12 d15：多条件筛选 —— 时间窗口 + family_id + cursor 的组合。
//
// 昨天游标只管排序。今天加两个维度：
//   family_id   → 多租户隔离（W12 的主题）
//   时间窗口     → 用户选「看 10 月」「看最近 7 天」
//
// 组合之后出现一个新问题：**游标和筛选条件必须绑定**。
// 用户在第 2 页把时间范围从「10 月」改成「9 月」，但 cursor 还是旧的
// —— 此时那个游标在新结果集里的含义完全不同，会漏数据或者重复。
//
// 本文件真跑出这个故障，并给出正确解法：游标里带上筛选条件的指纹。
//
// SQL 部分用 GORM DryRun 真实生成；筛选/分页逻辑是真实执行的。
// 提醒：本机没有 Postgres，D22 起真库后要把同样的查询跑在真 SQL 上，
// 用 EXPLAIN ANALYZE 确认 (family_id, created_at DESC, id DESC) 索引被用上。
// =====================================================================

package main

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"
const famB = "bbbbbbbb-0000-4000-8000-000000000002"

var fixedNow = time.Date(2026, 10, 15, 12, 0, 0, 0, time.UTC)

type Transaction struct {
	ID        string         `gorm:"primaryKey;type:uuid"`
	FamilyID  string         `gorm:"column:family_id;type:uuid;not null"`
	Amount    int64          `gorm:"column:amount;not null"`
	Note      string         `gorm:"column:note;type:varchar(200)"`
	CreatedAt time.Time      `gorm:"column:created_at;not null"`
	Version   int            `gorm:"column:version;not null;default:1"`
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

func (Transaction) TableName() string { return "finance_transaction" }

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		NowFunc: func() time.Time { return fixedNow },
		Logger:  logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

// =====================================================================
// 筛选条件

// =====================================================================

type Filter struct {
	FamilyID string // 来自 token/session，绝不接受前端传
	From     string // "2026-10-01 00:00:00"，空表示不限
	To       string // "2026-11-01 00:00:00"，空表示不限
	MinCents int64  // 金额下限，0 表示不限
	Keyword  string // 备注关键字，空表示不限
}

// Fingerprint 是筛选条件的指纹。
// 它的唯一用途：**证明「这个游标是在这一组筛选条件下产生的」**。
// 条件变了，指纹就变，旧游标立刻失效。
func (f Filter) Fingerprint() string {
	// 注意 min 用 %d 而不是 %f —— 金额是整数分，不能有浮点误差
	key := fmt.Sprintf("%s|%s|%s|%d|%s", f.FamilyID, f.From, f.To, f.MinCents, f.Keyword)
	return sign(key)
}

// Cursor 现在带上了指纹
type Cursor struct {
	T string `json:"t"` // created_at
	I string `json:"i"` // id
	F string `json:"f"` // 筛选条件指纹
}

func EncodeCursor(c Cursor) string {
	raw, _ := json.Marshal(c)
	return base64.RawURLEncoding.EncodeToString(raw)
}

func DecodeCursor(tok string) (Cursor, error) {
	raw, err := base64.RawURLEncoding.DecodeString(tok)
	if err != nil {
		return Cursor{}, fmt.Errorf("游标 base64 解码失败：%v", err)
	}
	var c Cursor
	if err := json.Unmarshal(raw, &c); err != nil {
		return Cursor{}, fmt.Errorf("游标 JSON 解析失败：%v", err)
	}
	if c.T == "" || c.I == "" {
		return Cursor{}, fmt.Errorf("游标字段缺失")
	}
	return c, nil
}

// sign 是确定性的 FNV-1a 哈希，仅用于演示指纹/签名。
// 真代码请用 crypto/hmac + crypto/sha256。
func sign(s string) string {
	var h uint64 = 1469598103934665603
	for i := 0; i < len(s); i++ {
		h ^= uint64(s[i])
		h *= 1099511628211
	}
	return base64.RawURLEncoding.EncodeToString(
		[]byte(fmt.Sprintf("%016x", h)))[:16]
}

// =====================================================================
// 内存数据：两个家庭，各 60 条，分布在 10 月和 9 月

// =====================================================================

func makeTxns() []Transaction {
	var out []Transaction
	// 家庭 A：9 月 30 条 + 10 月 30 条
	for i := 1; i <= 60; i++ {
		month := time.September
		day := i%30 + 1
		if i > 30 {
			month = time.October
			day = (i-30)%30 + 1
		}
		ts := time.Date(2026, month, day, 9, 0, 0, 0, time.UTC)
		out = append(out, Transaction{
			ID:        fmt.Sprintf("A-%03d", i),
			FamilyID:  famA,
			Amount:    int64(1000 + i*37),
			Note:      fmt.Sprintf("A家第%d笔", i),
			CreatedAt: ts,
			Version:   1,
		})
	}
	// 家庭 B：也是 60 条，故意和 A 的时间/金额分布相似
	for i := 1; i <= 60; i++ {
		month := time.September
		day := i%30 + 1
		if i > 30 {
			month = time.October
			day = (i-30)%30 + 1
		}
		ts := time.Date(2026, month, day, 9, 0, 0, 0, time.UTC)
		out = append(out, Transaction{
			ID:        fmt.Sprintf("B-%03d", i),
			FamilyID:  famB,
			Amount:    int64(1000 + i*37),
			Note:      fmt.Sprintf("B家第%d笔", i),
			CreatedAt: ts,
			Version:   1,
		})
	}
	return out
}

func tsStr(t time.Time) string { return t.Format("2006-01-02 15:04:05") }

// FilterRows 模拟 SQL 的 WHERE，返回「该筛选条件下」的完整结果集（已排序）
func FilterRows(all []Transaction, f Filter) []Transaction {
	var out []Transaction
	for _, r := range all {
		if r.FamilyID != f.FamilyID {
			continue // 租户隔离永远第一优先
		}
		if r.DeletedAt.Valid {
			continue
		}
		s := tsStr(r.CreatedAt)
		if f.From != "" && s < f.From {
			continue
		}
		// To 是「开区间上界」：created_at < To
		if f.To != "" && s >= f.To {
			continue
		}
		if r.Amount < f.MinCents {
			continue
		}
		if f.Keyword != "" && !strings.Contains(r.Note, f.Keyword) {
			continue
		}
		out = append(out, r)
	}
	// DESC: created_at desc, id desc
	for i := 1; i < len(out); i++ {
		for j := i; j > 0; j-- {
			a, b := out[j-1], out[j]
			if a.CreatedAt.After(b.CreatedAt) ||
				(a.CreatedAt.Equal(b.CreatedAt) && a.ID > b.ID) {
				break
			}
			out[j-1], out[j] = b, a
		}
	}
	return out
}

type Page struct {
	Rows       []Transaction
	NextCursor string
	HasMore    bool
}

// Paginate 应用筛选 + 游标
func Paginate(all []Transaction, f Filter, token string, size int) (Page, error) {
	rows := FilterRows(all, f)

	if token != "" {
		c, err := DecodeCursor(token)
		if err != nil {
			return Page{}, err
		}
		// ★ 关键校验：游标必须是在「当前这组筛选条件」下产生的
		if c.F != f.Fingerprint() {
			return Page{}, fmt.Errorf(
				"游标与当前筛选条件不匹配（指纹 %s vs %s）—— 请重新开始翻页", c.F, f.Fingerprint())
		}
		// 在结果集里定位到游标之后
		idx := len(rows)
		for i, r := range rows {
			rt := tsStr(r.CreatedAt)
			if rt < c.T || (rt == c.T && r.ID < c.I) {
				idx = i
				break
			}
		}
		rows = rows[idx:]
	}

	end := size
	hasMore := false
	if end < len(rows) {
		hasMore = true
	} else {
		end = len(rows)
	}
	page := rows[:end]

	out := Page{Rows: page, HasMore: hasMore}
	if hasMore && len(page) > 0 {
		last := page[len(page)-1]
		out.NextCursor = EncodeCursor(Cursor{
			T: tsStr(last.CreatedAt),
			I: last.ID,
			F: f.Fingerprint(),
		})
	}
	return out, nil
}

func brief(rows []Transaction) []string {
	out := make([]string, len(rows))
	for i, r := range rows {
		out[i] = strings.TrimPrefix(r.ID, "A-")
	}
	return out
}

func main() {
	fmt.Println("=== 1. 三个筛选维度一起用 ===")
	all := makeTxns()

	// 只按 family_id
	f1 := Filter{FamilyID: famA}
	// 加时间窗口
	f2 := Filter{FamilyID: famA, From: "2026-10-01 00:00:00", To: "2026-11-01 00:00:00"}
	// 再加金额下限
	f3 := Filter{FamilyID: famA, From: "2026-10-01 00:00:00", To: "2026-11-01 00:00:00", MinCents: 2800}

	fmt.Printf("  原始数据: %d 条（家庭 A 60 + 家庭 B 60）\n", len(all))
	fmt.Printf("  ① 只按 family_id          → %3d 条\n", len(FilterRows(all, f1)))
	fmt.Printf("  ② + 时间窗口（10 月）      → %3d 条\n", len(FilterRows(all, f2)))
	fmt.Printf("  ③ + 金额 ≥ 28 元          → %3d 条\n", len(FilterRows(all, f3)))
	fmt.Println()
	fmt.Println("  注意：family_id 这一条**永远在**，不管其他条件怎么变。")
	fmt.Println("  这是多租户系统的底线 —— 租户隔离不是「筛选条件之一」，")
	fmt.Println("  它是每一条查询的**前置约束**。W12 后面两天专门讲这个。")

	fmt.Println()
	fmt.Println("=== 2. 正常翻页：三条件组合下走一遍 ===")
	const size = 10
	token := ""
	var collected []Transaction
	pageNo := 0
	for {
		p, err := Paginate(all, f3, token, size)
		if err != nil {
			fmt.Printf("  第%d页出错：%v\n", pageNo+1, err)
			break
		}
		pageNo++
		if pageNo <= 3 {
			fmt.Printf("  第%d页 (%d 条): %s\n", pageNo, len(p.Rows),
				strings.Join(brief(p.Rows), ", "))
		} else if !p.HasMore {
			fmt.Printf("  第%d页 (%d 条): %s  ← 最后一页\n", pageNo, len(p.Rows),
				strings.Join(brief(p.Rows), ", "))
		}
		collected = append(collected, p.Rows...)
		if !p.HasMore {
			break
		}
		token = p.NextCursor
	}
	fmt.Println()
	want := FilterRows(all, f3)
	fmt.Printf("  筛选结果应有 %d 条，实际翻到 %d 条\n", len(want), len(collected))
	fmt.Printf("  完全一致？%v\n", idsEqual(want, collected))

	fmt.Println()

	fmt.Println("=== 与 JS/前端对比 ===")
	fmt.Println("  ① 前端做筛选是「拿到全量再 filter」，服务端做筛选是「数据库只返回要的行」。")
	fmt.Println("     前者在数据量小时简单好用，S1/S2 的内存 store 就是这么做的；")
	fmt.Println("     但一旦接了后端，筛选必须下推到 SQL，否则响应体会爆炸。")
	fmt.Println("  ② JS 里改筛选条件很容易触发一串连锁更新（useEffect 依赖变化 → 重新请求），")
	fmt.Println("     而游标的分页状态可能被连带清空。本项目的约定是：")
	fmt.Println("     任何筛选条件变化 → 清空 cursor，从第 1 页重新开始。")
	fmt.Println("  ③ 时间处理：JS 的 new Date('2026-10-01') 会按**浏览器本地时区**解析，")
	fmt.Println("     用户在纽约看到的「10 月 1 日」和服务端算的可能差一天。")
	fmt.Println("     这就是 d4 讲的 TIMESTAMP vs TIMESTAMPTZ ——")
	fmt.Println("     本项目所有时间在传输层都用带时区的 ISO 8601 字符串。")

	fmt.Println()
	fmt.Println("=== S3 d15 到此结束 ===")
	fmt.Println("明天讲稳定性：翻页过程中数据被**修改**或**软删**会怎样，")
	fmt.Println("以及为什么「不重复不遗漏」这个承诺需要一个明确的前提条件。")
}

func idsEqual(a, b []Transaction) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].ID != b[i].ID {
			return false
		}
	}
	return true
}

func trunc(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n]
}

func flat(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

code.content:
// =====================================================================
// W12 d16：分页稳定性 —— 翻页过程中数据被改/被删会怎样。
//
// d13/d14/d15 已经建立了两个结论：
//   offset 会因为「新增」而重复/遗漏
//   游标对「新增」免疫（因为新数据只出现在第 1 页）
//
// 今天要把话说完整：游标分页的「不重复不遗漏」承诺是有**前提条件**的。
// 前提是：**排序键不可变**。
//
// 三种真实场景：
//   A. 翻页期间新增数据        → 游标免疫（已证）
//   B. 翻页期间软删了一行      → 游标会「少一行」（安全，可接受）
//   C. 翻页期间**改**了排序键   → 游标会漏/重（危险）
//   D. 翻页期间硬删（物理删）  → 游标会「少一行」
//
// 本文件把这四种场景逐一真跑出来，并给出「快照方案」作为完全解法。
//
// SQL 部分用 GORM DryRun 真实生成；分页/修改逻辑是真实执行的。
// 提醒：本机没有 Postgres，D22 起真库后要把同样的查询跑在真 SQL 上；
// 快照方案依赖事务隔离级别 REPEATABLE READ，真库上要验证 long-running
// 事务不会被 idle_in_transaction_session_timeout 杀掉。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

var fixedNow = time.Date(2026, 10, 15, 12, 0, 0, 0, time.UTC)

type Txn struct {
	ID        string
	Amount    int64
	Note      string
	CreatedAt time.Time // 排序键
	Version   int
	Deleted   bool // 软删标记
	HardGone  bool // 物理删除标记
}

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		NowFunc: func() time.Time { return fixedNow },
		Logger:  logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

// baseData：40 条，第 1 条时间最新
func baseData(n int) []Txn {
	out := make([]Txn, 0, n)
	for i := 1; i <= n; i++ {
		sec := n - i
		out = append(out, Txn{
			ID:        fmt.Sprintf("T%02d", i),
			Amount:    int64(1000 + i*37),
			Note:      fmt.Sprintf("第%d条", i),
			CreatedAt: fixedNow.Add(time.Duration(-sec) * time.Second),
			Version:   1,
		})
	}
	return out
}

func (t Txn) visible() bool { return !t.Deleted && !t.HardGone }

// DBTxn 只用于展示 DryRun 生成的 SQL（DryRun 不返回行，所以字段用不到）
type DBTxn struct {
	ID        string         `gorm:"primaryKey;type:uuid"`
	FamilyID  string         `gorm:"column:family_id;type:uuid;not null"`
	CreatedAt time.Time      `gorm:"column:created_at;not null"`
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

func (DBTxn) TableName() string { return "finance_transaction" }

func tsStr(t time.Time) string { return t.Format("2006-01-02 15:04:05") }

// visibleRows 返回「可见的行」，按 (created_at DESC, id DESC) 排好
func visibleRows(all []Txn) []Txn {
	var out []Txn
	for _, r := range all {
		if r.visible() {
			out = append(out, r)
		}
	}
	sortDesc(out)
	return out
}

func sortDesc(rows []Txn) {
	for i := 1; i < len(rows); i++ {
		for j := i; j > 0; j-- {
			a, b := rows[j-1], rows[j]
			if a.CreatedAt.After(b.CreatedAt) ||
				(a.CreatedAt.Equal(b.CreatedAt) && a.ID > b.ID) {
				break
			}
			rows[j-1], rows[j] = b, a
		}
	}
}

// Cursor 只记位置
type Cursor struct {
	Ts string
	ID string
}

// Walk 是游标分页的标准遍历。
//
// maxPages > 0 时只翻 maxPages 页，并返回最后一页的游标 ——
// 用来模拟「用户先翻了前 1 页，然后数据被改动，接着继续翻」。
// maxPages == 0 时翻到底。
func Walk(all []Txn, size, maxPages int) ([]string, *Cursor) {
	var out []string
	var cur *Cursor
	pages := 0

	for {
		vis := visibleRows(all)
		start := 0
		if cur != nil {
			// 在可见集合里定位到游标之后（对应 SQL 的 (created_at, id) < (?, ?)）
			start = len(vis)
			for i, r := range vis {
				s := tsStr(r.CreatedAt)
				if s < cur.Ts || (s == cur.Ts && r.ID < cur.ID) {
					start = i
					break
				}
			}
		}
		vis = vis[start:]
		if len(vis) == 0 {
			return out, cur
		}
		end := size
		if end > len(vis) {
			end = len(vis)
		}
		out = append(out, idsOf(vis[:end])...)
		last := vis[end-1]
		cur = &Cursor{Ts: tsStr(last.CreatedAt), ID: last.ID}
		pages++
		if maxPages > 0 && pages >= maxPages {
			return out, cur
		}
	}
}

// continueWalk 从给定游标继续往后翻到结束 —— 这就是「点加载更多」
func continueWalk(all []Txn, size int, cur *Cursor) []string {
	var out []string
	for {
		vis := visibleRows(all)
		start := len(vis)
		for i, r := range vis {
			s := tsStr(r.CreatedAt)
			if s < cur.Ts || (s == cur.Ts && r.ID < cur.ID) {
				start = i
				break
			}
		}
		vis = vis[start:]
		if len(vis) == 0 {
			return out
		}
		end := size
		if end > len(vis) {
			end = len(vis)
		}
		out = append(out, idsOf(vis[:end])...)
		last := vis[end-1]
		cur = &Cursor{Ts: tsStr(last.CreatedAt), ID: last.ID}
	}
}

func idsOf(rows []Txn) []string {
	out := make([]string, len(rows))
	for i, r := range rows {
		out[i] = r.ID
	}
	return out
}

func dupOf(s []string) []string {
	c := map[string]int{}
	for _, x := range s {
		c[x]++
	}
	var out []string
	for k, v := range c {
		if v > 1 {
			out = append(out, fmt.Sprintf("%s×%d", k, v))
		}
	}
	// 排序保证输出确定
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j] < out[j-1]; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

func missingFrom(want, got []string) []string {
	w := map[string]bool{}
	for _, x := range want {
		w[x] = true
	}
	g := map[string]bool{}
	for _, x := range got {
		g[x] = true
	}
	var out []string
	for x := range w {
		if !g[x] {
			out = append(out, x)
		}
	}
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j] < out[j-1]; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

// sortedCopy
func sortedCopy(s []string) []string {
	out := append([]string{}, s...)
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j] < out[j-1]; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

func report(title string, baseline []string, got []string) {
	dups := dupOf(got)
	missing := missingFrom(baseline, got)
	fmt.Printf("  %s\n", title)
	fmt.Printf("    基准（翻页前的完整列表）%d 条\n", len(baseline))
	fmt.Printf("    实际拿到% d 条\n", len(got))
	if len(dups) == 0 && len(missing) == 0 {
		fmt.Printf("    ✅ 无重复、无遗漏\n")
	} else if len(dups) == 0 && len(missing) > 0 {
		fmt.Printf("    ⚠️  重复 0，遗漏 %d：%s\n", len(missing), strings.Join(missing, ", "))
	} else if len(dups) > 0 && len(missing) == 0 {
		fmt.Printf("    ❌ 重复 %d：%s（无遗漏）\n", len(dups), strings.Join(dups, ", "))
	} else {
		fmt.Printf("    ❌ 重复 %d：%s\n", len(dups), strings.Join(dups, ", "))
		fmt.Printf("       遗漏 %d：%s\n", len(missing), strings.Join(missing, ", "))
	}
}

func main() {
	const N = 40
	const size = 10

	fmt.Println("=== 1. 先明确「不重复不遗漏」这个承诺的前提 ===")
	fmt.Println("  游标分页保证的是：**在排序键不变的前提下**，")
	fmt.Println("  一次连续遍历不会重复也不会遗漏任何一行。")
	fmt.Println()
	fmt.Println("  排序键是什么？取决于你 ORDER BY 什么。")
	fmt.Println("    ORDER BY created_at DESC, id DESC")
	fmt.Println("      → 排序键是 (created_at, id)")
	fmt.Println("      → created_at 必须不可变")
	fmt.Println()
	fmt.Println("  对记账流水来说，created_at 是「这笔账发生的时间」，")
	fmt.Println("  是不可变的 —— 所以这个前提天然成立。")
	fmt.Println("  但如果你拿 updated_at 排序，前提就不成立了（见场景 C）。")

	fmt.Println()
	fmt.Println("=== 2. 基准：无并发时的完整遍历 ===")
	base := baseData(N)
	baseline := idsOf(visibleRows(base))
	fmt.Printf("  数据 %d 条，每页 %d 条，共 %d 页\n", N, size, (N+size-1)/size)
	clean, _ := Walk(base, size, 0)
	report("完整遍历结果：", baseline, clean)
	fmt.Println()
	fmt.Println("  ✅ 这是基准线。后面三个场景都跟它对比。")

	fmt.Println()
	fmt.Println("=== 3. 场景 A：翻到第 2 页时新增 3 条数据 ===")
	mutA := baseData(N)
	// 模拟：取完第 1 页之后，有人记了 3 笔新的（时间戳最新 → 排在最前）
	firstPage, curA := Walk(base, size, 1)
	fmt.Printf("  第 1 页已拿到: %s\n", strings.Join(firstPage, ", "))
	fmt.Printf("  游标         : T=%s I=%s\n", curA.Ts, curA.ID)
	// 插入
	for k := 1; k <= 3; k++ {
		newT := Txn{
			ID:        fmt.Sprintf("NEW%d", k),
			CreatedAt: fixedNow.Add(time.Duration(k) * time.Second),
			Version:   1,
			Note:      fmt.Sprintf("并发新增 %d", k),
		}
		mutA = append(mutA, newT)
	}
	// 接着从第 2 页继续（游标 = 第 1 页最后一行 T10）
	// 真正的续翻：用第 1 页的游标接着往下走
	restA := continueWalk(mutA, size, curA)
	gotA := append(append([]string{}, firstPage...), restA...)
	// 基准要加上新增的数据（新数据本来也该被看到）
	baselineA := append([]string{"NEW1", "NEW2", "NEW3"}, baseline...)
	fmt.Println()
	report("场景 A（新增 3 条）：", baselineA, gotA)
	fmt.Println()
	fmt.Println("  ✅ 结论：新增的数据排在最前（时间戳最新），")
	fmt.Println("     它出现在第 1 页（在新增之前取的，所以这次遍历里看不到），")
	fmt.Println("     但它不会把后面的行挤走 —— 所以老数据一条不少。")
	fmt.Println()
	fmt.Println("  注意 baselineA 里的 NEW1..NEW3 没出现在 gotA 里，")
	fmt.Println("  这是**正确**的：它们的时间戳比第 1 页游标更新，")
	fmt.Println("  在「按 created_at 倒序」下本来就属于第 1 页之前的区域。")
	fmt.Println("  下次用户刷新页面就会看到它们。")

	fmt.Println()
	fmt.Println("=== 4. 场景 B：翻页期间软删了一行 ===")
	mutB := baseData(N)
	firstPageB, curB := Walk(base, size, 1)
	// 第 2 页中间的一行被软删
	for i := range mutB {
		if mutB[i].ID == "T15" {
			mutB[i].Deleted = true
			mutB[i].Version++
		}
	}
	restB := continueWalk(mutB, size, curB)
	gotB := append(append([]string{}, firstPageB...), restB...)
	fmt.Println()
	report("场景 B（软删 T15）：", baseline, gotB)
	fmt.Println()
	fmt.Println("  ⚠️ 结果：少了 T15，没有重复。")
	fmt.Println()
	fmt.Println("  这是**可以接受**的，而且比「重复」好得多：")
	fmt.Println("    ① 用户已经能看到数据变少了（比如这一页只有 9 条），")
	fmt.Println("       他能感知到。")
	fmt.Println("    ② 不会出现「同一条账目出现两次」这种更诡异的现象。")
	fmt.Println("    ③ 对于「查看历史流水」这个场景，少一条被删的数据是正确的语义 ——")
	fmt.Println("       它本来就已经被删了，不该继续显示。")
	fmt.Println()
	fmt.Println("  反过来说，如果你的场景是「对账」（要求总数精确），")
	fmt.Println("  那就不能接受这种漂移，必须用第 7 节的快照方案。")

	fmt.Println()
	fmt.Println("=== 5. 场景 C：翻页期间改了排序键（危险）===")
	mutC := baseData(N)
	firstPageC, curC := Walk(base, size, 1)
	// T15 的 created_at 被改到「第 1 页区间」
	// 这模拟「用户编辑了一笔账的日期」
	for i := range mutC {
		if mutC[i].ID == "T15" {
			mutC[i].CreatedAt = base[34].CreatedAt // 落到第 1 页区间附近
			mutC[i].Version++
		}
	}
	restC := continueWalk(mutC, size, curC)
	gotC := append(append([]string{}, firstPageC...), restC...)
	fmt.Println()
	report("场景 C（把 T15 的 created_at 改到第 1 页区间）：", baseline, gotC)
	fmt.Println()
	fmt.Println("  ❌ 分析：")
	fmt.Println("     T15 原本在第 2 页（T11~T20）。")
	fmt.Println("     它的 created_at 被改早之后，位置移到了第 1 页区间（T36~T40）。")
	fmt.Println("     但第 1 页在改动**之前**就已经取走了，所以这次遍历里 T15 被跳过了。")
	fmt.Println("     更糟的情况是反方向：把一行改**晚**，它会从已翻过的区域")
	fmt.Println("     跳到未翻过的区域，于是被显示**两次**。")
	fmt.Println()
	fmt.Println("  这个场景在记账系统里真的会发生：用户补记一笔，")
	fmt.Println("  或者事后修正日期。")
	fmt.Println()
	fmt.Println("  规避办法（三选一）：")
	fmt.Println("    ① **不要用会变的字段排序**。用 created_at（创建时间），")
	fmt.Println("       它是不可变的；不要用 updated_at。")
	fmt.Println("    ② 用一个单调递增的不可变列做排序键（比如雪花 ID / 序列）。")
	fmt.Println("    ③ 用快照（第 7 节）—— 排序键即使变了，快照里还是旧值。")

	fmt.Println()
	fmt.Println("=== 6. 场景 D：翻页期间物理删除（硬删）===")
	mutD := baseData(N)
	firstPageD, curD := Walk(base, size, 1)
	for i := range mutD {
		if mutD[i].ID == "T25" {
			mutD[i].HardGone = true
		}
	}
	restD := continueWalk(mutD, size, curD)
	gotD := append(append([]string{}, firstPageD...), restD...)
	fmt.Println()
	report("场景 D（硬删 T25）：", baseline, gotD)
	fmt.Println()
	fmt.Println("  ⚠️ 结果：和场景 B 一样，少一行，没有重复。")
	fmt.Println()
	fmt.Println("  但硬删在生产上有个额外风险：如果那一行刚好是「当前页的最后一行」，")
	fmt.Println("  游标的定位值就指向了一个已不存在的行。")
	fmt.Println("  好在 WHERE (created_at, id) < (?, ?) 不要求那行存在 ——")
	fmt.Println("  它只需要「所有满足条件的行」。所以游标分页天然容忍目标行消失。")
	fmt.Println("  这是游标相对于「按 id 记录上一页最后一个 id 再 JOIN 查」的优势：")
	fmt.Println("  后者如果那行没了，查询会返回空结果，用户以为到底了。")

	fmt.Println()
	fmt.Println("=== 7. 完全解法：快照分页（Snapshot Pagination）===")
	fmt.Println("  如果你的场景**不允许任何漂移**（对账、导出、审计），")
	fmt.Println("  正确做法是让整次遍历在同一个数据库快照里完成。")
	fmt.Println()
	fmt.Println("  原理：Postgres 的 REPEATABLE READ 隔离级别下，")
	fmt.Println("  一个事务内的所有 SELECT 看到的是**事务开始那一刻**的数据快照。")
	fmt.Println("  事务没提交之前，别人怎么改都影响不到你。")
	fmt.Println()
	fmt.Println("  实现方式：把「整次遍历」包在一个长事务里。")
	fmt.Println("  ⚠️ 但这有两个硬约束：")
	fmt.Println("    ① HTTP 是无状态的 —— 前端翻第 5 页是**另一个请求**，")
	fmt.Println("       不可能和第 1 页在同一个事务里。")
	fmt.Println("       所以「一次遍历 = 一个事务」在 HTTP 下做不到。")
	fmt.Println("    ② 只能退而求其次：给每页一个快照标识（比如 created_at <= 请求时刻），")
	fmt.Println("       叫「时间锚点」。这能做到「新增不影响本次遍历」，")
	fmt.Println("       但**软删和修改仍然会影响** —— 因为锚点只是时间上界，")
	fmt.Println("       不是 MVCC 快照。")

	fmt.Println()
	fmt.Println("  时间锚点的实现（这是本项目采用的方案）：")
	fmt.Println("    WHERE family_id = ?")
	fmt.Println("      AND created_at < ?      -- 锚点，第一页时由服务端生成")
	fmt.Println("      AND (created_at, id) < (?, ?)  -- 游标")
	fmt.Println("      AND created_at <= ?     -- 时间窗口的上界")
	fmt.Println("      AND deleted_at IS NULL")
	fmt.Println("    ORDER BY created_at DESC, id DESC")
	dbg := dryDB()
	st := dbg.Session(&gorm.Session{DryRun: true}).
		Where("family_id = ? AND created_at < ? AND (created_at, id) < (?, ?) AND deleted_at IS NULL",
			famA, "2026-10-15 12:00:00", "2026-10-15 11:59:50", "T10").
		Order("created_at DESC, id DESC").Limit(size).Find(&[]DBTxn{})
	fmt.Printf("    %s\n", flat(st.Statement.SQL.String()))
	fmt.Println()
	fmt.Println("  注意 created_at < 锚点 这个条件在**每一页**都要带上，")
	fmt.Println("  锚点由服务端在第一页生成后放在游标里返回给前端。")
	fmt.Println("  这样即使翻页期间有新增数据，也不会混进本次遍历。")

	fmt.Println()
	fmt.Println("  各方案的取舍：")
	fmt.Println("  ┌──────────────┬────────┬────────┬────────┬────────┐")
	fmt.Println("  │ 方案         │ 新增   │ 软删   │ 改排序键│ 复杂度 │")
	fmt.Println("  ├──────────────┼────────┼────────┼────────┼────────┤")
	fmt.Println("  │ offset       │ 重复   │ 少一行 │ 重复   │ 最低   │")
	fmt.Println("  │ 游标         │ 免疫   │ 少一行 │ 漏/重  │ 低     │")
	fmt.Println("  │ 游标+时间锚点│ 免疫   │ 少一行 │ 漏/重  │ 中     │")
	fmt.Println("  │ MVCC 快照    │ 免疫   │ 免疫   │ 免疫   │ 高     │")
	fmt.Println("  └──────────────┴────────┴────────┴────────┴────────┘")
	fmt.Println()
	fmt.Println("  本项目选「游标 + 时间锚点」：")
	fmt.Println("    ① 记账流水是追加为主、软删为辅的业务，不需要 MVCC 那么重")
	fmt.Println("    ② 时间锚点顺带解决了「导出时数据一直变」的体验问题")
	fmt.Println("    ③ 需要绝对一致时，走另一个「导出」接口（异步任务 + 快照）")

	fmt.Println()
	fmt.Println("=== 8. 与 JS/前端对比 ===")
	fmt.Println("  ① 前端内存数组分页（比如 slice(0, 10)）根本没有这个问题 ——")
	fmt.Println("     因为数组在同一时刻只有一个版本，不存在「翻页期间数据变了」。")
	fmt.Println("     这就是「内存开发时感受不到这类 bug」的根本原因。")
	fmt.Println("     一旦接了数据库，同样的 UI 代码立刻暴露在这个问题下。")
	fmt.Println("  ② JS 里做「一致性快照」的常见做法是先全量拉到前端再分页，")
	fmt.Println("     这在几百条数据时可接受，但会：")
	fmt.Println("       - 响应体大（1 万条流水 ≈ 几 MB JSON）")
	fmt.Println("       - 首屏变慢（要等全量下载完才能渲染）")
	fmt.Println("       - 移动端流量杀手")
	fmt.Println("     所以正确做法还是服务端分页 + 游标。")
	fmt.Println("  ③ React 里有个常见的坑：用 useEffect 依赖 [page, filters]，")
	fmt.Println("     翻页时如果 filters 引用变了（对象每次渲染都是新的），")
	fmt.Println("     会触发重复请求，甚至出现竞态（后发先至 → 数据显示错乱）。")
	fmt.Println("     用游标 + 请求取消（AbortController）能缓解，")
	fmt.Println("     但根因还是「状态管理没做对」——和数据库无关。")

	fmt.Println()
	fmt.Println("=== S3 d16 到此结束 ===")
	fmt.Println("明天讲索引设计与 EXPLAIN：今天说的「(family_id, created_at DESC, id DESC)」")
	fmt.Println("这个复合索引到底长什么样、为什么列顺序要这么排、")
	fmt.Println("以及怎么用 EXPLAIN 确认真走上了它。")
}

func flat(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

