// =====================================================================
// W12 d19：漏洞演示 —— 改一个 id 就能看到别人的数据，以及怎么测出来。
//
// d18 讲了「漏加 WHERE family_id」这个结构性错误。
// 今天做两件事：
//   ① 把它变成一次**真实的攻击**：用户不改任何代码，只改 URL 里的 id
//   ② 给出**能抓住它**的测试方法，并真跑一遍证明测试有效
//
// 攻击部分全是内存模拟（本机没有 Postgres），
// 但攻击路径、请求参数、响应内容都按真实 HTTP 接口的形式呈现。
// SQL 用 GORM DryRun 真实生成。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

const (
	famA = "aaaaaaaa-0000-4000-8000-000000000001"
	famB = "bbbbbbbb-0000-4000-8000-000000000002"
)

func shortID(s string) string {
	if len(s) >= 8 {
		return s[:8]
	}
	return s
}
func famName(f string) string {
	if f == famA {
		return "家庭A"
	}
	if f == famB {
		return "家庭B"
	}
	return "?"
}

type Txn struct {
	ID        string         `gorm:"primaryKey;type:uuid"`
	FamilyID  string         `gorm:"column:family_id;type:uuid;not null;index"`
	Amount    int64          `gorm:"column:amount;not null"`
	Note      string         `gorm:"column:note;type:varchar(200)"`
	Version   int            `gorm:"column:version;not null;default:1"`
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

func (Txn) TableName() string { return "finance_transaction" }

// 固定时间戳：软删 SQL 里会带上 NowFunc() 的结果，
// 用真实时间会导致两次运行输出不同 —— 而 expect 必须是确定的。
var fixedNow = time.Date(2026, 10, 15, 9, 30, 0, 0, time.UTC)

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		NowFunc: func() time.Time { return fixedNow },
		Logger:  logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

// ---- 服务端状态（模拟数据库）----

type server struct {
	txns []Txn
}

func newServer() *server {
	return &server{txns: []Txn{
		{ID: "11111111-0000-4000-8000-000000000001", FamilyID: famA, Amount: 1137, Note: "超市买菜"},
		{ID: "11111111-0000-4000-8000-000000000002", FamilyID: famA, Amount: 1274, Note: "地铁通勤"},
		{ID: "22222222-0000-4000-8000-000000000001", FamilyID: famB, Amount: 8888, Note: "房租"},
		{ID: "22222222-0000-4000-8000-000000000002", FamilyID: famB, Amount: 65000, Note: "年终奖入账"},
		{ID: "22222222-0000-4000-8000-000000000003", FamilyID: famB, Amount: 2300, Note: "私立学校学费"},
	}}
}

// ---- 两个版本的接口实现 ----

// 有 bug 的实现：只按 id 查，忘了 family_id
func (s *server) GetByIDVulnerable(attackerFamily, id string) (Txn, bool) {
	for _, r := range s.txns {
		if r.ID == id {
			return r, true
		}
	}
	return Txn{}, false
}

// 正确的实现：id + family_id 双条件
func (s *server) GetByIDSafe(attackerFamily, id string) (Txn, bool) {
	for _, r := range s.txns {
		if r.ID == id && r.FamilyID == attackerFamily {
			return r, true
		}
	}
	return Txn{}, false
}

func main() {
	fmt.Println("=== 1. 攻击者的视角：他手里有什么 ===")
	srv := newServer()
	fmt.Println("  攻击者（家庭A 的用户）合法持有的数据：")
	for _, r := range srv.txns {
		if r.FamilyID == famA {
			fmt.Printf("    %s  %6d  %s\n", r.ID, r.Amount, r.Note)
		}
	}
	fmt.Println()
	fmt.Println("  他知道的东西：")
	fmt.Println("    · 自己 token 里的 family_id = " + shortID(famA))
	fmt.Println("    · 接口是 GET /api/finance/transactions/{id}")
	fmt.Println("    · **别人的 id 长什么样？** —— 这里有个关键问题，见第 5 节")
	fmt.Println()
	fmt.Println("  他要做的唯一一件事：把 URL 里的 id 换掉。")

	fmt.Println()
	fmt.Println("=== 2. 攻击演示：有 bug 的实现 ===")
	target := "22222222-0000-4000-8000-000000000002" // 家庭B 的「年终奖入账」
	fmt.Printf("  请求：GET /api/finance/transactions/%s\n", target)
	fmt.Printf("  Authorization: Bearer <家庭A的token>\n")
	fmt.Println()
	row, ok := srv.GetByIDVulnerable(famA, target)
	fmt.Println("  响应 200 OK：")
	fmt.Printf("    {\n      \"code\": 0,\n      \"message\": \"ok\",\n")
	fmt.Printf("      \"data\": {\n        \"id\": \"%s\",\n", row.ID)
	fmt.Printf("        \"amount\": %d,\n", row.Amount)
	fmt.Printf("        \"note\": \"%s\"\n      },\n", row.Note)
	fmt.Printf("      \"request_id\": \"req-20261015-000042\"\n    }\n")
	if ok {
		fmt.Println()
		fmt.Println("  ❌❌ 家庭B 的数据被返回给了家庭A 的用户。")
		fmt.Println()
		fmt.Println("  注意攻击者**没有做任何技术上的事**：")
		fmt.Println("    · 他没有伪造 token（用的是自己合法的 token）")
		fmt.Println("    · 他没有绕过任何鉴权")
		fmt.Println("    · 他只改了一个自己有权访问的资源路径参数")
		fmt.Println("  这类漏洞叫 IDOR（不安全的直接对象引用），")
		fmt.Println("  在 OWASP Top 10 里排得很前，而且**扫描器很难自动发现** ——")
		fmt.Println("  因为从外面看，这个请求完全合法（带了有效 token、返回了 200）。")
	}

	fmt.Println()
	fmt.Println("  他还能试出什么：")
	for _, r := range srv.txns {
		if r.FamilyID == famB {
			got, ok := srv.GetByIDVulnerable(famA, r.ID)
			status := "404"
			body := "resource not found"
			if ok {
				status = "200"
				body = fmt.Sprintf("%d 元 · %s", got.Amount, got.Note)
			}
			fmt.Printf("    %s → %s  %s\n", r.ID, status, body)
		}
	}
	fmt.Println()
	fmt.Println("  → 家庭B 的全部数据都被枚举出来了。")
	fmt.Println("    「年终奖入账 65000」这种信息本身就极具价值。")

	fmt.Println()
	fmt.Println("=== 3. 同一攻击，打正确的实现 ===")
	fmt.Printf("  请求：GET /api/finance/transactions/%s\n", target)
	fmt.Println()
	_, ok2 := srv.GetByIDSafe(famA, target)
	if !ok2 {
		fmt.Println("  响应 404 Not Found：")
		fmt.Print("    {\n      \"code\": 40402,\n      \"message\": \"流水不存在\",\n")
		fmt.Println("      \"data\": null,\n      \"request_id\": \"req-20261015-000043\"\n    }")
		fmt.Println()
		fmt.Println("  ✅ 家庭A 的用户拿不到家庭B 的数据。")
		fmt.Println()
		fmt.Println("  ⚠️ 关于 404 vs 403，这里有个安全上的取舍：")
		fmt.Println("     · 返回 403「无权限」→ 攻击者知道这个 id **确实存在**，")
		fmt.Println("       只是没权限。可以用它来枚举「哪些 id 是真实存在的」。")
		fmt.Println("     · 返回 404「不存在」→ 攻击者无法区分「不存在」和「无权限」，")
		fmt.Println("       枚举难度大幅上升。")
		fmt.Println("     本项目选 404：对外统一说「不存在」，对内通过日志记录真实原因。")
		fmt.Println("     这不是技术规定，是产品决策 —— 但要知道它是有意的选择。")
	}

	fmt.Println()
	fmt.Println("=== 4. 正确的 SQL 是什么样（DryRun 真实生成）===")
	dbg := dryDB()
	fmt.Println("  ❌ 有 bug 的写法（只按 id）")
	st := dbg.Session(&gorm.Session{DryRun: true}).Where("id = ?", target).First(&Txn{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))

	fmt.Println()
	fmt.Println("  ✅ 正确写法（id + family_id）")
	st = dbg.Session(&gorm.Session{DryRun: true}).
		Where("id = ? AND family_id = ?", target, famA).First(&Txn{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))

	fmt.Println()
	fmt.Println("  ✅ 列表查询")
	st = dbg.Session(&gorm.Session{DryRun: true}).
		Where("family_id = ?", famA).Limit(20).Find(&[]Txn{})
	fmt.Printf("     %s\n", flat(st.Statement.SQL.String()))

	fmt.Println()
	fmt.Println("  ✅ 删除（写操作同样要带）")
	fmt.Printf("     %s\n", flat(dbg.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Where("id = ? AND family_id = ?", target, famA).Delete(&Txn{ID: target})
	})))
	fmt.Println()
	fmt.Println("  一个代码结构的建议：把 family_id 做成**必填的上下文**，")
	fmt.Println("  而不是每个方法的普通参数。这样「忘记传」会变成编译错误。")

	fmt.Println()
	fmt.Println("=== 5. 现实里的难点：攻击者怎么拿到别人的 id ===")
	fmt.Println("  你可能会想：UUID 这么长，攻击者怎么知道该试哪个？")
	fmt.Println()
	vectors := []struct{ vector, difficulty, detail string }{
		{"自增整数主键", "极易", "1, 2, 3... 一扫一个准。UUID 主键在这点上确实更好"},
		{"可预测的 UUID（v1）", "较易", "v1 UUID 含时间戳和 MAC 地址，可以算出相邻的值"},
		{"在别处泄露的 id", "易", "日志、错误信息、分享链接、导出文件里可能已经出现了"},
		{"通过其他接口拿到的 id", "易", "比如「最近记账的用户排行」这类接口（如果存在）"},
		{"纯暴力猜测", "难但可行", "取决于 id 空间。短 id（6 位数字）几小时就能扫完"},
	}
	fmt.Printf("  %-24s %-12s %s\n", "泄露途径", "难度", "说明")
	for _, v := range vectors {
		fmt.Printf("  %-24s %-12s %s\n", v.vector, v.difficulty, v.detail)
	}
	fmt.Println()
	fmt.Println("  结论：**不要把「id 难猜」当作安全措施。**")
	fmt.Println("  它只是把攻击成本从「零」提高到「高」，不解决根本问题。")
	fmt.Println("  根本措施是：每个查询都强制带上租户条件（今天讲的）+")
	fmt.Println("  数据库层兜底（明天讲的 RLS）。")
	fmt.Println()
	fmt.Println("  本项目用 UUID v4 是为了不暴露「有多少条数据」和「插入顺序」，")
	fmt.Println("  属于「减少信息泄露」，不属于「访问控制」。")

	fmt.Println()
	fmt.Println("=== 6. 测试方法：怎么让这个 bug 逃不出去 ===")
	fmt.Println()
	fmt.Println("  方法一：多租户 fixture（最基础，也最容易被忽略）")
	fmt.Println("    ❌ 测试里只有一个家庭的数据")
	fmt.Println("       → 任何漏加 family_id 的查询都能返回「正确结果」，测试永远绿")
	fmt.Println("    ✅ fixture 至少准备 2 个家庭，且 id 有规律（便于断言）")
	test1 := []struct{ id, wantA, wantB string }{
		{"txn-A-01", "200", "404"},
		{"txn-A-02", "200", "404"},
		{"txn-B-01", "404", "200"},
		{"txn-B-02", "404", "200"},
	}
	fmt.Println()
	fmt.Println("    跨租户访问矩阵（真实期望）：")
	fmt.Printf("      %-14s %-12s %s\n", "id", "家庭A 请求", "家庭B 请求")
	for _, c := range test1 {
		fmt.Printf("      %-14s %-12s %s\n", c.id, c.wantA, c.wantB)
	}
	fmt.Println()
	fmt.Println("    这张表就是「越权测试矩阵」。只要有一个格子反了，测试就红。")

	fmt.Println()
	fmt.Println("  方法二：通用断言（写一次，到处用）")
	fmt.Println("    // 每个返回行的接口测试都加这一段")
	fmt.Println("    for _, row := range resp.Data.Items {")
	fmt.Println("      require.Equal(t, currentFamilyID, row.FamilyID, \"跨租户数据泄露\")")
	fmt.Println("    }")
	fmt.Println()
	fmt.Println("    它甚至不需要第二个家庭的数据 ——")
	fmt.Println("    只要有数据，行里的 family_id 就是证据。")
	fmt.Println("    但它查不出「完全没过滤且表里只有一个家庭」的情况，")
	fmt.Println("    所以两个方法要配合。")

	fmt.Println()
	fmt.Println("  方法三：静态检查（把纪律变成规则）")
	fmt.Println("    方案 A：golangci-lint 自定义规则")
	fmt.Println("      禁止在仓储层出现不带 family_id 的 Where")
	fmt.Println("    方案 B：更简单的土办法 —— grep 门禁")
	fmt.Println("      # 找出所有 .Where(\"...id...\" 的调用，人工确认是否还有 family_id")
	fmt.Println("      grep -rn '\\.Where(' server/internal/store/ | grep -v family_id")
	fmt.Println()
	fmt.Println("    方案 C：接口层强制")
	fmt.Println("      所有 store 方法的第一个参数都是 familyID，")
	fmt.Println("      编译期就锁死「不能忘」。")

	fmt.Println()
	fmt.Println("  方法四：真跑一遍，证明测试有效")
	fmt.Println()
	fmt.Println("  下面把「有 bug 的实现」放进测试里，看它能不能被抓到：")
	fmt.Println()

	// 真跑测试逻辑
	targetID := "22222222-0000-4000-8000-000000000002"
	leakA := checkIsolation(srv.GetByIDVulnerable, famA, targetID)
	fmt.Println("  用例：家庭A 的 token 请求家庭B 的 id")
	fmt.Println("  期望：404（拿不到别人的数据）")
	if leakA {
		fmt.Println("  实际：200，返回了家庭B 的数据")
		fmt.Println("  结果：❌ 测试失败 —— bug 被抓到了")
	} else {
		fmt.Println("  实际：404")
		fmt.Println("  结果：✅ 测试通过")
	}
	fmt.Println()
	leakB := checkIsolation(srv.GetByIDSafe, famA, targetID)
	fmt.Println("  用例：同一个请求，打正确的实现")
	fmt.Println("  期望：404")
	if leakB {
		fmt.Println("  实际：200，泄露")
		fmt.Println("  结果：❌ 测试失败 —— 说明正确实现也有问题")
	} else {
		fmt.Println("  实际：404")
		fmt.Println("  结果：✅ 测试通过 —— 正确实现守住了")
	}

	fmt.Println()
	if leakA {
		fmt.Println("  → 测试有效地抓到了 bug。这正是它该起的作用。")
		fmt.Println("  → 如果这个测试存在，d18 那个 43% 泄露率的 bug 根本进不了 main。")
	} else {
		fmt.Println("  → ❌ 测试没抓到，说明测试写得不对（这比 bug 本身更可怕）")
	}

	fmt.Println()
	fmt.Println("=== 7. 越权测试应该放在哪一层 ===")
	levels := []struct{ level, scope, speed, catches string }{
		{"单元测试", "单个 store 方法", "毫秒级", "逻辑错误（条件写错）"},
		{"仓储契约测试", "整个 store 包", "秒级", "新增方法忘了加过滤 ← 最容易漏"},
		{"接口集成测试", "HTTP 端到端", "秒级", "中间件没传下 family_id"},
		{"端到端测试", "真实用户路径", "分钟级", "组合场景"},
		{"线上巡检", "生产数据抽样", "每天", "代码里完全没想到的路径"},
	}
	fmt.Printf("  %-16s %-20s %-10s %s\n", "层次", "范围", "速度", "能抓什么")
	for _, l := range levels {
		fmt.Printf("  %-16s %-20s %-10s %s\n", l.level, l.scope, l.speed, l.catches)
	}
	fmt.Println()
	fmt.Println("  重点在第二行：**仓储契约测试**。")
	fmt.Println("  因为新增一个查询方法时，最容易的就是「忘了加 family_id」，")
	fmt.Println("  而契约测试可以做到：给 store 包写一个通用测试，")
	fmt.Println("  对该包下**所有**返回行的方法自动跑一遍隔离断言。")
	fmt.Println("  这样新人加方法时不用记得写测试，测试已经自动覆盖了。")

	fmt.Println()
	fmt.Println("=== 8. 与 JS/前端对比 ===")
	fmt.Println("  ① 这是典型的「后端安全」问题，前端框架帮不上忙。")
	fmt.Println("     React 里你怎么写都拦不住 —— 请求是用户用 curl 发的，不是你的组件发的。")
	fmt.Println("     这类问题必须在服务端解决。")
	fmt.Println("  ② 前端常见的对应错误是「信任前端传来的 userId」：")
	fmt.Println("     fetch('/api/orders?userId=' + userId)  ← userId 来自前端状态")
	fmt.Println("     后端如果照单全收，就是同一个漏洞。")
	fmt.Println("     正确做法和今天一样：从 token 推导，不接受客户端指定。")
	fmt.Println("  ③ JS 生态有 helmet、express-rate-limit 之类的中间件，")
	fmt.Println("     但没有任何一个能自动做租户隔离 —— 它必须知道你的业务模型。")
	fmt.Println("     Go 这边也一样（Gin 没有自动隔离中间件）。")
	fmt.Println("     所以这不能指望框架，只能靠约定 + 测试 + 数据库兜底。")

	fmt.Println()
	fmt.Println("=== 9. 明天预告 ===")
	fmt.Println("  今天说「靠纪律就会漏」。明天讲数据库层的兜底：")
	fmt.Println("  Row Level Security —— 即使应用层忘了加 WHERE，")
	fmt.Println("  数据库也会把别人的行过滤掉。")
	fmt.Println("  这是本项目唯一能「即使代码写错也不泄露」的机制。")
}

// checkIsolation 就是那个越权测试：请求别家的 id，应该拿不到
func checkIsolation(fn func(string, string) (Txn, bool), attackerFamily, targetID string) (leaked bool) {
	row, ok := fn(attackerFamily, targetID)
	if !ok {
		return false
	}
	return row.FamilyID != attackerFamily
}

func flat(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

