// =====================================================================
// W12 d19：漏洞演示 —— 改一个 id 就能看到别人的数据，以及怎么测出来。
//
// d18 讲了「漏加 WHERE family_id」这个结构性错误。
// 今天做两件事：
//   ① 把它变成一次**真实的攻击**：用户不改任何代码，只改 URL 里的 id
//   ② 给出**能抓住它**的测试方法，并真跑一遍证明测试有效
//
// 攻击部分全是内存模拟（本机没有 Postgres），
// 但攻击路径、请求参数、响应内容都按真实 HTTP 接口的形式呈现。
// SQL 用 GORM DryRun 真实生成。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

const (
	famA = "aaaaaaaa-0000-4000-8000-000000000001"
	famB = "bbbbbbbb-0000-4000-8000-000000000002"
)

func shortID(s string) string {
	if len(s) >= 8 {
		return s[:8]
	}
	return s
}
func famName(f string) string {
	if f == famA {
		return "家庭A"
	}
	if f == famB {
		return "家庭B"
	}
	return "?"
}

type Txn struct {
	ID        string         `gorm:"primaryKey;type:uuid"`
	FamilyID  string         `gorm:"column:family_id;type:uuid;not null;index"`
	Amount    int64          `gorm:"column:amount;not null"`
	Note      string         `gorm:"column:note;type:varchar(200)"`
	Version   int            `gorm:"column:version;not null;default:1"`
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

func (Txn) TableName() string { return "finance_transaction" }

// 固定时间戳：软删 SQL 里会带上 NowFunc() 的结果，
// 用真实时间会导致两次运行输出不同 —— 而 expect 必须是确定的。
var fixedNow = time.Date(2026, 10, 15, 9, 30, 0, 0, time.UTC)

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		NowFunc: func() time.Time { return fixedNow },
		Logger:  logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

// ---- 服务端状态（模拟数据库）----

type server struct {
	txns []Txn
}

func newServer() *server {
	return &server{txns: []Txn{
		{ID: "11111111-0000-4000-8000-000000000001", FamilyID: famA, Amount: 1137, Note: "超市买菜"},
		{ID: "11111111-0000-4000-8000-000000000002", FamilyID: famA, Amount: 1274, Note: "地铁通勤"},
		{ID: "22222222-0000-4000-8000-000000000001", FamilyID: famB, Amount: 8888, Note: "房租"},
		{ID: "22222222-0000-4000-8000-000000000002", FamilyID: famB, Amount: 65000, Note: "年终奖入账"},
		{ID: "22222222-0000-4000-8000-000000000003", FamilyID: famB, Amount: 2300, Note: "私立学校学费"},
	}}
}

// ---- 两个版本的接口实现 ----

// 有 bug 的实现：只按 id 查，忘了 family_id
func (s *server) GetByIDVulnerable(attackerFamily, id string) (Txn, bool) {
	for _, r := range s.txns {
		if r.ID == id {
			return r, true
		}
	}
	return Txn{}, false
}

// 正确的实现：id + family_id 双条件
func (s *server) GetByIDSafe(attackerFamily, id string) (Txn, bool) {
	for _, r := range s.txns {
		if r.ID == id && r.FamilyID == attackerFamily {
			return r, true
		}
	}
	return Txn{}, false
}

	fmt.Println("=== 8. 与 JS/前端对比 ===")
	fmt.Println("  ① 这是典型的「后端安全」问题，前端框架帮不上忙。")
	fmt.Println("     React 里你怎么写都拦不住 —— 请求是用户用 curl 发的，不是你的组件发的。")
	fmt.Println("     这类问题必须在服务端解决。")
	fmt.Println("  ② 前端常见的对应错误是「信任前端传来的 userId」：")
	fmt.Println("     fetch('/api/orders?userId=' + userId)  ← userId 来自前端状态")
	fmt.Println("     后端如果照单全收，就是同一个漏洞。")
	fmt.Println("     正确做法和今天一样：从 token 推导，不接受客户端指定。")
	fmt.Println("  ③ JS 生态有 helmet、express-rate-limit 之类的中间件，")
	fmt.Println("     但没有任何一个能自动做租户隔离 —— 它必须知道你的业务模型。")
	fmt.Println("     Go 这边也一样（Gin 没有自动隔离中间件）。")
	fmt.Println("     所以这不能指望框架，只能靠约定 + 测试 + 数据库兜底。")

	fmt.Println()
	fmt.Println("=== 9. 明天预告 ===")
	fmt.Println("  今天说「靠纪律就会漏」。明天讲数据库层的兜底：")
	fmt.Println("  Row Level Security —— 即使应用层忘了加 WHERE，")
	fmt.Println("  数据库也会把别人的行过滤掉。")
	fmt.Println("  这是本项目唯一能「即使代码写错也不泄露」的机制。")
}

