// =====================================================================
// W12 d20：数据库层兜底 —— schema / 账号权限 / Row Level Security。
//
// 前两天讲了：靠应用层纪律（每条查询带 family_id）会漏。
// 今天讲「即使代码写错也不泄露」的三层数据库机制：
//
//   第 1 层：schema 隔离      —— 每域一个 schema，服务账号只 GRANT 自己那个 schema
//   第 2 层：账号权限        —— 撤掉不需要的权限（比如禁止 TRUNCATE/DDL）
//   第 3 层：Row Level Security —— 行级策略，漏加 WHERE 也过滤得掉
//
// RLS 是本项目唯一「即使代码写错也不泄露」的机制，所以今天重点讲它。
//
// ⚠️ 诚实声明：本机没有 Postgres，所以 RLS 的**实际拦截效果**没有在这里跑过。
// 本文件做的是：
//   ① 给出完整可执行的 DDL（D22 起库后直接跑）
//   ② 用 Go 模拟 RLS 策略的执行时机和效果（逻辑等价，机制不同）
//   ③ 给出 EXPLAIN 和验证步骤
// =====================================================================

package main

import (
	"fmt"
	"strings"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"
const famB = "bbbbbbbb-0000-4000-8000-000000000002"

func shortID(s string) string {
	if len(s) >= 8 {
		return s[:8]
	}
	return s
}

type Txn struct {
	ID        string         `gorm:"primaryKey;type:uuid"`
	FamilyID  string         `gorm:"column:family_id;type:uuid;not null;index"`
	Amount    int64          `gorm:"column:amount;not null"`
	Note      string         `gorm:"column:note;type:varchar(200)"`
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

func (Txn) TableName() string { return "finance_transaction" }

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		Logger: logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

// =====================================================================
// 模拟 RLS：一个会拦截「漏加 WHERE」查询的过滤器
// =====================================================================

// rlsContext 模拟「当前连接的租户上下文」。
// 真实 Postgres 里它存在 session 变量 app.family_id 里。
type rlsContext struct {
	// familyID 就是 SET LOCAL app.family_id 的值
	familyID string
	// enabled 表示 RLS 策略是否生效
	enabled bool
	// isOwner 表示连接用的是表的 owner 账号（owner 默认绕过 RLS！）
	isOwner bool
}

type rlsRow struct {
	ID       string
	FamilyID string
	Amount   int64
	Note     string
}

// selectSim 模拟一次 SELECT，并说明 RLS 在哪一步生效
func selectSim(rows []rlsRow, ctx rlsContext, whereFamilyID, whereID string) (returned []rlsRow, note string) {
	// ── 第 1 步：执行用户写的 WHERE 子句 ──
	var afterWhere []rlsRow
	for _, r := range rows {
		keep := true
		if whereFamilyID != "" && r.FamilyID != whereFamilyID {
			keep = false
		}
		if whereID != "" && r.ID != whereID {
			keep = false
		}
		if keep {
			afterWhere = append(afterWhere, r)
		}
	}

	// ── 第 2 步：RLS 策略在「结果返回给应用之前」再过滤一次 ──
	// 这是关键：即使第 1 步漏了过滤，第 2 步仍然会挡住
	if !ctx.enabled {
		return afterWhere, "RLS 未启用 → 只经过用户写的 WHERE"
	}
	if ctx.isOwner {
		// owner 绕过策略 —— 这是最容易踩的坑
		return afterWhere, "⚠️ RLS 已启用，但连接是 owner → 策略被绕过！"
	}

	var afterRLS []rlsRow
	for _, r := range afterWhere {
		if r.FamilyID == ctx.familyID {
			afterRLS = append(afterRLS, r)
		}
	}
	return afterRLS, "✅ 用户 WHERE 之后，RLS 策略又过滤了一次"
}

func main() {
	fmt.Println("=== 1. 为什么需要数据库层兜底 ===")
	fmt.Println("  d18/d19 已经证明：漏加 WHERE family_id 时，43% 的数据会泄露。")
	fmt.Println("  而这个 bug 通过下面这些手段**全都抓不住**：")
	miss := []string{"类型系统（SQL 不是强类型的 WHERE 表达式）", "编译器", "普通单元测试（测试数据只有一个家庭）", "code review（代码看起来完全正常）", "静态扫描工具（没有通用规则）"}
	for _, m := range miss {
		fmt.Printf("    ❌ %s\n", m)
	}
	fmt.Println()
	fmt.Println("  所以需要机制，而不是纪律。数据库能提供三种：")
	mech := []struct{ level, granularity, catches, misses string }{
		{"schema 隔离", "schema 级", "跨域查询（svc-finance 连不上 homeos 的表）", "同域内的行级越权"},
		{"账号权限", "表级 / 列级", "DROP TABLE、TRUNCATE、读不该读的列", "行级越权"},
		{"Row Level Security", "行级", "✅ 行级越权 —— 包括漏加 WHERE", "连接池串了租户上下文"},
	}
	for _, m := range mech {
		fmt.Printf("  %-22s %-14s\n", m.level, m.granularity)
		fmt.Printf("    能抓 : %s\n", m.catches)
		fmt.Printf("    抓不到: %s\n", m.misses)
	}

	fmt.Println()
	fmt.Println("=== 2. 第 1 层：schema 隔离 ===")
	fmt.Println("  每个域一个 schema，服务账号只被授予自己 schema 的权限：")
	fmt.Println()
	fmt.Println("    -- 初始化时执行（deploy/init/01-create-schema.sql）")
	fmt.Println("    CREATE SCHEMA finance AUTHORIZATION svc_finance;")
	fmt.Println("    CREATE SCHEMA homeos AUTHORIZATION svc_homeos;")
	fmt.Println()
	fmt.Println("    -- svc_finance 只能碰 finance，碰不到 homeos")
	fmt.Println("    GRANT USAGE  ON SCHEMA finance TO svc_finance;")
	fmt.Println("    REVOKE ALL   ON SCHEMA homeos FROM svc_finance;   -- 默认就没有，但要显式")
	fmt.Println("    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA finance TO svc_finance;")
	fmt.Println()
	fmt.Println("  效果：svc_finance 执行 SELECT * FROM homeos.household 会得到")
	fmt.Println("    ERROR: permission denied for schema homeos")
	fmt.Println("  这挡住了「finance 服务误读 homeos 数据」，但**挡不住同 schema 内的行级越权**。")

	fmt.Println()
	fmt.Println("=== 3. 第 2 层：账号权限（收窄）===")
	fmt.Println("  应用账号只需要 DML，不需要 DDL。默认新建账号是有 CREATE 权限的，要撤：")
	fmt.Println()
	fmt.Println("    -- 应用账号不该有建表/删表能力")
	fmt.Println("    ALTER ROLE svc_finance NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;")
	fmt.Println()
	fmt.Println("    ALTER DEFAULT PRIVILEGES IN SCHEMA finance")
	fmt.Println("      GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO svc_finance;")
	fmt.Println()
	fmt.Println("    ALTER DEFAULT PRIVILEGES IN SCHEMA finance")
	fmt.Println("      REVOKE TRUNCATE, REFERENCES, TRIGGER ON TABLES FROM svc_finance;")
	fmt.Println()
	fmt.Println("  撤掉的几个权限各挡什么：")
	perms := []struct{ priv, blocks string }{
		{"TRUNCATE", "一次清空整张表（DELETE 做不到，因为 DELETE 要逐行过权限）"},
		{"REFERENCES", "建外键时需要；给了它就能在别的表上加指向本表的外键"},
		{"CREATE (on schema)", "在 finance schema 里建新表 —— 意味着可以绕过迁移自己造表"},
		{"NOBYPASSRLS", "超级用户默认绕过所有 RLS。这个标志专门用来防止「图省事用超级用户连接」"},
	}
	fmt.Printf("    %-22s %s\n", "权限", "挡住的攻击")
	for _, p := range perms {
		fmt.Printf("    %-22s %s\n", p.priv, p.blocks)
	}
	fmt.Println()
	fmt.Println("  ⚠️ 顺带说一个真实的安全配置习惯：**应用绝不能用超级用户连接数据库**。")
	fmt.Println("     因为超级用户能 BYPASSRLS，等于把 RLS 全部关掉。")
	fmt.Println("     所以 NOBYPASSRLS 要显式写出来，不能靠「我们不用超级用户」的自觉。")

	fmt.Println()
	fmt.Println("=== 4. 第 3 层：Row Level Security ===")
	fmt.Println("  RLS 的核心思想：**策略在数据库内部执行，应用层无法绕过**。")
	fmt.Println("  它不是「给 SQL 加条件」，而是在查询结果返回给连接之前，")
	fmt.Println("  对每一行再检查一次策略。")
	fmt.Println()
	fmt.Println("  完整可执行的 DDL（D22 起库后直接跑）：")
	fmt.Println()
	rlsDDL := []string{
		"-- ① 给每张业务表加上租户上下文变量读取（用 current_setting）",
		"--    app.family_id 由应用在事务开始时 SET LOCAL 写入",
		"",
		"-- ② 逐表建策略。USING 决定「哪些行对当前连接可见」",
		"CREATE POLICY finance_txn_isolation ON finance.finance_transaction",
		"  FOR SELECT",
		"  USING (family_id = current_setting('app.family_id', true)::uuid);",
		"",
		"-- ③ 写操作要同时管 SELECT 和 UPDATE/DELETE 两面",
		"CREATE POLICY finance_txn_insert ON finance.finance_transaction",
		"  FOR INSERT",
		"  WITH CHECK (family_id = current_setting('app.family_id', true)::uuid);",
		"",
		"CREATE POLICY finance_txn_update ON finance.finance_transaction",
		"  FOR UPDATE",
		"  USING      (family_id = current_setting('app.family_id', true)::uuid)",
		"  WITH CHECK (family_id = current_setting('app.family_id', true)::uuid);",
		"",
		"-- ④ 打开 RLS",
		"ALTER TABLE finance.finance_transaction ENABLE ROW LEVEL SECURITY;",
		"",
		"-- ⑤ ★★★ 最关键的一行 ★★★",
		"--    默认「表的 owner 绕过所有策略」。如果连接用的就是建表的账号，",
		"--    RLS 形同虚设。FORCE 让 owner 也必须遵守策略。",
		"ALTER TABLE finance.finance_transaction FORCE ROW LEVEL SECURITY;",
	}
	for _, l := range rlsDDL {
		fmt.Println("    " + l)
	}
	fmt.Println()
	fmt.Println("  ⚠️ 第 ⑤ 条是最容易漏的。不加 FORCE 时：")
	fmt.Println("     应用用建表账号连接 → owner 绕过策略 → RLS 完全无效")
	fmt.Println("     而这恰恰是开发环境最常见的配置（用 postgres 超级用户跑）。")
	fmt.Println("     所以 D22 起库后第一件事就是验证 FORCE 有没有生效。")

	fmt.Println()
	fmt.Println("=== 5. RLS 为什么能兜住漏加 WHERE：看它在哪一步生效 ===")
	fmt.Println("  Postgres 处理一条 SELECT 的顺序：")
	fmt.Println("    ① 解析 SQL → 生成执行计划")
	fmt.Println("    ② 执行扫描（seq scan / index scan）")
	fmt.Println("    ③ ★ 对每一行检查 RLS 策略（USING），不通过的行被丢弃")
	fmt.Println("    ④ 剩下的行才返回给客户端")
	fmt.Println()
	fmt.Println("  也就是说：RLS 在「用户写的条件」**之后**、「返回给应用」**之前**。")
	fmt.Println("  所以即使应用完全忘了写 WHERE family_id，策略依然会执行。")
	fmt.Println()

	// 真跑模拟：三种情况
	rows := []rlsRow{
		{"11111111-0000-4000-8000-000000000001", famA, 1137, "超市买菜"},
		{"11111111-0000-4000-8000-000000000002", famA, 1274, "地铁通勤"},
		{"22222222-0000-4000-8000-000000000001", famB, 8888, "房租"},
		{"22222222-0000-4000-8000-000000000002", famB, 65000, "年终奖入账"},
	}
	fmt.Println("  用同一个「写错了的查询」—— 完全不带 family_id：")
	fmt.Println("    SELECT * FROM finance_transaction;   -- 忘了 WHERE family_id")
	fmt.Println()

	scenarios := []struct {
		name string
		ctx  rlsContext
		note string
	}{
		{"情况① 没有 RLS（今天之前的状态）", rlsContext{familyID: famA, enabled: false}, ""},
		{"情况② 启用了 RLS，但连接是 owner（没加 FORCE）", rlsContext{familyID: famA, enabled: true, isOwner: true}, ""},
		{"情况③ 启用了 RLS + FORCE，连接是普通账号", rlsContext{familyID: famA, enabled: true, isOwner: false}, ""},
	}
	for _, sc := range scenarios {
		got, note := selectSim(rows, sc.ctx, "", "")
		leaked := 0
		for _, r := range got {
			if r.FamilyID != famA {
				leaked++
			}
		}
		mark := "❌"
		if leaked == 0 {
			mark = "✅"
		}
		fmt.Printf("  %s\n", sc.name)
		fmt.Printf("    %s 返回 %d 条，其中 %d 条属于其他家庭\n", mark, len(got), leaked)
		for _, r := range got {
			flag := ""
			if r.FamilyID != famA {
				flag = "  ← 泄露"
			}
			fmt.Printf("      %s  %6d  %-10s%s\n", r.ID[0:8], r.Amount, r.Note, flag)
		}
		fmt.Printf("    %s\n", note)
		fmt.Println()
	}
	fmt.Println("  对比三个情况：")
	fmt.Println("    ① 泄露全部 4 条 —— 应用层纪律是唯一防线，错了就完了")
	fmt.Println("    ② 泄露全部 4 条 —— RLS 看起来开了，实际被 owner 绕过了（最危险：以为有保护）")
	fmt.Println("    ③ 泄露 0 条 —— FORCE 生效，策略真的执行了")
	fmt.Println()
	fmt.Println("  ② 是最坏的情况：**你以为有兜底，其实没有**。")
	fmt.Println("  所以验证 RLS 是否生效必须是门禁的一部分，不能靠读代码判断。")

	fmt.Println()
	fmt.Println("=== 6. RLS 的代价 ===")
	costs := []struct{ cost, detail string }{
		{"每行都要过策略", "策略是 SQL 表达式，会被求值一次。百万行的扫描 = 百万次求值。好在简单条件（等值比较）非常快"},
		{"优化器可能变差", "RLS 条件会影响 planner 的估算。有 RLS 时它会禁用某些优化（比如并行查询的部分场景）"},
		{"需要管理 session 变量", "每个连接池的连接都要 SET LOCAL，而且必须 SET 在事务里（连接会归还池）"},
		{"current_setting 的坑", "如果没设置过 app.family_id，current_setting('app.family_id') 会**直接报错**。用第二个参数 true 可以返回 NULL，但那样策略会一条都过滤不出来"},
		{"连接池串租户", "SET 是 session 级的。如果用 SET（不是 SET LOCAL）而连接被归还池，下一个租户可能继承上一个的上下文 —— 这就是最隐蔽的漏洞"},
	}
	for i, c := range costs {
		fmt.Printf("  %d. %s\n", i+1, c.cost)
		fmt.Printf("     %s\n", c.detail)
	}
	fmt.Println()
	fmt.Println("  第 5 条尤其重要 —— 它是「RLS 反而制造了新漏洞」的典型案例。")
	fmt.Println("  正确做法：")
	fmt.Println("    · 用 SET LOCAL（只在当前事务内有效，事务结束自动清除）")
	fmt.Println("    · 每个请求一个事务，SET LOCAL 放在事务第一行")
	fmt.Println("    · 绝不用连接级的 SET")

	fmt.Println()
	fmt.Println("=== 7. Go 侧怎么用（真实 SQL，D22 直接跑）===")
	dbg := dryDB()
	fmt.Println("  每个请求的处理流程（在同一个事务里）：")
	fmt.Println()
	fmt.Printf("    ① BEGIN\n       %s\n", flat(dbg.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Exec("BEGIN")
	})))
	fmt.Printf("    ② SET LOCAL\n       %s\n", flat(dbg.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Exec("SET LOCAL app.family_id = ?", famA)
	})))
	fmt.Printf("    ③ 查询（**不需要**自己写 WHERE family_id，RLS 会兜住）\n       %s\n",
		flat(dbg.Session(&gorm.Session{DryRun: true}).Where("amount > ?", 1000).Limit(20).
			Find(&[]Txn{}).Statement.SQL.String()))
	fmt.Printf("    ④ COMMIT\n       %s\n", flat(dbg.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Exec("COMMIT")
	})))
	fmt.Println()
	fmt.Println("  Go 代码：")
	fmt.Println("    err := db.Transaction(func(tx *gorm.DB) error {")
	fmt.Println("      // 必须用 SET LOCAL，且必须在事务内")
	fmt.Println("      if err := tx.Exec(`SET LOCAL app.family_id = ?`, familyID).Error; err != nil {")
	fmt.Println("        return err")
	fmt.Println("      }")
	fmt.Println("      var rows []Txn")
	fmt.Println("      // 注意：这里**不需要** Where(family_id)，RLS 已经保证了")
	fmt.Println("      if err := tx.Where(\"amount > ?\", 1000).Limit(20).Find(&rows).Error; err != nil {")
	fmt.Println("        return err")
	fmt.Println("      }")
	fmt.Println("      return nil")
	fmt.Println("    })")
	fmt.Println()
	fmt.Println("  ⚠️ 两条纪律：")
	fmt.Println("    ① SET LOCAL 必须在事务里。用 SET（session 级）在连接池下会串租户。")
	fmt.Println("    ② RLS 开启后，应用层**仍然应该**写 WHERE family_id。")
	fmt.Println("       理由不是「RLS 不够用」，而是：")
	fmt.Println("         - 显式条件能走 d17 设计的那个复合索引")
	fmt.Println("         - 不依赖数据库配置（测试用 SQLite/内存时没有 RLS）")
	fmt.Println("         - 代码意图清晰，review 时能看出来")
	fmt.Println("       RLS 是**最后一道防线**，不是唯一防线。")

	fmt.Println()
	fmt.Println("=== 8. 怎么验证 RLS 真的生效（D22 的必做项）===")
	fmt.Println("  脚本必须以**非 owner 账号**运行，否则测的是情况②：")
	verify := []string{
		"-- 1. 确认 RLS 已开启（不是 owner 的情况下）",
		"SELECT relname, relrowsecurity, relforcerowsecurity",
		"  FROM pg_class WHERE relname = 'finance_transaction';",
		"--   期望：relrowsecurity = t，relforcerowsecurity = t",
		"",
		"-- 2. 故意用错的租户上下文查一张别的表",
		"BEGIN;",
		"  SET LOCAL app.family_id = 'aaaaaaaa-0000-4000-8000-000000000001';",
		"  SELECT count(*) FROM finance.finance_category",
		"   WHERE family_id = 'bbbbbbbb-0000-4000-8000-000000000002';  -- 别家的",
		"--   期望：count = 0（RLS 把它们全过滤了），而不是别家的数量",
		"ROLLBACK;",
		"",
		"-- 3. 确认应用账号不是 owner",
		"SELECT current_user, usesuper FROM pg_user WHERE usename = current_user;",
		"--   期望：usesuper = f",
		"SELECT tableowner FROM pg_tables WHERE tablename = 'finance_transaction';",
		"--   期望：tableowner 不是 svc_finance",
	}
	for _, l := range verify {
		fmt.Println("    " + l)
	}
	fmt.Println()
	fmt.Println("  第 2 条是最关键的验收测试：**用错租户查别家的数据，必须是 0 行**。")
	fmt.Println("  如果这里返回了别家的数据，说明 RLS 没生效（或者连接是 owner）。")
	fmt.Println("  这条应该进 CI，每次迁移后跑。")

	fmt.Println()
	fmt.Println("=== 9. 与 JS/前端对比 ===")
	fmt.Println("  ① 这是纯粹的后端/数据库话题，前端完全无关。")
	fmt.Println("     RLS 是数据库特性，Node 也一样能用 —— 只要它用 pg 连同一个库。")
	fmt.Println("  ② 但 Node 生态有个问题：Prisma/TypeORM 不会帮你 SET session 变量。")
	fmt.Println("     你得用 `$executeRaw` 手动发 SET LOCAL，而且很容易忘记放进事务。")
	fmt.Println("     Go 的 GORM 也一样（要 tx.Exec），但 Go 的事务是显式的闭包，")
	fmt.Println("     把 SET LOCAL 和查询写在同一个闭包里，视觉上很难漏。")
	fmt.Println("  ③ 有个替代方案是「每租户一个数据库连接串」（多租户分库），")
	fmt.Println("     Node 生态用 Prisma 多 schema 更容易做这种隔离。")
	fmt.Println("     但那是另一种架构（隔离更强、成本更高），本项目选择共享库 + RLS。")
	fmt.Println("     共享库的好处：跨租户统计（如果需要）、成本低、运维简单。")

	fmt.Println()
	fmt.Println("=== 10. 三层兜底的分工（记住这张表）===")
	fmt.Println()
	fmt.Println("    ┌─────────────────────┬──────────────┬──────────────┬────────────┐")
	fmt.Println("    │ 机制                │ 防什么       │ 防不住什么   │ 性能代价   │")
	fmt.Println("    ├─────────────────────┼──────────────┼──────────────┼────────────┤")
	fmt.Println("    │ 应用层 WHERE        │ 日常查询     │ 人为遗漏     │ 无         │")
	fmt.Println("    │ schema 隔离         │ 跨域访问     │ 同域越权     │ 无         │")
	fmt.Println("    │ 账号权限            │ DDL/DML 越界 │ 行级越权     │ 无         │")
	fmt.Println("    │ RLS                 │ 行级越权     │ 连接池串租户 │ 轻微       │")
	fmt.Println("    ├─────────────────────┼──────────────┼──────────────┼────────────┤")
	fmt.Println("    │ 业务代码审查        │ 逻辑错误     │ 疏忽         │ 无         │")
	fmt.Println("    │ 越权测试            │ 回归         │ 没写的路径   │ 无         │")
	fmt.Println("    └─────────────────────┴──────────────┴──────────────┴────────────┘")
	fmt.Println()
	fmt.Println("  关键认识：**每一层都有它防不住的东西**，所以要叠起来。")
	fmt.Println("  只靠应用层 → 一次疏忽就泄露")
	fmt.Println("  只靠 RLS   → 连接池配置错就全泄露，且更难发现")
	fmt.Println("  两者都有   → 一层失效时另一层还在")

	fmt.Println()
	fmt.Println("=== S3 d20 到此结束 ===")
	fmt.Println("明天建 11 张表：把这两周讲的所有约束真正落到 DDL 上 ——")
	fmt.Println("family_id、version、软删、部分唯一索引、复合索引，一个都不能少。")
}

func flat(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

build.add:
// =====================================================================
// W12 d20：数据库层兜底 —— schema / 账号权限 / Row Level Security。
//
// 前两天讲了：靠应用层纪律（每条查询带 family_id）会漏。
// 今天讲「即使代码写错也不泄露」的三层数据库机制：
//
//   第 1 层：schema 隔离      —— 每域一个 schema，服务账号只 GRANT 自己那个 schema
//   第 2 层：账号权限        —— 撤掉不需要的权限（比如禁止 TRUNCATE/DDL）
//   第 3 层：Row Level Security —— 行级策略，漏加 WHERE 也过滤得掉
//
// RLS 是本项目唯一「即使代码写错也不泄露」的机制，所以今天重点讲它。
//
// ⚠️ 诚实声明：本机没有 Postgres，所以 RLS 的**实际拦截效果**没有在这里跑过。
// 本文件做的是：
//   ① 给出完整可执行的 DDL（D22 起库后直接跑）
//   ② 用 Go 模拟 RLS 策略的执行时机和效果（逻辑等价，机制不同）
//   ③ 给出 EXPLAIN 和验证步骤
// =====================================================================

package main

import (
	"fmt"
	"strings"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"
const famB = "bbbbbbbb-0000-4000-8000-000000000002"

func shortID(s string) string {
	if len(s) >= 8 {
		return s[:8]
	}
	return s
}

type Txn struct {
	ID        string         `gorm:"primaryKey;type:uuid"`
	FamilyID  string         `gorm:"column:family_id;type:uuid;not null;index"`
	Amount    int64          `gorm:"column:amount;not null"`
	Note      string         `gorm:"column:note;type:varchar(200)"`
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

func (Txn) TableName() string { return "finance_transaction" }

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true,
		Logger: logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

// =====================================================================
// 模拟 RLS：一个会拦截「漏加 WHERE」查询的过滤器

// =====================================================================

// rlsContext 模拟「当前连接的租户上下文」。
// 真实 Postgres 里它存在 session 变量 app.family_id 里。
type rlsContext struct {
	// familyID 就是 SET LOCAL app.family_id 的值
	familyID string
	// enabled 表示 RLS 策略是否生效
	enabled bool
	// isOwner 表示连接用的是表的 owner 账号（owner 默认绕过 RLS！）
	isOwner bool
}

type rlsRow struct {
	ID       string
	FamilyID string
	Amount   int64
	Note     string
}

// selectSim 模拟一次 SELECT，并说明 RLS 在哪一步生效
func selectSim(rows []rlsRow, ctx rlsContext, whereFamilyID, whereID string) (returned []rlsRow, note string) {
	// ── 第 1 步：执行用户写的 WHERE 子句 ──
	var afterWhere []rlsRow
	for _, r := range rows {
		keep := true
		if whereFamilyID != "" && r.FamilyID != whereFamilyID {
			keep = false
		}
		if whereID != "" && r.ID != whereID {
			keep = false
		}
		if keep {
			afterWhere = append(afterWhere, r)
		}
	}

	// ── 第 2 步：RLS 策略在「结果返回给应用之前」再过滤一次 ──
	// 这是关键：即使第 1 步漏了过滤，第 2 步仍然会挡住
	if !ctx.enabled {
		return afterWhere, "RLS 未启用 → 只经过用户写的 WHERE"
	}
	if ctx.isOwner {
		// owner 绕过策略 —— 这是最容易踩的坑
		return afterWhere, "⚠️ RLS 已启用，但连接是 owner → 策略被绕过！"
	}

	var afterRLS []rlsRow
	for _, r := range afterWhere {
		if r.FamilyID == ctx.familyID {
			afterRLS = append(afterRLS, r)
		}
	}
	return afterRLS, "✅ 用户 WHERE 之后，RLS 策略又过滤了一次"
}

func main() {
	fmt.Println("=== 1. 为什么需要数据库层兜底 ===")
	fmt.Println("  d18/d19 已经证明：漏加 WHERE family_id 时，43% 的数据会泄露。")
	fmt.Println("  而这个 bug 通过下面这些手段**全都抓不住**：")
	miss := []string{"类型系统（SQL 不是强类型的 WHERE 表达式）", "编译器", "普通单元测试（测试数据只有一个家庭）", "code review（代码看起来完全正常）", "静态扫描工具（没有通用规则）"}
	for _, m := range miss {
		fmt.Printf("    ❌ %s\n", m)
	}
	fmt.Println()
	fmt.Println("  所以需要机制，而不是纪律。数据库能提供三种：")
	mech := []struct{ level, granularity, catches, misses string }{
		{"schema 隔离", "schema 级", "跨域查询（svc-finance 连不上 homeos 的表）", "同域内的行级越权"},
		{"账号权限", "表级 / 列级", "DROP TABLE、TRUNCATE、读不该读的列", "行级越权"},
		{"Row Level Security", "行级", "✅ 行级越权 —— 包括漏加 WHERE", "连接池串了租户上下文"},
	}
	for _, m := range mech {
		fmt.Printf("  %-22s %-14s\n", m.level, m.granularity)
		fmt.Printf("    能抓 : %s\n", m.catches)
		fmt.Printf("    抓不到: %s\n", m.misses)
	}

	fmt.Println()

