// =====================================================================
// W12 d21：建 11 张表 —— 把前 20 天的约束真正落到 DDL 上。
//
// 今天是整个 S3 的「集大成」：前面讲的每一条纪律，在这里变成一行 DDL。
//
//   family_id              → 多租户（d18/d19/d20）
//   version                → 乐观锁（d23 会详细讲）
//   deleted_at             → 软删（d12）
//   部分唯一索引            → 软删 × 唯一约束（d12）
//   复合索引 (family_id, 排序键) → 游标分页 + 租户过滤（d15/d17）
//   money 用整数分          → 精度（d5）
//   TIMESTAMPTZ            → 时区（d4）
//
// 本文件做两件事：
//   ① 给出完整可执行的 DDL（D22 起库后直接跑）
//   ② 写一个**真能跑的 DDL 检查器**，机械校验 7 项规则
//
// ⚠️ 本机没有 Postgres，所以 DDL 没有在这里执行过。
//    但第 ② 部分的检查器是真的在跑 —— 它解析下面的 DDL 文本，
//    按规则逐项检查并打印 ✅/❌。这是 tech-plan §10.2 的「表结构门禁」。
// =====================================================================

package main

import (
	"fmt"
	"regexp"
	"strings"
)

// =====================================================================
// ① 完整可执行的 DDL
//
// 分三个文件：
//   homeos_0001_init.up.sql        —— 用户、家庭、成员、邀请、通知、refresh_token
//   finance_0001_init.up.sql       —— 账户、分类、流水、预算、周期记账
//   （10 张业务表 + 第 11 张 schema_migrations 由 golang-migrate 维护）
// =====================================================================

const ddlHomeos = `
-- ============================================================
-- migrations/homeos/homeos_0001_init.up.sql
-- ============================================================

-- ---------- 1. 用户 ----------
CREATE TABLE homeos.homeos_user (
  id            UUID PRIMARY KEY,                    -- 应用层生成 uuid v4
  email         VARCHAR(254) NOT NULL,
  phone         VARCHAR(20),
  password_hash TEXT NOT NULL,                       -- argon2id，绝不存明文
  nickname      VARCHAR(32) NOT NULL,
  avatar_url    VARCHAR(512),
  status        VARCHAR(16) NOT NULL DEFAULT 'active',
  -- 用户表本身没有 family_id：它是「租户的主人」，不是租户的数据
  version       INTEGER NOT NULL DEFAULT 1,          -- 乐观锁
  deleted_at    TIMESTAMPTZ,                          -- 软删（注销账号）
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT ck_user_status CHECK (status IN ('active','disabled','deleted'))
);

-- 邮箱大小写不敏感，所以用 lower(email) 建唯一索引
CREATE UNIQUE INDEX uniq_user_email ON homeos.homeos_user (lower(email))
  WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uniq_user_phone ON homeos.homeos_user (phone)
  WHERE deleted_at IS NULL AND phone IS NOT NULL;
-- RLS 不适用于用户表（它没有 family_id），但要索引 status
CREATE INDEX idx_user_status ON homeos.homeos_user (status);

-- ---------- 2. 家庭 ----------
CREATE TABLE homeos.family (
  id            UUID PRIMARY KEY,
  name          VARCHAR(64) NOT NULL,
  owner_id      UUID NOT NULL REFERENCES homeos.homeos_user(id),
  currency      CHAR(3) NOT NULL DEFAULT 'CNY',       -- ISO 4217
  timezone      VARCHAR(64) NOT NULL DEFAULT 'Asia/Shanghai',
  version       INTEGER NOT NULL DEFAULT 1,
  deleted_at    TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ---------- 3. 家庭成员 ----------
CREATE TABLE homeos.family_member (
  id            UUID PRIMARY KEY,
  family_id     UUID NOT NULL REFERENCES homeos.family(id),
  user_id       UUID NOT NULL REFERENCES homeos.homeos_user(id),
  role          VARCHAR(16) NOT NULL DEFAULT 'member',
  nickname      VARCHAR(32),
  joined_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  version       INTEGER NOT NULL DEFAULT 1,
  deleted_at    TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT ck_member_role CHECK (role IN ('owner','admin','member','viewer'))
);

-- 一个人在一个家庭里只能有一个角色；软删后可以重新加入
CREATE UNIQUE INDEX uniq_member_family_user ON homeos.family_member (family_id, user_id)
  WHERE deleted_at IS NULL;
-- 反向索引：查「我加入了哪些家庭」
CREATE INDEX idx_member_user ON homeos.family_member (user_id)
  WHERE deleted_at IS NULL;

-- ---------- 4. 邀请 ----------
CREATE TABLE homeos.invitation (
  id            UUID PRIMARY KEY,
  family_id     UUID NOT NULL REFERENCES homeos.family(id),
  inviter_id    UUID NOT NULL REFERENCES homeos.homeos_user(id),
  invitee_email VARCHAR(254) NOT NULL,
  token_hash    TEXT NOT NULL,                       -- 邀请码的哈希，不存明文
  role          VARCHAR(16) NOT NULL DEFAULT 'member',
  expires_at    TIMESTAMPTZ NOT NULL,
  accepted_at   TIMESTAMPTZ,
  status        VARCHAR(16) NOT NULL DEFAULT 'pending',
  version       INTEGER NOT NULL DEFAULT 1,
  deleted_at    TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT ck_invitation_status CHECK (status IN ('pending','accepted','expired','revoked'))
);

CREATE UNIQUE INDEX uniq_invitation_token ON homeos.invitation (token_hash);
-- 同一个邮箱对同一个家庭只能有一条有效邀请
CREATE UNIQUE INDEX uniq_invitation_family_email ON homeos.invitation (family_id, invitee_email)
  WHERE deleted_at IS NULL AND status = 'pending';
-- 清理过期邀请用
CREATE INDEX idx_invitation_expires ON homeos.invitation (expires_at);

-- ---------- 5. 通知 ----------
CREATE TABLE homeos.notification (
  id            UUID PRIMARY KEY,
  family_id     UUID NOT NULL REFERENCES homeos.family(id),
  user_id       UUID NOT NULL REFERENCES homeos.homeos_user(id),
  kind          VARCHAR(32) NOT NULL,
  title         VARCHAR(128) NOT NULL,
  body          VARCHAR(512),
  payload       JSONB NOT NULL DEFAULT '{}'::jsonb,
  read_at       TIMESTAMPTZ,
  version       INTEGER NOT NULL DEFAULT 1,
  deleted_at    TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 通知列表：按家庭 + 未读 + 最新
CREATE INDEX idx_notification_user_unread ON homeos.notification (family_id, user_id, created_at DESC)
  WHERE deleted_at IS NULL AND read_at IS NULL;

-- ---------- 6. refresh_token ----------
CREATE TABLE homeos.refresh_token (
  id            UUID PRIMARY KEY,
  family_id     UUID NOT NULL REFERENCES homeos.family(id),
  user_id       UUID NOT NULL REFERENCES homeos.homeos_user(id),
  token_hash    TEXT NOT NULL,                       -- 只存哈希
  user_agent    VARCHAR(256),
  ip            INET,
  expires_at    TIMESTAMPTZ NOT NULL,
  revoked_at    TIMESTAMPTZ,
  rotated_from  UUID REFERENCES homeos.refresh_token(id),
  version       INTEGER NOT NULL DEFAULT 1,
  deleted_at    TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- refresh_token 也带 family_id 且 NOT NULL：能签发 refresh token 就说明已经登录并选定了家庭
CREATE UNIQUE INDEX uniq_refresh_token_hash ON homeos.refresh_token (token_hash);
CREATE INDEX idx_refresh_user ON homeos.refresh_token (user_id) WHERE revoked_at IS NULL;
CREATE INDEX idx_refresh_expires ON homeos.refresh_token (expires_at);

-- ---------- 7. schema_migrations（golang-migrate 自动维护）----------
-- tech-plan §10.1 第 8 条：两个服务的迁移序列分开
-- CREATE TABLE IF NOT EXISTS public.schema_migrations (
--   version BIGINT NOT NULL PRIMARY KEY,
--   dirty BOOLEAN NOT NULL
-- );
`

const ddlFinance = `
-- ============================================================
-- migrations/finance/finance_0001_init.up.sql
-- ============================================================

-- ---------- 7. 账户 ----------
CREATE TABLE finance.finance_account (
  id             UUID PRIMARY KEY,
  family_id      UUID NOT NULL REFERENCES homeos.family(id),
  name           VARCHAR(64) NOT NULL,
  account_type   VARCHAR(16) NOT NULL,               -- cash/bank/alipay/wechat/credit
  currency       CHAR(3) NOT NULL DEFAULT 'CNY',
  -- ★ 金额用整数「分」存储，绝不用 NUMERIC/FLOAT/INTEGER 元
  --   d5 讲过：0.1+0.2 != 0.3，浮点数记账必然对不上账
  balance_cents  BIGINT NOT NULL DEFAULT 0,
  initial_cents  BIGINT NOT NULL DEFAULT 0,
  credit_limit_cents BIGINT NOT NULL DEFAULT 0,
  is_archived    BOOLEAN NOT NULL DEFAULT false,
  sort_order     INTEGER NOT NULL DEFAULT 0,
  version        INTEGER NOT NULL DEFAULT 1,          -- 乐观锁（d23）
  deleted_at     TIMESTAMPTZ,                          -- 软删（d12）
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT ck_account_type CHECK (account_type IN ('cash','bank','alipay','wechat','credit')),
  CONSTRAINT ck_account_balance CHECK (balance_cents >= 0 OR account_type = 'credit')
);

-- 部分唯一索引：软删后可以重建同名账户（d12 的教训）
CREATE UNIQUE INDEX uniq_account_family_name ON finance.finance_account (family_id, lower(name))
  WHERE deleted_at IS NULL;
-- 游标分页主索引：等值列在前，范围列在后（d17）
CREATE INDEX idx_account_family_created ON finance.finance_account (family_id, created_at DESC, id DESC)
  WHERE deleted_at IS NULL;

-- ---------- 8. 分类 ----------
CREATE TABLE finance.finance_category (
  id            UUID PRIMARY KEY,
  family_id     UUID NOT NULL REFERENCES homeos.family(id),
  parent_id     UUID REFERENCES finance.finance_category(id),  -- 自引用：二级分类
  name          VARCHAR(32) NOT NULL,
  type          VARCHAR(16) NOT NULL,                 -- expense/income
  icon          VARCHAR(32) NOT NULL DEFAULT 'wallet',
  color         VARCHAR(9),
  sort_order    INTEGER NOT NULL DEFAULT 0,
  is_active     BOOLEAN NOT NULL DEFAULT true,
  version       INTEGER NOT NULL DEFAULT 1,
  deleted_at    TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT ck_category_type CHECK (type IN ('expense','income')),
  CONSTRAINT ck_category_color CHECK (color IS NULL OR color ~ '^#[0-9A-Fa-f]{6}$')
);

-- d12 的核心修复：部分唯一索引，软删的行不占键
CREATE UNIQUE INDEX uniq_category_family_name ON finance.finance_category (family_id, parent_id, name)
  WHERE deleted_at IS NULL;
CREATE INDEX idx_category_family_sort ON finance.finance_category (family_id, sort_order, id)
  WHERE deleted_at IS NULL;

-- ---------- 9. 流水 ----------
CREATE TABLE finance.finance_transaction (
  id            UUID PRIMARY KEY,
  family_id     UUID NOT NULL REFERENCES homeos.family(id),
  account_id    UUID NOT NULL REFERENCES finance.finance_account(id),
  category_id   UUID REFERENCES finance.finance_category(id),
  type          VARCHAR(16) NOT NULL,                 -- expense/income/transfer
  amount_cents  BIGINT NOT NULL,                      -- 正整数，方向由 type 决定
  occurred_on   DATE NOT NULL,                        -- 用户记账的日期（可修改）
  occurred_at   TIMESTAMPTZ NOT NULL,                 -- 精确时间点，**不可变**，排序用
  note          VARCHAR(200),
  recurring_id  UUID,                                  -- 周期记账生成的记录
  version       INTEGER NOT NULL DEFAULT 1,           -- 乐观锁
  deleted_at    TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT ck_txn_type CHECK (type IN ('expense','income','transfer')),
  CONSTRAINT ck_txn_amount CHECK (amount_cents > 0)
);

-- ★ 主查询索引：游标分页 + 租户过滤（d15/d17 的核心）
--   family_id 是等值列，occurred_at 是范围列，id 是 tiebreaker
CREATE INDEX idx_txn_family_occurred ON finance.finance_transaction
  (family_id, occurred_at DESC, id DESC)
  WHERE deleted_at IS NULL;
-- 按日期查某一笔（对账用）
CREATE UNIQUE INDEX uniq_txn_account_occurred ON finance.finance_transaction
  (account_id, occurred_at, note)
  WHERE deleted_at IS NULL;
-- 统计用
CREATE INDEX idx_txn_family_category ON finance.finance_transaction (family_id, category_id, occurred_on)
  WHERE deleted_at IS NULL;

-- ---------- 10. 预算 ----------
CREATE TABLE finance.finance_budget (
  id             UUID PRIMARY KEY,
  family_id      UUID NOT NULL REFERENCES homeos.family(id),
  category_id    UUID REFERENCES finance.finance_category(id),
  period         VARCHAR(7) NOT NULL,                 -- 'YYYY-MM'
  amount_cents   BIGINT NOT NULL,                     -- 预算额度（分）
  alert_ratio    SMALLINT NOT NULL DEFAULT 80,        -- 用到 80% 时提醒
  is_active      BOOLEAN NOT NULL DEFAULT true,
  version        INTEGER NOT NULL DEFAULT 1,
  deleted_at     TIMESTAMPTZ,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT ck_budget_period CHECK (period ~ '^[0-9]{4}-[0-9]{2}$'),
  CONSTRAINT ck_budget_amount CHECK (amount_cents > 0),
  CONSTRAINT ck_budget_alert CHECK (alert_ratio BETWEEN 1 AND 100)
);

-- 一个家庭在一个月份里，同一分类只能有一个预算
CREATE UNIQUE INDEX uniq_budget_family_period_category ON finance.finance_budget
  (family_id, COALESCE(category_id, '00000000-0000-0000-0000-000000000000'::uuid), period)
  WHERE deleted_at IS NULL;

-- ---------- 11. 周期记账 ----------
CREATE TABLE finance.finance_recurring (
  id             UUID PRIMARY KEY,
  family_id      UUID NOT NULL REFERENCES homeos.family(id),
  account_id     UUID NOT NULL REFERENCES finance.finance_account(id),
  category_id    UUID REFERENCES finance.finance_category(id),
  name           VARCHAR(64) NOT NULL,
  type           VARCHAR(16) NOT NULL,
  amount_cents   BIGINT NOT NULL,
  frequency      VARCHAR(16) NOT NULL,                -- daily/weekly/monthly/yearly
  interval_days  INTEGER NOT NULL DEFAULT 1,
  next_run_on    DATE NOT NULL,
  end_on         DATE,
  is_active      BOOLEAN NOT NULL DEFAULT true,
  version        INTEGER NOT NULL DEFAULT 1,
  deleted_at     TIMESTAMPTZ,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT ck_recurring_type CHECK (type IN ('expense','income')),
  CONSTRAINT ck_recurring_freq CHECK (frequency IN ('daily','weekly','monthly','yearly')),
  CONSTRAINT ck_recurring_interval CHECK (interval_days > 0),
  CONSTRAINT ck_recurring_end CHECK (end_on IS NULL OR end_on >= next_run_on)
);

-- 定时任务扫「今天该跑哪些」：这是热路径
CREATE INDEX idx_recurring_due ON finance.finance_recurring (next_run_on)
  WHERE deleted_at IS NULL AND is_active = true;
CREATE INDEX idx_recurring_family ON finance.finance_recurring (family_id, next_run_on DESC, id DESC)
  WHERE deleted_at IS NULL;

-- ---------- RLS：多租户最后一道防线（d20）----------
`

// rlsDDL 是追加在 finance 迁移里的 RLS 语句
const rlsDDL = `
-- 对所有 5 张 finance 业务表逐个启用 RLS。
-- FORCE 是关键：否则 owner 绕过策略，RLS 形同虚设（d20 的情况②）。
DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'finance_account','finance_category','finance_transaction',
    'finance_budget','finance_recurring'
  ] LOOP
    EXECUTE format('ALTER TABLE finance.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE finance.%I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON finance.%I FOR ALL'
      ' USING (family_id = current_setting(''app.family_id'', true)::uuid)'
      ' WITH CHECK (family_id = current_setting(''app.family_id'', true)::uuid)', t, t);
  END LOOP;
END $$;
`

// =====================================================================
// ② DDL 检查器 —— 真跑，不是伪代码
// =====================================================================

var reComment = regexp.MustCompile(`(?m)--[^\n]*`)

var (
	reCreateTable = regexp.MustCompile(`(?is)CREATE TABLE (\w+)\.(\w+)\s*\((.*?)\n\);`)
	reCreateIndex = regexp.MustCompile(`(?i)CREATE (UNIQUE )?INDEX (\w+)\s+ON\s+(\w+)\.(\w+)\s*\(([^)]*)\)`)
	reRefTable    = regexp.MustCompile(`REFERENCES\s+(\w+)\.(\w+)`)
)

type tableInfo struct {
	schema  string
	name    string
	body    string
	indexes []indexInfo
}

type indexInfo struct {
	name    string
	unique  bool
	table   string
	columns []string
	where   string // 部分索引的 WHERE 子句
}

// parse 从 DDL 文本里解析出表和索引
func parse(ddl string) map[string]*tableInfo {
	tables := map[string]*tableInfo{}

	for _, m := range reCreateTable.FindAllStringSubmatch(ddl, -1) {
		schema, name, body := m[1], m[2], m[3]
		tables[schema+"."+name] = &tableInfo{schema: schema, name: name, body: body}
	}

	// 部分索引的 WHERE 要单独抓（因为正则的 () 不能嵌套）
	for _, m := range reCreateIndex.FindAllStringSubmatch(ddl, -1) {
		unique := strings.TrimSpace(m[1]) == "UNIQUE"
		idxName, tableSchema, tableName, cols := m[2], m[3], m[4], m[5]
		key := tableSchema + "." + tableName
		t, ok := tables[key]
		if !ok {
			continue
		}
		var colList []string
		for _, c := range strings.Split(cols, ",") {
			c = strings.TrimSpace(c)
			if c != "" {
				colList = append(colList, c)
			}
		}
		idx := indexInfo{name: idxName, unique: unique, table: key, columns: colList}
		// 找这个索引后面的 WHERE
		if pos := strings.Index(ddl, "CREATE"); pos >= 0 {
			_ = pos
		}
		t.indexes = append(t.indexes, idx)
	}

	// 补 WHERE 子句：从 "CREATE ... INDEX name ... ;" 整句里找 WHERE
	for _, line := range splitStatements(ddl) {
		if !strings.Contains(strings.ToUpper(line), "CREATE ") || !strings.Contains(strings.ToUpper(line), "INDEX") {
			continue
		}
		m := reCreateIndex.FindStringSubmatch(line)
		if m == nil {
			continue
		}
		idxName, key := m[2], m[3]+"."+m[4]
		if w := extractWhere(line); w != "" {
			if t, ok := tables[key]; ok {
				for i := range t.indexes {
					if t.indexes[i].name == idxName {
						t.indexes[i].where = w
					}
				}
			}
		}
	}

	return tables
}

func splitStatements(ddl string) []string {
	var out []string
	var cur strings.Builder
	for _, r := range ddl {
		if r == ';' {
			out = append(out, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteRune(r)
	}
	if strings.TrimSpace(cur.String()) != "" {
		out = append(out, cur.String())
	}
	return out
}

// extractWhere 取一条语句里 INDEX 之后的 WHERE 子句
func extractWhere(stmt string) string {
	upper := strings.ToUpper(stmt)
	// 找 "INDEX" 后面第一个 WHERE
	idx := strings.Index(upper, "INDEX")
	if idx < 0 {
		return ""
	}
	rest := upper[idx:]
	wi := strings.Index(rest, " WHERE ")
	if wi < 0 {
		return ""
	}
	return strings.TrimSpace(stmt[idx+wi+7:])
}

// ---- 7 项检查 ----

type checkResult struct {
	name   string
	pass   bool
	detail string
}

// hasColumn 按「顶层逗号切分」判断列是否存在。
// 不能用 ^\s*col\s 的行首匹配：真实迁移里一行可能有多个列定义
// （d24 的 DDL 就是紧凑写法），行首匹配会漏掉大部分列。
func hasColumn(body, col string) bool {
	for _, frag := range splitCols(body) {
		f := strings.TrimSpace(frag)
		if f == col || strings.HasPrefix(f, col+" ") {
			return true
		}
	}
	return false
}

// splitCols 按顶层逗号切分建表语句的列（忽略括号内的逗号）。
// 先剥掉 -- 行注释，否则「-- 乐观锁（d23）」会把后面的 deleted_at 列粘在一起。
func splitCols(body string) []string {
	body = reComment.ReplaceAllString(body, "")
	var out []string
	depth, cur := 0, strings.Builder{}
	for _, r := range body {
		switch r {
		case '(':
			depth++
			cur.WriteRune(r)
		case ')':
			depth--
			cur.WriteRune(r)
		case ',':
			if depth == 0 {
				out, cur = append(out, cur.String()), strings.Builder{}
			} else {
				cur.WriteRune(r)
			}
		default:
			cur.WriteRune(r)
		}
	}
	if strings.TrimSpace(cur.String()) != "" {
		out = append(out, cur.String())
	}
	return out
}

func columnDecl(body, col string) string {
	for _, line := range strings.Split(body, "\n") {
		l := strings.TrimSpace(line)
		if !hasColumn(l, col) {
			continue
		}
		fields := strings.Fields(l)
		if len(fields) == 0 {
			continue
		}
		return l
	}
	return ""
}

