// =====================================================================
// W12 d21：建 11 张表 —— 把前 20 天的约束真正落到 DDL 上。
//
// 今天是整个 S3 的「集大成」：前面讲的每一条纪律，在这里变成一行 DDL。
//
//   family_id              → 多租户（d18/d19/d20）
//   version                → 乐观锁（d23 会详细讲）
//   deleted_at             → 软删（d12）
//   部分唯一索引            → 软删 × 唯一约束（d12）
//   复合索引 (family_id, 排序键) → 游标分页 + 租户过滤（d15/d17）
//   money 用整数分          → 精度（d5）
//   TIMESTAMPTZ            → 时区（d4）
//
// 本文件做两件事：
//   ① 给出完整可执行的 DDL（D22 起库后直接跑）
//   ② 写一个**真能跑的 DDL 检查器**，机械校验 7 项规则
//
// ⚠️ 本机没有 Postgres，所以 DDL 没有在这里执行过。
//    但第 ② 部分的检查器是真的在跑 —— 它解析下面的 DDL 文本，
//    按规则逐项检查并打印 ✅/❌。这是 tech-plan §10.2 的「表结构门禁」。
// =====================================================================

package main

import (
	"fmt"
	"regexp"
	"strings"
)

// =====================================================================
// ① 完整可执行的 DDL
//
// 分三个文件：
//   homeos_0001_init.up.sql        —— 用户、家庭、成员、邀请、通知、refresh_token
//   finance_0001_init.up.sql       —— 账户、分类、流水、预算、周期记账
//   （10 张业务表 + 第 11 张 schema_migrations 由 golang-migrate 维护）

// =====================================================================

var reComment = regexp.MustCompile(`(?m)--[^\n]*`)

var (
	reCreateTable = regexp.MustCompile(`(?is)CREATE TABLE (\w+)\.(\w+)\s*\((.*?)\n\);`)
	reCreateIndex = regexp.MustCompile(`(?i)CREATE (UNIQUE )?INDEX (\w+)\s+ON\s+(\w+)\.(\w+)\s*\(([^)]*)\)`)
	reRefTable    = regexp.MustCompile(`REFERENCES\s+(\w+)\.(\w+)`)
)

type tableInfo struct {
	schema  string
	name    string
	body    string
	indexes []indexInfo
}

type indexInfo struct {
	name    string
	unique  bool
	table   string
	columns []string
	where   string // 部分索引的 WHERE 子句
}

// parse 从 DDL 文本里解析出表和索引
func parse(ddl string) map[string]*tableInfo {
	tables := map[string]*tableInfo{}

	for _, m := range reCreateTable.FindAllStringSubmatch(ddl, -1) {
		schema, name, body := m[1], m[2], m[3]
		tables[schema+"."+name] = &tableInfo{schema: schema, name: name, body: body}
	}

	// 部分索引的 WHERE 要单独抓（因为正则的 () 不能嵌套）
	for _, m := range reCreateIndex.FindAllStringSubmatch(ddl, -1) {
		unique := strings.TrimSpace(m[1]) == "UNIQUE"
		idxName, tableSchema, tableName, cols := m[2], m[3], m[4], m[5]
		key := tableSchema + "." + tableName
		t, ok := tables[key]
		if !ok {
			continue
		}
		var colList []string
		for _, c := range strings.Split(cols, ",") {
			c = strings.TrimSpace(c)
			if c != "" {
				colList = append(colList, c)
			}
		}
		idx := indexInfo{name: idxName, unique: unique, table: key, columns: colList}
		// 找这个索引后面的 WHERE
		if pos := strings.Index(ddl, "CREATE"); pos >= 0 {
			_ = pos
		}
		t.indexes = append(t.indexes, idx)
	}

	// 补 WHERE 子句：从 "CREATE ... INDEX name ... ;" 整句里找 WHERE
	for _, line := range splitStatements(ddl) {
		if !strings.Contains(strings.ToUpper(line), "CREATE ") || !strings.Contains(strings.ToUpper(line), "INDEX") {
			continue
		}
		m := reCreateIndex.FindStringSubmatch(line)
		if m == nil {
			continue
		}
		idxName, key := m[2], m[3]+"."+m[4]
		if w := extractWhere(line); w != "" {
			if t, ok := tables[key]; ok {
				for i := range t.indexes {
					if t.indexes[i].name == idxName {
						t.indexes[i].where = w
					}
				}
			}
		}
	}

	return tables
}

func splitStatements(ddl string) []string {
	var out []string
	var cur strings.Builder
	for _, r := range ddl {
		if r == ';' {
			out = append(out, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteRune(r)
	}
	if strings.TrimSpace(cur.String()) != "" {
		out = append(out, cur.String())
	}
	return out
}

// extractWhere 取一条语句里 INDEX 之后的 WHERE 子句
func extractWhere(stmt string) string {
	upper := strings.ToUpper(stmt)
	// 找 "INDEX" 后面第一个 WHERE
	idx := strings.Index(upper, "INDEX")
	if idx < 0 {
		return ""
	}
	rest := upper[idx:]
	wi := strings.Index(rest, " WHERE ")
	if wi < 0 {
		return ""
	}
	return strings.TrimSpace(stmt[idx+wi+7:])
}

// ---- 7 项检查 ----

type checkResult struct {
	name   string
	pass   bool
	detail string
}

// hasColumn 按「顶层逗号切分」判断列是否存在。
// 不能用 ^\s*col\s 的行首匹配：真实迁移里一行可能有多个列定义
// （d24 的 DDL 就是紧凑写法），行首匹配会漏掉大部分列。
func hasColumn(body, col string) bool {
	for _, frag := range splitCols(body) {
		f := strings.TrimSpace(frag)
		if f == col || strings.HasPrefix(f, col+" ") {
			return true
		}
	}
	return false
}

// splitCols 按顶层逗号切分建表语句的列（忽略括号内的逗号）。
// 先剥掉 -- 行注释，否则「-- 乐观锁（d23）」会把后面的 deleted_at 列粘在一起。

func splitCols(body string) []string {
	body = reComment.ReplaceAllString(body, "")
	var out []string
	depth, cur := 0, strings.Builder{}
	for _, r := range body {
		switch r {
		case '(':
			depth++
			cur.WriteRune(r)
		case ')':
			depth--
			cur.WriteRune(r)
		case ',':
			if depth == 0 {
				out, cur = append(out, cur.String()), strings.Builder{}
			} else {
				cur.WriteRune(r)
			}
		default:
			cur.WriteRune(r)
		}
	}
	if strings.TrimSpace(cur.String()) != "" {
		out = append(out, cur.String())
	}
	return out
}

func columnDecl(body, col string) string {
	for _, line := range strings.Split(body, "\n") {
		l := strings.TrimSpace(line)
		if !hasColumn(l, col) {
			continue
		}
		fields := strings.Fields(l)
		if len(fields) == 0 {
			continue
		}
		return l
	}
	return ""
}

func main() {

fmt.Println("=== 1. 建 11 张表：前 20 天的每条纪律对应哪一行 DDL ===")
fmt.Println()
all := ddlHomeos + ddlFinance
tables := parse(all)
keys := make([]string, 0, len(tables))
for k := range tables {
	keys = append(keys, k)
}
sortStrings(keys)

// 按「业务域 + 逻辑顺序」展示，而不是按解析出来的字母序 ——
// 字母序会让「表名」和「它体现的约束」对不上，那就没意义了。
mapping := []struct {
	name string
	why  string
}{
	{"homeos.homeos_user", "邮箱唯一用部分索引（d12）；密码只存哈希"},
	{"homeos.family", "带 timezone 字段 —— 时间一律带时区（d4）"},
	{"homeos.family_member", "一人在一个家庭只有一个角色（d12 的部分唯一索引）"},
	{"homeos.invitation", "邀请码只存哈希；同邮箱同家庭只能有一条待接受邀请"},
	{"homeos.notification", "未读索引含 created_at DESC（d17 的列顺序）"},
	{"homeos.refresh_token", "轮换机制 rotated_from + 过期清理索引"},
	{"finance.finance_account", "金额用整数分（d5）+ 部分唯一索引（d12）"},
	{"finance.finance_category", "部分唯一索引 —— d12 那个事故的正主"},
	{"finance.finance_transaction", "游标分页复合索引（d15/d17）+ version 乐观锁（d23）"},
	{"finance.finance_budget", "COALESCE 处理 category_id 可空（d2 的 NULL 语义）"},
	{"finance.finance_recurring", "定时任务热路径索引（next_run_on 部分索引）"},
}
// 行格式：│ <col1> │ <col2> │ <col3> │（每个单元格前后各一个空格）
const col1, col2, col3 = 4, 28, 44
row := func(a, b, c string) string {
	return "  │ " + padWide(a, col1) + " │ " + padWide(b, col2) + " │ " + padWide(c, col3) + " │"
}
border := func(l, m, r string) string {
	return "  " + l + strings.Repeat("─", col1+2) + m +
		strings.Repeat("─", col2+2) + m + strings.Repeat("─", col3+2) + r
}
fmt.Println(border("┌", "┬", "┐"))
fmt.Println(row("#", "表名", "体现前面哪天的约束"))
fmt.Println(border("├", "┼", "┤"))
for i, m := range mapping {
	mark := "✓"
	if _, ok := tables[m.name]; !ok {
		mark = "✗"
	}
	fmt.Println(row(fmt.Sprintf("%d", i+1), m.name, m.why+" "+mark))
}
fmt.Println(border("└", "┴", "┘"))
fmt.Println()
fmt.Printf("  共 %d 张业务表 + schema_migrations（第 12 张，golang-migrate 自动维护）\n", len(tables))
fmt.Println("  ✓ 表示该表确实出现在上面那份 DDL 里。")
fmt.Println("  解析自下面这两份 DDL：")
fmt.Println("    server/migrations/homeos/homeos_0001_init.up.sql")
fmt.Println("    server/migrations/finance/finance_0001_init.up.sql")

fmt.Println()

fmt.Println("=== 4. DDL 检查器：真跑一遍 ===")
fmt.Println("  下面 7 项检查是**真实执行**的 —— 它解析上面那份 DDL 文本，")
fmt.Println("  按规则逐项校验。这正是 tech-plan §10.2 的「表结构门禁」要做的事。")
fmt.Println()

var results []checkResult

// 检查 1：11 张表
results = append(results, checkResult{
	name:   "1. 表数量 = 11 张业务表（+schema_migrations 由 migrate 维护）",
	pass:   len(tables) == 11,
	detail: fmt.Sprintf("实际解析到 %d 张：%s", len(tables), strings.Join(keys, ", ")),
})

// 检查 2：带 family_id 的表必须有 version / deleted_at
var badTenant []string
var tenantTables []string
for _, k := range keys {
	t := tables[k]
	if !hasColumn(t.body, "family_id") {
		continue
	}
	tenantTables = append(tenantTables, k)
	// users 表也要 version/deleted_at，一视同仁
	if !hasColumn(t.body, "version") || !hasColumn(t.body, "deleted_at") {
		badTenant = append(badTenant, k)
	}
}
results = append(results, checkResult{
	name:   "2. 每张带 family_id 的表都有 version + deleted_at",
	pass:   len(badTenant) == 0,
	detail: fmt.Sprintf("检查了 %d 张租户表，%d 张缺列", len(tenantTables), len(badTenant)),
})

// 检查 3：family_id 必须是 UUID NOT NULL
var badFam []string
for _, k := range tenantTables {
	decl := columnDecl(tables[k].body, "family_id")
	if !strings.Contains(strings.ToUpper(decl), "UUID") ||
		!strings.Contains(strings.ToUpper(decl), "NOT NULL") {
		badFam = append(badFam, k)
	}
}
results = append(results, checkResult{
	name:   "3. family_id 都是 UUID NOT NULL",
	pass:   len(badFam) == 0,
	detail: fmt.Sprintf("%d 张表检查，%d 张不合格", len(tenantTables), len(badFam)),
})

// 检查 4：外键引用的表都存在
var badFK []string
fkCount := 0
for _, k := range keys {
	for _, m := range reRefTable.FindAllStringSubmatch(tables[k].body, -1) {
		fkCount++
		ref := m[1] + "." + m[2]
		if _, ok := tables[ref]; !ok {
			badFK = append(badFK, fmt.Sprintf("%s → %s", k, ref))
		}
	}
}
results = append(results, checkResult{
	name:   "4. 外键引用的表都存在",
	pass:   len(badFK) == 0,
	detail: fmt.Sprintf("共 %d 个外键，%d 个指向不存在的表", fkCount, len(badFK)),
})

// 检查 5：索引名全局唯一
nameCount := map[string]int{}
for _, k := range keys {
	for _, idx := range tables[k].indexes {
		nameCount[idx.name]++
	}
}
var dupIdx []string
for n, c := range nameCount {
	if c > 1 {
		dupIdx = append(dupIdx, fmt.Sprintf("%s×%d", n, c))
	}
}
sortStrings(dupIdx)
results = append(results, checkResult{
	name:   "5. 索引名不重复",
	pass:   len(dupIdx) == 0,
	detail: fmt.Sprintf("共 %d 个索引，%d 个重名", len(nameCount), len(dupIdx)),
})

// 检查 6：唯一索引必须带 WHERE deleted_at IS NULL（软删表的铁律）
var badUniq []string
uniqCount := 0
for _, k := range keys {
	t := tables[k]
	if !hasColumn(t.body, "deleted_at") {
		continue
	}
	for _, idx := range t.indexes {
		if !idx.unique {
			continue
		}
		// token_hash / email 这类天然唯一的索引不需要
		if strings.Contains(strings.Join(idx.columns, ","), "token_hash") ||
			strings.Contains(strings.Join(idx.columns, ","), "lower(email)") {
			continue
		}
		uniqCount++
		if !strings.Contains(idx.where, "deleted_at IS NULL") {
			badUniq = append(badUniq, fmt.Sprintf("%s.%s", k, idx.name))
		}
	}
}
results = append(results, checkResult{
	name:   "6. 业务唯一索引都带 WHERE deleted_at IS NULL",
	pass:   len(badUniq) == 0,
	detail: fmt.Sprintf("检查 %d 个业务唯一索引，%d 个漏了软删条件", uniqCount, len(badUniq)),
})

// 检查 7：money 列必须是整数分
var badMoney []string
for _, k := range keys {
	body := tables[k].body
	for _, m := range regexp.MustCompile(`(?i)(\w*cents)\s+(\w+)`).FindAllStringSubmatch(body, -1) {
		typ := strings.ToUpper(m[2])
		if strings.Contains(typ, "INT") && !strings.Contains(typ, "POINT") {
			continue
		}
		badMoney = append(badMoney, fmt.Sprintf("%s.%s %s", k, m[1], m[2]))
	}
}
results = append(results, checkResult{
	name:   "7. 所有 money 列（*_cents）都是整数类型",
	pass:   len(badMoney) == 0,
	detail: fmt.Sprintf("%d 个不合格", len(badMoney)),
})

// 打印结果
passed := 0
for _, r := range results {
	mark := "✅"
	if !r.pass {
		mark = "❌"
	} else {
		passed++
	}
	fmt.Printf("  %s %s\n", mark, r.name)
	fmt.Printf("       %s\n", r.detail)
	if !r.pass {
		// 打印具体是哪些
		for _, b := range badTenant {
			if strings.Contains(r.name, "version") {
				fmt.Printf("         缺列: %s\n", b)
			}
		}
		for _, b := range badFam {
			if strings.Contains(r.name, "UUID") {
				fmt.Printf("         不合格: %s\n", b)
			}
		}
		for _, b := range badFK {
			if strings.Contains(r.name, "外键") {
				fmt.Printf("         悬空: %s\n", b)
			}
		}
		for _, b := range dupIdx {
			if strings.Contains(r.name, "索引名") {
				fmt.Printf("         重名: %s\n", b)
			}
		}
		for _, b := range badUniq {
			if strings.Contains(r.name, "唯一索引") {
				fmt.Printf("         漏软删条件: %s\n", b)
			}
		}
		for _, b := range badMoney {
			if strings.Contains(r.name, "money") {
				fmt.Printf("         %s\n", b)
			}
		}
	}
}
fmt.Println()
fmt.Printf("  结果：%d / %d 项通过\n", passed, len(results))
if passed == len(results) {
	fmt.Println("  ✅ 表结构门禁通过")
} else {
	fmt.Println("  ❌ 表结构门禁未通过 —— CI 应该在这里拦住这次提交")
}

fmt.Println()
fmt.Println("  下面把 finance_budget 的部分唯一索引去掉 WHERE，看看第 6 项会不会红：")
broken := strings.Replace(ddlFinance,
	"CREATE UNIQUE INDEX uniq_budget_family_period_category ON finance.finance_budget\n"+
		"  (family_id, COALESCE(category_id, '00000000-0000-0000-0000-000000000000'::uuid), period)\n"+
		"  WHERE deleted_at IS NULL;",
	"CREATE UNIQUE INDEX uniq_budget_family_period_category ON finance.finance_budget\n"+
		"  (family_id, COALESCE(category_id, '00000000-0000-0000-0000-000000000000'::uuid), period);", 1)
if broken == ddlFinance {
	fmt.Println("  （替换失败，跳过这个演示）")
} else {
	bt := parse(ddlHomeos + broken)
	var badU []string
	for _, k := range []string{"finance.finance_budget"} {
		if t, ok := bt[k]; ok {
			for _, idx := range t.indexes {
				if idx.unique && !strings.Contains(idx.where, "deleted_at IS NULL") {
					badU = append(badU, idx.name)
				}
			}
		}
	}
	if len(badU) > 0 {
		fmt.Printf("  ❌ 检查 6 变红：%s 漏了 WHERE deleted_at IS NULL\n", badU[0])
		fmt.Println("     → 这正是 d12 那个事故的 schema 形态，门禁在这里就挡住了。")
	} else {
		fmt.Println("  ⚠️ 没能抓到（检查器的 where 解析需要改进）")
	}
}

fmt.Println()

	fmt.Println("=== S3 d21 到此结束 ===")
	fmt.Println("明天把内存 store 换成 Postgres：定义接口、写两个实现、")
	fmt.Println("用同一套测试跑通，证明抽象是对的。")
}

// padWide 按「显示宽度」补空格（中文算 2 列），保证表格能对齐。
// Go 的 %-44s 是按字节数补的，中文会被撑爆，所以自己算。
func padWide(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

// isWide 粗略判断：CJK 统一表意文字、全角标点算 2 列
func isWide(r rune) bool {
	return (r >= 0x1100 && r <= 0x115F) ||
		(r >= 0x2E80 && r <= 0xA4CF) ||
		(r >= 0xAC00 && r <= 0xD7A3) ||
		(r >= 0xF900 && r <= 0xFAFF) ||
		(r >= 0xFE30 && r <= 0xFE6F) ||
		(r >= 0xFF00 && r <= 0xFF60) ||
		(r >= 0xFFE0 && r <= 0xFFE6)
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

