// =====================================================================
// W12 d22：把内存存储换成 Postgres —— 分类域从内存 store 迁到 DB。
//
// S1/S2 我们用内存 store（map + slice）跑通了全部分类接口。
// 今天把它换成 Postgres。核心不是「怎么写 SQL」，而是：
//
//   「换一个存储实现，业务代码要不要改？」
//
// 如果不用改，说明前面的抽象是对的；如果要改，说明抽象漏了。
// 所以本文件做一件事：**定义一个接口，写两个实现，用同一套测试跑通两者**。
// 测试真的跑了、真的都过了 —— 这才是「抽象正确」的证据。
//
// ⚠️ 诚实声明：PGStore 用 GORM DryRun 生成真实 SQL，但**没有真连数据库**。
//    它的「结果」是模拟的。D22 你起真库后要把同样的逻辑跑在真 SQL 上，
//    验证 DryRun 里看不到的部分（约束真的生效、事务真的回滚）。
// =====================================================================

package main

import (
	"errors"
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

var fixedNow = time.Date(2026, 10, 15, 9, 30, 0, 0, time.UTC)

// ---- 领域模型（和存储无关）----

type Category struct {
	ID        string
	FamilyID  string
	ParentID  *string // 可空：一级分类没有父分类
	Name      string
	Type      string // expense / income
	Icon      string
	Color     *string
	SortOrder int
	IsActive  bool
	Version   int
	Deleted   bool
}

var ErrNotFound = errors.New("分类不存在")
var ErrDuplicate = errors.New("同名分类已存在")
var ErrVersionConflict = errors.New("版本冲突，数据已被他人修改")

// =====================================================================
// 接口：业务代码只依赖它，不依赖具体存储
// =====================================================================

type CategoryStore interface {
	Create(c Category) (Category, error)
	GetByID(familyID, id string) (Category, error)
	List(familyID string) ([]Category, error)
	// Update 用乐观锁：expectedVersion 不匹配就返回 ErrVersionConflict
	Update(familyID, id, name string, expectedVersion int) (Category, error)
	SoftDelete(familyID, id string, expectedVersion int) error
	// 实现类的名字（仅用于测试输出）
	Impl() string
}

// =====================================================================
// 实现 A：内存 store（S1/S2 用的那个）
// =====================================================================

type MemStore struct {
	byID    map[string]*Category
	seq     int
	quiesce bool // 模拟「数据库唯一约束」的效果
}

func NewMemStore() *MemStore {
	return &MemStore{byID: map[string]*Category{}}
}

func (m *MemStore) Impl() string { return "MemStore（内存 map）" }

func (m *MemStore) Create(c Category) (Category, error) {
	// 模拟数据库的部分唯一索引：软删的行不参与判定
	for _, e := range m.byID {
		if e.FamilyID == c.FamilyID && e.Name == c.Name && !e.Deleted {
			return Category{}, ErrDuplicate
		}
	}
	m.seq++
	c.ID = fmt.Sprintf("cat-%03d", m.seq)
	c.Version = 1
	cp := c
	m.byID[c.ID] = &cp
	return c, nil
}

func (m *MemStore) GetByID(familyID, id string) (Category, error) {
	c, ok := m.byID[id]
	if !ok || c.Deleted || c.FamilyID != familyID {
		return Category{}, ErrNotFound
	}
	return *c, nil
}

func (m *MemStore) List(familyID string) ([]Category, error) {
	var out []Category
	for _, c := range m.byID {
		if c.FamilyID == familyID && !c.Deleted {
			out = append(out, *c)
		}
	}
	// 按 (sort_order, id) 排，和 d17 的索引一致
	for i := 1; i < len(out); i++ {
		for j := i; j > 0; j-- {
			a, b := out[j-1], out[j]
			if a.SortOrder < b.SortOrder || (a.SortOrder == b.SortOrder && a.ID < b.ID) {
				break
			}
			out[j-1], out[j] = b, a
		}
	}
	return out, nil
}

func (m *MemStore) Update(familyID, id, name string, expectedVersion int) (Category, error) {
	c, ok := m.byID[id]
	if !ok || c.Deleted || c.FamilyID != familyID {
		return Category{}, ErrNotFound
	}
	if c.Version != expectedVersion {
		return Category{}, ErrVersionConflict
	}
	// 改名也要检查唯一
	for _, e := range m.byID {
		if e.ID != id && e.FamilyID == familyID && e.Name == name && !e.Deleted {
			return Category{}, ErrDuplicate
		}
	}
	c.Name = name
	c.Version++
	return *c, nil
}

func (m *MemStore) SoftDelete(familyID, id string, expectedVersion int) error {
	c, ok := m.byID[id]
	if !ok || c.Deleted || c.FamilyID != familyID {
		return ErrNotFound
	}
	if c.Version != expectedVersion {
		return ErrVersionConflict
	}
	c.Deleted = true
	c.Version++
	return nil
}

// =====================================================================
// 实现 B：Postgres（GORM）
//
// DryRun 下不真连库，所以这里：
//   · 约束检查由本文件手工模拟（对应 Postgres 的 CHECK / 唯一索引）
//   · 真实 SQL 通过 DryRun 打印出来（D22 起库后照着跑）
// =====================================================================

type PGCategory struct {
	ID        string         `gorm:"primaryKey;type:uuid"`
	FamilyID  string         `gorm:"column:family_id;type:uuid;not null;index"`
	ParentID  *string        `gorm:"column:parent_id;type:uuid"`
	Name      string         `gorm:"column:name;type:varchar(32);not null"`
	Type      string         `gorm:"column:type;type:varchar(16);not null"`
	Icon      string         `gorm:"column:icon;type:varchar(32);not null;default:'wallet'"`
	Color     *string        `gorm:"column:color;type:varchar(9)"`
	SortOrder int            `gorm:"column:sort_order;not null;default:0"`
	IsActive  bool           `gorm:"column:is_active;not null;default:true"`
	Version   int            `gorm:"column:version;not null;default:1"`
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index"`
}

func (PGCategory) TableName() string { return "finance_category" }

type PGStore struct {
	db *gorm.DB
	// DryRun 下没有真数据，这里保留一份内存镜像用于演示结果
	mirror map[string]*Category
	seq    int
	sqlLog []string
}

func NewPGStore(dry bool) *PGStore {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun:               dry,
		DisableAutomaticPing: true,
		NowFunc:              func() time.Time { return fixedNow },
		Logger:               logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return &PGStore{db: db, mirror: map[string]*Category{}}
}

func (p *PGStore) Impl() string { return "PGStore（Postgres / GORM）" }

func (p *PGStore) record(sql string) { p.sqlLog = append(p.sqlLog, sql) }

func (p *PGStore) Create(c Category) (Category, error) {
	// 真实 Postgres 会用这个唯一索引挡：
	//   uniq_category_family_name (family_id, parent_id, name) WHERE deleted_at IS NULL
	for _, e := range p.mirror {
		if e.FamilyID == c.FamilyID && e.Name == c.Name && !e.Deleted {
			return Category{}, ErrDuplicate
		}
	}
	p.seq++
	c.ID = fmt.Sprintf("cat-%03d", p.seq)
	c.Version = 1
	p.record(p.db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Create(&PGCategory{
			ID: c.ID, FamilyID: c.FamilyID, Name: c.Name, Type: c.Type,
			Icon: "wallet", SortOrder: c.SortOrder, IsActive: true, Version: 1,
		})
	}))
	cp := c
	p.mirror[c.ID] = &cp
	return c, nil
}

func (p *PGStore) GetByID(familyID, id string) (Category, error) {
	st := p.db.Session(&gorm.Session{DryRun: true}).
		Where("id = ? AND family_id = ?", id, familyID).First(&PGCategory{})
	p.record(st.Statement.SQL.String())
	c, ok := p.mirror[id]
	if !ok || c.Deleted || c.FamilyID != familyID {
		return Category{}, ErrNotFound
	}
	return *c, nil
}

func (p *PGStore) List(familyID string) ([]Category, error) {
	st := p.db.Session(&gorm.Session{DryRun: true}).
		Where("family_id = ?", familyID).
		Order("sort_order ASC, id ASC").Find(&[]PGCategory{})
	p.record(st.Statement.SQL.String())
	var out []Category
	for _, c := range p.mirror {
		if c.FamilyID == familyID && !c.Deleted {
			out = append(out, *c)
		}
	}
	for i := 1; i < len(out); i++ {
		for j := i; j > 0; j-- {
			a, b := out[j-1], out[j]
			if a.SortOrder < b.SortOrder || (a.SortOrder == b.SortOrder && a.ID < b.ID) {
				break
			}
			out[j-1], out[j] = b, a
		}
	}
	return out, nil
}

func (p *PGStore) Update(familyID, id, name string, expectedVersion int) (Category, error) {
	p.record(p.db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&PGCategory{}).
			Where("id = ? AND family_id = ? AND version = ?", id, familyID, expectedVersion).
			Updates(map[string]any{
				"name":    name,
				"version": gorm.Expr("version + ?", 1),
			})
	}))
	c, ok := p.mirror[id]
	if !ok || c.Deleted || c.FamilyID != familyID {
		return Category{}, ErrNotFound
	}
	// ★ 这里是真正的乐观锁：RowsAffected == 0 → 版本已被别人推进
	if c.Version != expectedVersion {
		return Category{}, ErrVersionConflict
	}
	c.Name = name
	c.Version++
	return *c, nil
}

func (p *PGStore) SoftDelete(familyID, id string, expectedVersion int) error {
	p.record(p.db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Where("id = ? AND family_id = ? AND version = ?", id, familyID, expectedVersion).
			Delete(&PGCategory{ID: id})
	}))
	c, ok := p.mirror[id]
	if !ok || c.Deleted || c.FamilyID != familyID {
		return ErrNotFound
	}
	if c.Version != expectedVersion {
		return ErrVersionConflict
	}
	c.Deleted = true
	c.Version++
	return nil
}

// =====================================================================
// 同一套测试，两个实现都跑一遍
// =====================================================================

type testCase struct {
	name string
	run  func(s CategoryStore) string
}

func buildTests() []testCase {
	return []testCase{
		{"建一个分类", func(s CategoryStore) string {
			c, err := s.Create(Category{FamilyID: famA, Name: "餐饮", Type: "expense", SortOrder: 10})
			if err != nil {
				return "ERR " + err.Error()
			}
			return fmt.Sprintf("ok id=%s version=%d", c.ID, c.Version)
		}},
		{"建同名分类 → 应该失败（唯一约束）", func(s CategoryStore) string {
			_, err := s.Create(Category{FamilyID: famA, Name: "餐饮", Type: "expense"})
			if err != nil {
				return "ok 返回 " + err.Error()
			}
			return "FAIL 应该报错但成功了"
		}},
		{"建第二个分类", func(s CategoryStore) string {
			c, err := s.Create(Category{FamilyID: famA, Name: "交通", Type: "expense", SortOrder: 20})
			if err != nil {
				return "ERR " + err.Error()
			}
			return fmt.Sprintf("ok id=%s", c.ID)
		}},
		{"列出该家庭的分类", func(s CategoryStore) string {
			list, err := s.List(famA)
			if err != nil {
				return "ERR " + err.Error()
			}
			var names []string
			for _, c := range list {
				names = append(names, c.Name)
			}
			return fmt.Sprintf("ok %d 个: %s", len(list), strings.Join(names, ","))
		}},
		{"按 id 取", func(s CategoryStore) string {
			c, err := s.GetByID(famA, "cat-001")
			if err != nil {
				return "ERR " + err.Error()
			}
			return fmt.Sprintf("ok %s/%s", c.ID, c.Name)
		}},
		{"取别的家庭的分类 → 应该失败", func(s CategoryStore) string {
			_, err := s.GetByID("bbbbbbbb-0000-4000-8000-000000000002", "cat-001")
			if err != nil {
				return "ok 返回 " + err.Error()
			}
			return "FAIL 越权成功了"
		}},
		{"改名（version=1）", func(s CategoryStore) string {
			c, err := s.Update(famA, "cat-001", "餐饮(改)", 1)
			if err != nil {
				return "ERR " + err.Error()
			}
			return fmt.Sprintf("ok name=%s version=%d", c.Name, c.Version)
		}},
		{"用过期 version 改名 → 冲突", func(s CategoryStore) string {
			_, err := s.Update(famA, "cat-001", "再改一次", 1)
			if err != nil {
				return "ok 返回 " + err.Error()
			}
			return "FAIL 版本冲突没生效"
		}},
		{"软删（version=2）", func(s CategoryStore) string {
			err := s.SoftDelete(famA, "cat-001", 2)
			if err != nil {
				return "ERR " + err.Error()
			}
			return "ok"
		}},
		{"软删后重建同名 → 应该成功", func(s CategoryStore) string {
			c, err := s.Create(Category{FamilyID: famA, Name: "餐饮", Type: "expense", SortOrder: 30})
			if err != nil {
				return "FAIL " + err.Error()
			}
			return fmt.Sprintf("ok 新 id=%s（d12 的教训在这里生效）", c.ID)
		}},
		{"软删后再取原 id → 应该失败", func(s CategoryStore) string {
			_, err := s.GetByID(famA, "cat-001")
			if err != nil {
				return "ok 返回 " + err.Error()
			}
			return "FAIL 软删的行还能查到"
		}},
	}
}

func main() {
	fmt.Println("=== 1. 为什么先定义接口 ===")
	fmt.Println("  S1/S2 用内存 store 时，handler 直接调用 store 的具体方法。")
	fmt.Println("  这样做能跑，但换成 Postgres 时 handler 要全部改一遍 ——")
	fmt.Println("  因为它依赖的是具体类型，不是接口。")
	fmt.Println()
	fmt.Println("  正确顺序是：")
	fmt.Println("    ① 先定义接口 CategoryStore（只描述业务需要什么）")
	fmt.Println("    ② 实现 A（内存）和实现 B（Postgres）都满足它")
	fmt.Println("    ③ handler 只依赖接口")
	fmt.Println("  这样迁移就只是「换一个实现」，业务代码零改动。")
	fmt.Println()
	fmt.Println("  接口的方法（7 个，全部是业务语义，不是 SQL 语义）：")
	methods := []string{
		"Create(c) (Category, error)",
		"GetByID(familyID, id) (Category, error)",
		"List(familyID) ([]Category, error)",
		"Update(familyID, id, name, expectedVersion) (Category, error)",
		"SoftDelete(familyID, id, expectedVersion) error",
	}
	for _, m := range methods {
		fmt.Printf("    %s\n", m)
	}
	fmt.Println()
	fmt.Println("  注意每个查询方法都把 familyID 作为**必填的第一个参数** ——")
	fmt.Println("  这就是 d18/d19 讨论的「让纪律变成结构」。")
	fmt.Println("  忘记传 → 编译错误，而不是数据泄露。")

	fmt.Println()
	fmt.Println("=== 2. 同一套测试，跑两个实现 ===")
	fmt.Println()
	// 每个实现都用一份全新的实例，避免测试之间互相污染
	for _, mk := range []func() CategoryStore{
		func() CategoryStore { return NewMemStore() },
		func() CategoryStore { return NewPGStore(true) },
	} {
		s := mk()
		fmt.Printf("  ▸ %s\n", s.Impl())
		fmt.Println("    " + strings.Repeat("─", 52))
		pass, fail := 0, 0
		for _, t := range buildTests() {
			got := t.run(s)
			ok := !strings.HasPrefix(got, "FAIL") && !strings.HasPrefix(got, "ERR")
			mark := "✅"
			if !ok {
				mark = "❌"
				fail++
			} else {
				pass++
			}
			fmt.Printf("    %s %-38s %s\n", mark, t.name, got)
		}
		fmt.Printf("    %s\n", strings.Repeat("─", 52))
		fmt.Printf("    结果：%d 通过，%d 失败\n", pass, fail)
		fmt.Println()
	}

	fmt.Println("  两个实现跑出了完全一样的结果 —— 这就证明接口抽象是对的。")
	fmt.Println("  迁移的时候，只要 PGStore 的测试还绿，业务代码就不用动。")
	fmt.Println()
	fmt.Println("  ⚠️ 但要注意：MemStore 和 PGStore 的「约束检查」这里都是手写模拟的。")
	fmt.Println("     真实的 Postgres 里那些检查来自 d21 建的那些索引和 CHECK 约束。")
	fmt.Println("     D22 起库后要验证它们真的生效 —— 那时才是不用模拟的部分。")

	fmt.Println()
	fmt.Println("=== 3. PGStore 会发什么 SQL（真实生成）===")
	p := NewPGStore(true)
	// 跑一遍让 sqlLog 填满
	for _, t := range buildTests() {
		_ = t.run(p)
	}
	fmt.Println("  按执行顺序：")
	for i, sql := range p.sqlLog {
		fmt.Printf("    [%2d] %s\n", i+1, flat(sql))
	}
	fmt.Println()
	fmt.Println("  三个观察点：")
	fmt.Println("    ① 列表查询带 family_id + deleted_at IS NULL（GORM 自动加软删过滤）")
	fmt.Println("    ② UPDATE 带 version = ?（乐观锁，d23 专门讲）")
	fmt.Println("    ③ DELETE 变成 UPDATE deleted_at（因为有 gorm.DeletedAt 字段）")

	fmt.Println()
	fmt.Println("=== 4. 内存 store 和 Postgres 的逐项对比 ===")
	cmp := []struct{ dim, mem, pg string }{
		{"查找复杂度", "O(1)（map 命中）", "O(log n)（B-tree 索引）+ 网络往返"},
		{"并发安全", "要自己加锁", "数据库自己的 MVCC，不用管"},
		{"事务", "要自己实现（d11 演示过）", "BEGIN/COMMIT/ROLLBACK 原生支持"},
		{"持久化", "进程退出就没了", "重启还在"},
		{"多进程", "不可能（内存不共享）", "天然支持（这是选它的主要理由）"},
		{"查询能力", "只能全表扫内存", "JOIN / 聚合 / 排序 / 索引，全都有"},
		{"约束", "要手写代码检查", "NOT NULL / UNIQUE / CHECK / FK，数据库层强制"},
		{"内存占用", "数据常驻内存", "按需加载，大表也不怕"},
		{"循环查询代价", "几乎为 0（map 查找）", "N+1 会打爆数据库（d10）"},
		{"时区处理", "要自己转", "TIMESTAMPTZ 自动处理（d4）"},
	}
	fmt.Printf("  %-14s %-24s %s\n", "维度", "内存 store", "Postgres")
	for _, c := range cmp {
		fmt.Printf("  %-14s %-24s %s\n", c.dim, c.mem, c.pg)
	}
	fmt.Println()
	fmt.Println("  最后一行是迁移时最容易踩的坑：")
	fmt.Println("  在内存 store 里，「查列表再循环查详情」完全没问题（map 查找是纳秒级）。")
	fmt.Println("  同样的代码搬到数据库，就是 d10 讲的 N+1 —— 20 次网络往返。")
	fmt.Println("  **所以换存储不只是换实现，是要重新审视每一处查询模式。**")

	fmt.Println()
	fmt.Println("=== 5. 五步迁移法（每步都能回滚）===")
	steps := []struct {
		n    string
		what string
		how  string
		back string
	}{
		{"1", "加接口，不改实现",
			"定义 CategoryStore；把 MemStore 改成实现它；handler 依赖接口",
			"直接把 handler 改回调用 MemStore —— 只有机械改动"},
		{"2", "写 PGStore，用测试证明它对",
			"实现全部 7 个方法；跑上面那套测试，必须和 MemStore 一样全绿",
			"删掉 PGStore 即可，此时业务已经能切来切去"},
		{"3", "双写：新旧两边都写",
			"PG 为主（失败会报错），Mem 为影子（失败只记日志）",
			"关掉 Mem 写入。风险：双写期间两边数据可能已经不一致"},
		{"4", "切读 + 校验",
			"读走 PG；同时定期比对两边结果，差异报警",
			"读切回 Mem（Mem 数据可能已过期，所以要尽快走完这步）"},
		{"5", "删旧代码",
			"删掉 MemStore、去掉双写、清理相关测试 fixture",
			"从 git 恢复 —— 所以第 5 步单独一个 commit"},
	}
	fmt.Println()
	for _, s := range steps {
		fmt.Printf("  第 %s 步：%s\n", s.n, s.what)
		fmt.Printf("    怎么做：%s\n", s.how)
		fmt.Printf("    怎么回滚：%s\n", s.back)
		fmt.Println()
	}
	fmt.Println("  ⚠️ 最容易做错的是跳过第 4 步的「比对」。")
	fmt.Println("     双写期间两边不一致是很常见的（比如 PG 的唯一约束把某个写入拒了，")
	fmt.Println("     而 Mem 那边写成功了）。不比对就切读，等于把不一致暴露给用户。")

	fmt.Println()
	fmt.Println("=== 6. 迁移时必须一起改的三件事 ===")
	together := []struct{ what, why string }{
		{"N+1 查询", "内存里零成本，DB 里是灾难（d10）。代码一模一样，代价差 1000 倍"},
		{"分页方式", "内存用 skip/take，DB 里深分页会退化（d13/d17）。必须换成游标"},
		{"时间处理", "内存里的 time.Time 本身带时区，DB 里要显式用 TIMESTAMPTZ（d4）"},
		{"错误处理", "内存里的「不存在」是自己判断的，DB 里可能是唯一约束/外键报错，要转成 409/400"},
		{"并发控制", "内存里靠锁，DB 里靠 version 乐观锁或 SELECT ... FOR UPDATE（d11/d23）"},
	}
	for i, t := range together {
		fmt.Printf("  %d. %s\n", i+1, t.what)
		fmt.Printf("     %s\n", t.why)
	}

	fmt.Println()
	fmt.Println("=== 7. 与 JS/前端对比 ===")
	fmt.Println("  ① JS 里也有同样的问题，Prisma 就是干这个的。")
	fmt.Println("     但 Node 生态更常见的做法是「直接换掉调用点」而不是抽接口，")
	fmt.Println("     结果就是从 JSON 文件迁到 Postgres 时要改几十处。")
	fmt.Println("  ② Node 的 in-memory store（比如测试用的 mock）很容易写得很随意：")
	fmt.Println("     「反正只是测试」。但如果业务代码直接依赖它，")
	fmt.Println("     生产和测试的差异就会以诡异的方式冒出来。")
	fmt.Println("  ③ TS 的 interface 和 Go 的 interface 是同一个机制，但有个差别：")
	fmt.Println("     TS 的 interface 是**结构化**的（隐式实现），Go 要求**显式**声明；")
	fmt.Println("     TS 只要方法签名对得上就算实现，Go 要写 `var _ CategoryStore = (*MemStore)(nil)`。")
	fmt.Println("     Go 更啰嗦，但换来的是「接口满足关系被编译器检查」。")

	fmt.Println()
	fmt.Println("=== 8. 一个实践建议：接口不要泄漏 SQL 概念 ===")
	fmt.Println("  ❌ 泄漏了 SQL 的接口：")
	fmt.Println("    type CategoryStore interface {")
	fmt.Println("      QueryWithFilter(ctx, sqlStr string, args ...any) ([]Category, error)  // ← 泄漏")
	fmt.Println("      GetRaw(id string) (*sql.Row, error)                                   // ← 泄漏")
	fmt.Println("    }")
	fmt.Println("    问题：业务代码可以拼任意 SQL，多租户过滤就守不住了")
	fmt.Println()
	fmt.Println("  ✅ 干净的接口：")
	fmt.Println("    type CategoryStore interface {")
	fmt.Println("      List(familyID string) ([]Category, error)  // 只说业务，不说怎么查")
	fmt.Println("    }")
	fmt.Println("    好处：familyID 在签名里，泄漏不了；SQL 怎么写是实现内部的事")
	fmt.Println()
	fmt.Println("  判断标准很简单：**接口里出现 string 类型的 SQL 或表名，就是泄漏了。**")

	fmt.Println()
	fmt.Println("=== S3 d22 到此结束 ===")
	fmt.Println("明天讲 version 乐观锁：为什么它必须是第一行代码而不是最后补上，")
	fmt.Println("以及冲突时为什么要返回 409 而不是 500 —— 会真跑出冲突演示。")
}

func flat(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

