// =====================================================================
// W13 d24：S3 收口 —— 自查脚本 + 费曼复盘。
//
// 两件事：
//   ① 写 scripts/s3-check.sh：把 24 天里所有「靠纪律」的东西变成 CI 门禁
//   ② 费曼复盘：把整个 S3 讲给一个只会 JS 的人听
//
// 自查部分是真跑的：
//   · 用 os.ReadDir 真读 lab/s3 目录，统计实验程序
//   · 用正则真解析 DDL，做 7 项表结构检查（同 d21）
//   · 打印脚本内容（作为 artifacts 交付）
// =====================================================================

package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// labDir 是实验目录。真库起法不同路径可能不同，这里从模块根做一次探测。
var labCandidates = []string{
	"lab/s3",
	"../../lab/s3",
}

func findLabDir() string {
	for _, p := range labCandidates {
		if st, err := os.Stat(p); err == nil && st.IsDir() {
			return p
		}
	}
	return ""
}

type gateResult struct {
	name  string
	pass  bool
	note  string
	count int
}

func main() {
	fmt.Println("=== 1. S3 自查：把纪律变成门禁 ===")
	fmt.Println()
	fmt.Println("  这 24 天里学到的绝大多数规则，本质上都是「要记得做某事」。")
	fmt.Println("  而「要记得」在团队里必然失效。所以最后一步是把它们自动化：")
	fmt.Println()
	rules := []struct{ day, rule, why string }{
		{"d2", "money 用整数分，不用浮点", "浮点累加必然有误差，对账时差一分钱也要查半天"},
		{"d4", "时间列一律 TIMESTAMPTZ", "差一个字母就是时区 bug，且很难复现"},
		{"d7", "迁移文件命名 {code}_{seq}_{desc}", "命名不统一就无法机械检查归属"},
		{"d8", "up → down → up 可重放", "不可重放的迁移会让每个人的库状态都不一样"},
		{"d10", "禁止在 for 循环里查库", "N+1 在数据量小时完全看不出来"},
		{"d12", "唯一约束用部分索引", "软删的行会一直占着键，导致重建失败"},
		{"d13", "分页用游标，不用 offset", "offset 会重复和遗漏，且深分页会退化"},
		{"d14", "游标的 ORDER BY 必须和比较键一致", "不一致就会漏行"},
		{"d15", "游标要绑定筛选条件指纹", "用户改筛选条件后旧游标会静默返回错数据"},
		{"d17", "复合索引等值列在前、范围列在后", "顺序反了索引就废了"},
		{"d18", "每条查询都带 family_id", "漏一次就是数据泄露"},
		{"d20", "RLS 必须 FORCE", "不加 FORCE 时 owner 绕过，RLS 形同虚设"},
		{"d21", "每张表都有 version / deleted_at", "事后补加会留下无法追溯的历史"},
		{"d23", "写操作带 version 条件 + 检查 RowsAffected", "否则丢失更新是静默的"},
	}
	fmt.Printf("  %-6s %-38s %s\n", "来源", "规则", "为什么必须自动化")
	for _, r := range rules {
		fmt.Printf("  %-6s %-38s %s\n", r.day, r.rule, r.why)
	}
	fmt.Println()
	fmt.Println("  14 条规则，没有一条能靠人记住。所以要写进 s3-check.sh。")

	fmt.Println()
	fmt.Println("=== 2. 自查器：真跑一遍 ===")
	fmt.Println()

	var gates []gateResult

	// 门禁 1：实验程序齐备
	labDir := findLabDir()
	var dirs []string
	if labDir != "" {
		entries, err := os.ReadDir(labDir)
		if err == nil {
			for _, e := range entries {
				if e.IsDir() && strings.HasPrefix(e.Name(), "d") {
					dirs = append(dirs, e.Name())
				}
			}
		}
	}
	sortStrings(dirs)
	gates = append(gates, gateResult{
		name:  "1. 实验程序目录（d01..d24）",
		pass:  len(dirs) >= 20,
		note:  fmt.Sprintf("%s 下有 %d 个实验目录", orDefault(labDir, "未找到 lab 目录"), len(dirs)),
		count: len(dirs),
	})
	if len(dirs) > 0 {
		fmt.Printf("    目录：%s\n", strings.Join(dirs, " "))
	}

	// 门禁 2：DDL 必备列（同 d21）
	tables := loadDDLTables()
	tenantTables := 0
	badVersion := 0
	badFamily := 0
	for _, t := range tables {
		if !columnExists(t.body, "family_id") {
			continue
		}
		tenantTables++
		if !columnExists(t.body, "version") || !columnExists(t.body, "deleted_at") {
			badVersion++
		}
		decl := columnDecl(t.body, "family_id")
		u := strings.ToUpper(decl)
		if !strings.Contains(u, "UUID") || !strings.Contains(u, "NOT NULL") {
			badFamily++
		}
	}
	gates = append(gates, gateResult{
		name: "2. 租户表都有 family_id(UUID NOT NULL) + version + deleted_at",
		pass: len(tables) == 11 && badVersion == 0 && badFamily == 0,
		note: fmt.Sprintf("%d 张表，租户表 %d 张，缺 version/deleted_at %d 张，family_id 不合格 %d 张",
			len(tables), tenantTables, badVersion, badFamily),
		count: len(tables),
	})

	// 门禁 3：部分唯一索引
	badPartial := 0
	uniqCount := 0
	for _, t := range tables {
		for _, idx := range t.indexes {
			if !idx.unique {
				continue
			}
			cols := strings.Join(idx.cols, ",")
			if strings.Contains(cols, "token_hash") || strings.Contains(cols, "email") ||
				strings.Contains(cols, "phone") {
				continue
			}
			uniqCount++
			if !strings.Contains(idx.where, "deleted_at IS NULL") {
				badPartial++
			}
		}
	}
	gates = append(gates, gateResult{
		name:  "3. 业务唯一索引都带 WHERE deleted_at IS NULL",
		pass:  badPartial == 0 && uniqCount > 0,
		note:  fmt.Sprintf("检查 %d 个业务唯一索引，%d 个漏了软删条件", uniqCount, badPartial),
		count: uniqCount,
	})

	// 门禁 4：money 列是整数
	badMoney := 0
	moneyCount := 0
	for _, t := range tables {
		for _, m := range regexp.MustCompile(`(?i)(\w*cents)\s+(\w+)`).FindAllStringSubmatch(t.body, -1) {
			moneyCount++
			typ := strings.ToUpper(m[2])
			if !strings.Contains(typ, "INT") {
				badMoney++
			}
		}
	}
	gates = append(gates, gateResult{
		name:  "4. 所有 money 列（*_cents）都是整数类型",
		pass:  badMoney == 0 && moneyCount > 0,
		note:  fmt.Sprintf("%d 个 money 列，%d 个用了浮点", moneyCount, badMoney),
		count: moneyCount,
	})

	// 门禁 5：时间列带时区
	badTime := 0
	timeCount := 0
	for _, t := range tables {
		timeCount += strings.Count(t.body, "TIMESTAMPTZ")
		badTime += strings.Count(t.body, "TIMESTAMP ") +
			strings.Count(t.body, "TIMESTAMP\n") +
			strings.Count(t.body, " TIMESTAMP,")
	}
	gates = append(gates, gateResult{
		name:  "5. 时间列用 TIMESTAMPTZ（没有裸 TIMESTAMP）",
		pass:  badTime == 0 && timeCount > 0,
		note:  fmt.Sprintf("%d 个 TIMESTAMPTZ，%d 个裸 TIMESTAMP", timeCount, badTime),
		count: timeCount,
	})

	// 门禁 6：游标分页索引
	cursorIdx := 0
	for _, t := range tables {
		for _, idx := range t.indexes {
			cols := strings.Join(idx.cols, " ")
			if strings.Contains(cols, "family_id") && strings.Contains(cols, "DESC") &&
				strings.Contains(cols, "id DESC") {
				cursorIdx++
			}
		}
	}
	gates = append(gates, gateResult{
		name:  "6. 游标分页索引存在 (family_id, ... DESC, id DESC)",
		pass:  cursorIdx > 0,
		note:  fmt.Sprintf("找到 %d 个符合列顺序的游标索引", cursorIdx),
		count: cursorIdx,
	})

	// 打印结果
	passed := 0
	for i, g := range gates {
		mark := "✅"
		if !g.pass {
			mark = "❌"
		} else {
			passed++
		}
		fmt.Printf("  %s 门禁 %s\n", mark, g.name)
		fmt.Printf("       %s\n", g.note)
		_ = i
	}
	fmt.Println()
	fmt.Printf("  门禁结果：%d / %d 通过\n", passed, len(gates))
	if passed == len(gates) {
		fmt.Println("  ✅ S3 结构自查通过")
	} else {
		fmt.Println("  ❌ 有门禁未通过 —— CI 应该在这里拦住提交")
	}

	fmt.Println()
	fmt.Println("=== 3. scripts/s3-check.sh（交付物）===")
	fmt.Println()
	fmt.Println("  下面是今天要写进项目的脚本。它把上面的门禁变成可执行的：")
	fmt.Println()
	for _, line := range strings.Split(checkScript, "\n") {
		fmt.Println("  " + line)
	}

	fmt.Println()
	fmt.Println("=== 4. 费曼复盘：把 S3 讲给一个只会 JS 的人听 ===")
	fmt.Println()
	fmt.Println("  「你是一个前端工程师，接下来要做一个记账 App 的后端。")
	fmt.Println("   数据库你已经会用了 —— 建表、SELECT、INSERT、UPDATE。")
	fmt.Println("   你现在有 24 天时间要搞清楚一件事：**什么时候必须换掉你熟悉的那套做法。**」")
	fmt.Println()

	lessons := []struct{ topic, say string }{
		{"钱不能用小数",
			"「你肯定写过 `0.1 + 0.2`。在 JS 里它是 0.30000000000000004。\n" +
				"    一笔账算一百次，误差会攒到用户投诉对不上数。\n" +
				"    所以金额存整数分：`amount_cents = 1137` 就是 11.37 元。\n" +
				"    加减都是整数运算，永远不会错。显示时才除以 100。\n" +
				"    这一条在小数点后两位时看不出来，但账目一多就必然出事。」"},
		{"时间必须带时区",
			"「你写过 `new Date('2026-10-01')`。它在 JS 里按**浏览器本地时区**解析。\n" +
				"    纽约的用户看到的『10 月 1 日』和服务端算的可能差一天。\n" +
				"    数据库里要用 TIMESTAMPTZ（带时区），不是 TIMESTAMP（不带）。\n" +
				"    差一个字母 tz，你的时间就永远偏 8 小时。」"},
		{"数据库约束比代码检查可靠",
			"「你可能会写 `if (!exists) insert()`。\n" +
				"    两个请求同时进来，都会查到『不存在』，然后都插入 —— 成功了两次。\n" +
				"    代码里的『先查后插』在并发下必然失效。\n" +
				"    数据库的唯一索引是**原子**的，它是最后一道防线。\n" +
				"    约束要写在数据库里，不是写在 if 里。」"},
		{"软删有个大坑",
			"「你删了分类，但想保留历史数据，于是不真的 DELETE，改成标记 deleted。\n" +
				"    然后用户想重建一个同名分类 —— 报错 duplicate key！\n" +
				"    因为那一行还在表里，还占着唯一键。\n" +
				"    解法是**部分索引**：`UNIQUE (family_id, name) WHERE deleted_at IS NULL`。\n" +
				"    让已删除的行自动退出约束。这个坑真实到大部分项目都会遇到。」"},
		{"分页不能用 offset",
			"「`LIMIT 10 OFFSET 30` 看起来很对。问题是：用户翻页时数据变了怎么办。\n" +
				"    他看到第 3 页时，你插入了 3 条新数据 —— \n" +
				"    所有行的位置都往后挪了 3 格，但 OFFSET 30 还停在原地。\n" +
				"    结果：有 3 条被看了两遍，还有 3 条永远看不到。\n" +
				"    正确做法是**游标分页**：不传页码，传『上一页最后一条的 (时间, id)』，\n" +
				"    SQL 用 `WHERE (created_at, id) < (?, ?)`。\n" +
				"    新数据只会在第一页出现，不会挤掉后面的任何一行。\n" +
				"    我们用 1000 条数据算过：offset 漏 3 条 + 重复 3 条，数字刚好对得上。」"},
		{"多租户是最容易翻车的",
			"「你有 100 个家庭共用一个数据库。每张表都有 family_id 列。\n" +
				"    听起来万事大吉？错。**表有 family_id ≠ 查询有 family_id**。\n" +
				"    只要有一条查询忘了写 `WHERE family_id = ?`，就泄露了别人的数据。\n" +
				"    我们实测过：漏一个条件，返回 7 条数据里有 3 条是别人的（43%）。\n" +
				"    而且这个 bug：代码看着完全正常、单测能过（测试只有一个家庭）、\n" +
				"    code review 抓不住（谁会想到少了这个条件）。\n" +
				"    解法有三层：应用层每条查询都带 + 数据库 RLS 兜底 + 越权测试。\n" +
				"    关键是别把安全寄托在『大家记得写』上。」"},
		{"并发修改要显式处理",
			"「妈妈和爸爸同时改同一个分类。后保存的会静默覆盖先保存的。\n" +
				"    两个人都看到『保存成功』，但妈妈的数据没了。\n" +
				"    解法：给表加 version 列，更新时带上 `WHERE version = 我读到的值`。\n" +
				"    如果影响了 0 行，说明有人抢先了 —— 返回 409 Conflict。\n" +
				"    **version 必须是第一行代码**。事后补加时，历史数据全是 1，\n" +
				"    你根本没法知道哪行被改过。而且补加期间正好是最乱的时候。」"},
		{"别把数据库当内存用",
			"「你在内存里用 Map/数组做存储，写了这样的代码：\n" +
				"    查列表 → 遍历 → 每条再查一次详情\n" +
				"    在内存里这几乎不花时间（Map 查找是纳秒级）。\n" +
				"    换成数据库，同样的代码就是 **N+1 查询**：20 条数据发 21 次网络往返。\n" +
				"    每条 SQL 单独看都很快，致命的是**次数**。\n" +
				"    所以从内存迁到数据库不是『换个实现』，\n" +
				"    是要重新审视每一处查询模式。\n" +
				"    这也是为什么接口要先定义好，让两个实现跑同一套测试。」"},
	}

	for i, l := range lessons {
		fmt.Printf("  ── 第 %d 课：%s ──\n", i+1, l.topic)
		for _, line := range strings.Split(l.say, "\n") {
			fmt.Println("  " + line)
		}
		fmt.Println()
	}

	fmt.Println("  如果你能对着上面 8 条讲清楚，S3 就真的过了。")
	fmt.Println("  讲不清楚的那一条，回去重看对应的日子。")
	fmt.Println()

	fmt.Println("=== 5. S3 的知识地图 ===")
	fmt.Println()
	fmt.Println("  W9（d1-d6）数据库基础")
	fmt.Println("    d1 手写 DDL，四种约束各防什么")
	fmt.Println("    d2 四种约束的实际语义：NULL 不参与唯一判定、外键的原子性")
	fmt.Println("    d3 索引什么时候需要，B-tree 靠前缀定位")
	fmt.Println("    d4 TIMESTAMP vs TIMESTAMPTZ，时区")
	fmt.Println("    d5 money 用整数分，浮点为什么不行")
	fmt.Println("    d6 docker-compose 起本地环境")
	fmt.Println()
	fmt.Println("  W10（d7-d12）迁移与 ORM")
	fmt.Println("    d7 golang-migrate 接入，命名约定")
	fmt.Println("    d8 up → down → up 可重放")
	fmt.Println("    d9 GORM 基础，自动迁移的隐患，手写 SQL 的边界")
	fmt.Println("    d10 N+1 查询，三种解法的真实次数")
	fmt.Println("    d11 事务：转账、隔离级别、rollback")
	fmt.Println("    d12 ★ 软删 × 唯一约束的冲突")
	fmt.Println()
	fmt.Println("  W11（d13-d18）游标分页")
	fmt.Println("    d13 ★ 为什么 offset 会跳数据（1000 条算清楚）")
	fmt.Println("    d14 ★ 复合游标 (created_at, id) 的实现")
	fmt.Println("    d15 多条件筛选：时间窗口 + family_id + 游标指纹")
	fmt.Println("    d16 稳定性：新增/软删/改排序键的三种后果")
	fmt.Println("    d17 索引列顺序 + EXPLAIN 验证")
	fmt.Println("    d18 ★ 多租户隔离：表有 family_id ≠ 查询有")
	fmt.Println()
	fmt.Println("  W12（d19-d24）多租户与收口")
	fmt.Println("    d19 ★ 越权漏洞演示与测试方法")
	fmt.Println("    d20 数据库层兜底：schema / 权限 / RLS")
	fmt.Println("    d21 建 11 张表 + DDL 门禁")
	fmt.Println("    d22 内存 store → Postgres，接口抽象验证")
	fmt.Println("    d23 ★ version 乐观锁与 409")
	fmt.Println("    d24 S3 收口与费曼复盘")
	fmt.Println()
	fmt.Println("  标 ★ 的五个是本阶段必须讲透的：")
