  echo "$LEAKY" | sed 's/^/       /'
fi

echo
if [ "$FAILED" -eq 0 ]; then
  echo "✅ S3 全部门禁通过"
  exit 0
else
  echo "❌ $FAILED 项门禁未通过"
  exit 1
