	fmt.Printf("    目录：%s\n", strings.Join(dirs, " "))
}

// 门禁 2：DDL 必备列（同 d21）
tables := loadDDLTables()
tenantTables := 0
badVersion := 0
badFamily := 0
for _, t := range tables {
	if !columnExists(t.body, "family_id") {
		continue
	}
	tenantTables++
	if !columnExists(t.body, "version") || !columnExists(t.body, "deleted_at") {
		badVersion++
	}
	decl := columnDecl(t.body, "family_id")
	u := strings.ToUpper(decl)
	if !strings.Contains(u, "UUID") || !strings.Contains(u, "NOT NULL") {
		badFamily++
	}
}
gates = append(gates, gateResult{
