var reComment = regexp.MustCompile(`(?m)--[^\n]*`)

var (
	reCreateTable = regexp.MustCompile(`(?is)CREATE TABLE (\w+)\.(\w+)\s*\((.*?)\n\);`)
	reCreateIndex = regexp.MustCompile(`(?i)CREATE (UNIQUE )?INDEX (\w+)\s+ON\s+(\w+)\.(\w+)\s*\(([^)]*)\)`)
)

type tbl struct {
	name    string
	body    string
	indexes []idx
}

type idx struct {
	name   string
	unique bool
	cols   []string
	where  string
}

