func loadDDLTables() []tbl {
	var out []tbl
	for _, m := range reCreateTable.FindAllStringSubmatch(ddlSource, -1) {
		out = append(out, tbl{name: m[1] + "." + m[2], body: m[3]})
	}
	// 索引：按语句逐条解析，才能拿到 WHERE
	byName := map[string]*tbl{}
	for i := range out {
		byName[out[i].name] = &out[i]
	}
	for _, stmt := range splitStmts(ddlSource) {
		up := strings.ToUpper(stmt)
		if !strings.Contains(up, "CREATE") || !strings.Contains(up, "INDEX") {
			continue
		}
		m := reCreateIndex.FindStringSubmatch(stmt)
		if m == nil {
			continue
		}
		key := m[3] + "." + m[4]
		t, ok := byName[key]
		if !ok {
			continue
		}
		var cols []string
		for _, c := range strings.Split(m[5], ",") {
			c = strings.TrimSpace(c)
			if c != "" {
				cols = append(cols, c)
			}
		}
		t.indexes = append(t.indexes, idx{
			name:   m[2],
			unique: strings.TrimSpace(m[1]) == "UNIQUE",
			cols:   cols,
			where:  extractWhere(stmt),
		})
	}
	return out
}

func splitStmts(s string) []string {
	var out []string
	var cur strings.Builder
	for _, r := range s {
		if r == ';' {
			out = append(out, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteRune(r)
	}
	if strings.TrimSpace(cur.String()) != "" {
		out = append(out, cur.String())
	}
	return out
}

func extractWhere(stmt string) string {
	up := strings.ToUpper(stmt)
	i := strings.Index(up, "INDEX")
	if i < 0 {
		return ""
	}
	rest := up[i:]
	if w := strings.Index(rest, " WHERE "); w >= 0 {
		return strings.TrimSpace(stmt[i+w+7:])
	}
	return ""
}

// columnExists 判断建表语句里是否有这一列。
// 不能用 ^\s*col\s 的行首匹配 —— 真实迁移里一行可能有多个列定义。
// 正确做法：按逗号/左括号切分成「列片段」，再看片段是否以列名开头。
func columnExists(body, col string) bool {
	for _, frag := range splitColumns(body) {
		f := strings.TrimSpace(frag)
		if f == col || strings.HasPrefix(f, col+" ") {
			return true
		}
	}
	return false
}

// splitColumns 把括号内的内容按顶层逗号切分（忽略括号里的逗号，如 NUMERIC(10,2)）
func splitColumns(body string) []string {
	body = reComment.ReplaceAllString(body, "")
	var out []string
	depth := 0
	cur := strings.Builder{}
	for _, r := range body {
		switch r {
		case '(':
			depth++
			cur.WriteRune(r)
		case ')':
			depth--
			cur.WriteRune(r)
		case ',':
			if depth == 0 {
				out = append(out, cur.String())
				cur.Reset()
			} else {
				cur.WriteRune(r)
			}
		default:
			cur.WriteRune(r)
		}
	}
	if strings.TrimSpace(cur.String()) != "" {
		out = append(out, cur.String())
	}
	return out
}

func columnDecl(body, col string) string {
	for _, frag := range splitColumns(body) {
		f := strings.TrimSpace(frag)
		if strings.HasPrefix(f, col+" ") {
			return f
		}
	}
	return ""
}

func orDefault(s, d string) string {
	if s == "" {
		return d
	}
	return s
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

// checkScript 是交付物：scripts/s3-check.sh
const checkScript = `#!/usr/bin/env bash
# scripts/s3-check.sh —— S3 阶段的机械门禁
#
# 用途：把「S3 学到的纪律」变成 CI 里会红的检查。
# 运行：bash scripts/s3-check.sh
# 退出码：0 = 全通过，1 = 有门禁未通过（CI 应该拦住这次提交）

set -uo pipefail
cd "$(dirname "$0")/.." || exit 1

FAILED=0
pass() { printf "  \033[32m✅\033[0m %s\n" "$1"; }
fail() { printf "  \033[31m❌\033[0m %s\n" "$1"; FAILED=$((FAILED+1)); }

MIG=server/migrations

echo "=== S3 结构门禁 ==="

# ---- 门禁 1：迁移文件命名 {code}_{seq}_{desc}.{up,down}.sql ----
echo "[1/8] 迁移文件命名"
BAD_NAME=$(find "$MIG" -name '*.sql' 2>/dev/null \
  | grep -vE '/[a-z]+_[0-9]{4}_[a-z0-9_]+\.(up|down)\.sql$' || true)
if [ -z "$BAD_NAME" ]; then
  pass "所有迁移文件命名符合 {code}_{seq}_{desc}"
else
  fail "命名不合规:"; echo "$BAD_NAME" | sed 's/^/       /'
fi

# ---- 门禁 2：up/down 成对 ----
echo "[2/8] up/down 成对"
MISSING_DOWN=$(for f in $(find "$MIG" -name '*.up.sql' 2>/dev/null); do
  d="${f%.up.sql}.down.sql"; [ -f "$d" ] || echo "$f 缺少 ${d##*/}"
done)
if [ -z "$MISSING_DOWN" ]; then
  pass "每个 up 都有对应的 down"
else
  fail "缺少 down:"; echo "$MISSING_DOWN" | sed 's/^/       /'
fi

# ---- 门禁 3：迁移只碰自己 schema 的表（归属门禁）----
echo "[3/8] 表归属（迁移只改本域的表）"
OWNER=$(find "$MIG" -mindepth 1 -maxdepth 1 -type d -exec basename {} \;)
BAD_OWNER=""
for code in $OWNER; do
  # 该目录下只允许出现 finance_ 或 homeos_ 前缀的表
  BAD_OWNER=$BAD_OWNER$(grep -ohiE '(CREATE|ALTER|DROP)[[:space:]]+TABLE[[:space:]]+(IF[[:space:]]+EXISTS[[:space:]]+)?[a-z]+\.[a-z_]+' \
    "$MIG/$code" 2>/dev/null \
    | grep -viE "\.(${code}_|schema_migrations)" || true)
done
if [ -z "$BAD_OWNER" ]; then
  pass "迁移只修改本域的表"
else
  fail "越界操作:"; echo "$BAD_OWNER" | sed 's/^/       /'
fi

# ---- 门禁 4：每张表都有 version + deleted_at ----
echo "[4/8] 元数据列（version / deleted_at）"
MISSING_META=""
for f in $(grep -rl 'CREATE TABLE' "$MIG" 2>/dev/null); do
  body=$(awk '/CREATE TABLE/,/^\\);/' "$f")
  echo "$body" | grep -qi 'version.*INTEGER.*DEFAULT 1'    || MISSING_META="$MISSING_META$f(缺version)\\n"
  echo "$body" | grep -qi 'deleted_at.*TIMESTAMPTZ'         || MISSING_META="$MISSING_META$f(缺deleted_at)\\n"
done
if [ -z "$MISSING_META" ]; then
  pass "所有表都有 version 和 deleted_at"
else
  fail "缺元数据列:"; echo -e "$MISSING_META" | sed 's/^/       /'
fi

# ---- 门禁 5：money 列必须是整数 ----
echo "[5/8] money 列类型"
BAD_MONEY=$(grep -rnE '\w*cents\s+(FLOAT|DOUBLE|REAL|NUMERIC|DECIMAL)' "$MIG" 2>/dev/null || true)
if [ -z "$BAD_MONEY" ]; then
  pass "所有 *_cents 列都是整数"
else
  fail "浮点 money 列:"; echo "$BAD_MONEY" | sed 's/^/       /'
fi

# ---- 门禁 6：唯一索引必须带软删条件 ----
echo "[6/8] 部分唯一索引"
BAD_UNIQ=$(grep -rn 'CREATE UNIQUE INDEX' "$MIG" 2>/dev/null \
  | grep -viE 'token_hash|email|phone' \
  | awk '{print}' | while read -r line; do :; done
# 逐个索引语句检查（多行索引要用 awk 提取完整语句）
BAD_UNIQ=$(awk '
  /CREATE UNIQUE INDEX/ { stmt=$0; inidx=1; next }
  inidx {
    stmt = stmt " " $0
    if ($0 ~ /;/) {
      if (stmt !~ /WHERE deleted_at IS NULL/ && stmt !~ /token_hash/ && stmt !~ /email/ && stmt !~ /phone/)
        print "  " stmt
      inidx=0; stmt=""
    }
  }
' $(find "$MIG" -name '*.sql' 2>/dev/null) || true)
if [ -z "$BAD_UNIQ" ]; then
  pass "业务唯一索引都带 WHERE deleted_at IS NULL"
else
  fail "缺软删条件的唯一索引:"; echo "$BAD_UNIQ" | sed 's/^/       /'
fi

# ---- 门禁 7：Go 代码里不得有裸 TIMESTAMP ----
echo "[7/8] 时间列带时区"
BAD_TS=$(grep -rn 'TIMESTAMP[^T]' "$MIG" --include='*.sql' 2>/dev/null | grep -v TIMESTAMPTZ || true)
if [ -z "$BAD_TS" ]; then
  pass "没有裸 TIMESTAMP（全部是 TIMESTAMPTZ）"
else
  fail "裸 TIMESTAMP:"; echo "$BAD_TS" | sed 's/^/       /'
fi

# ---- 门禁 8：仓储层查询必须带 family_id（人工确认清单）----
echo "[8/8] 仓储层租户过滤"
LEAKY=$(grep -rn 'store/.*\.Where(' server/internal/store/ 2>/dev/null \
  | grep -v 'family_id' | grep -viE '//|FindByPrimaryKey|\.Count\(\)' || true)
if [ -z "$LEAKY" ]; then
  pass "未发现漏加 family_id 的查询"
else
  fail "疑似漏加 family_id（需人工确认）:"
  echo "$LEAKY" | sed 's/^/       /'
fi

echo
if [ "$FAILED" -eq 0 ]; then
  echo "✅ S3 全部门禁通过"
  exit 0
else
  echo "❌ $FAILED 项门禁未通过"
  exit 1
fi`

